const DATA_LED_APPROVED = [{"id":"LED-20261009-0001","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e incisos I a V","number":"Art. 170, caput e incisos I a V","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nI - soberania nacional;\nII - propriedade privada;\nIII - função social da propriedade;\nIV - livre concorrência;\nV - defesa do consumidor;"],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nI - soberania nacional;\nII - propriedade privada;\nIII - função social da propriedade;\nIV - livre concorrência;\nV - defesa do consumidor;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 170, caput e incisos I a V, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0002","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e inciso VI","number":"Art. 170, caput e inciso VI","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVI - defesa do meio ambiente, inclusive mediante tratamento diferenciado conforme o impacto ambiental dos produtos e serviços e de seus processos de elaboração e prestação;"],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVI - defesa do meio ambiente, inclusive mediante tratamento diferenciado conforme o impacto ambiental dos produtos e de seus processos de elaboração e prestação;","answer":false,"explanation":"Errada. O art. 170, VI, prevê tratamento diferenciado conforme o impacto ambiental \"dos produtos e serviços e de seus processos de elaboração e prestação\". O enunciado omite \"serviços\", de modo que não reproduz o texto constitucional; a omissão, porém, não contradiz o dispositivo, e por isso a certificação é parcial (gabarito mantido pela falta de correspondência literal).","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado-parcial","basis":"texto legal conferido (Constituição Federal, Planalto); dispositivo ou precedente complementar ainda não conferido em fonte oficial","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0003","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e incisos VII e VIII","number":"Art. 170, caput e incisos VII e VIII","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVII - redução das desigualdades regionais e sociais;\nVIII - busca do pleno emprego;"],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nVII - redução das desigualdades regionais e sociais;\nVIII - busca do pleno emprego;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 170, caput e incisos VII e VIII, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0004","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, caput e inciso IX","number":"Art. 170, caput e inciso IX","title":"Constituição Federal de 1988","parts":["Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nIX - tratamento favorecido para as empresas de pequeno porte constituídas sob as leis brasileiras e que tenham sua sede e administração no País."],"origin":"authorial","question":{"statement":"Art. 170. A ordem econômica, fundada na valorização do trabalho humano e na livre iniciativa, tem por fim assegurar a todos existência digna, conforme os ditames da justiça social, observados os seguintes princípios:\nIX - tratamento favorecido para as empresas de pequeno porte constituídas sob as leis brasileiras e que tenham sua sede ou administração no País.","answer":false,"explanation":"Errada. O art. 170, IX, assegura tratamento favorecido às empresas de pequeno porte constituídas sob as leis brasileiras e que tenham sua sede e administração no País (requisitos cumulativos). O enunciado troca \"e\" por \"ou\", tornando alternativa a exigência.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0005","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 170, parágrafo único","number":"Art. 170, parágrafo único","title":"Constituição Federal de 1988","parts":["Parágrafo único. É assegurado a todos o livre exercício de qualquer atividade econômica, independentemente de autorização de órgãos públicos, salvo nos casos previstos em lei."],"origin":"authorial","question":{"statement":"Parágrafo único. É assegurado a todos o livre exercício de qualquer atividade econômica, independentemente de autorização de órgãos públicos, salvo nos casos previstos em regulamento.","answer":false,"explanation":"Errada. O parágrafo único do art. 170 assegura a todos o livre exercício de qualquer atividade econômica, independentemente de autorização de órgãos públicos, salvo nos casos previstos em lei. O enunciado substitui \"lei\" por \"regulamento\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0006","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 172, caput","number":"Art. 172, caput","title":"Constituição Federal de 1988","parts":["Art. 172. A lei disciplinará, com base no interesse nacional, os investimentos de capital estrangeiro, incentivará os reinvestimentos e regulará a remessa de lucros."],"origin":"authorial","question":{"statement":"Art. 172. A lei disciplinará, com base no interesse nacional, os investimentos de capital estrangeiro, incentivará os reinvestimentos e regulará a remessa de lucros.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 172, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0007","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, caput","number":"Art. 173, caput","title":"Constituição Federal de 1988","parts":["Art. 173. Ressalvados os casos previstos nesta Constituição, a exploração direta de atividade econômica pelo Estado só será permitida quando necessária aos imperativos da segurança nacional ou a relevante interesse coletivo, conforme definidos em lei."],"origin":"authorial","question":{"statement":"Art. 173. Ressalvados os casos previstos nesta Constituição, a exploração direta de atividade econômica pelo Estado só será permitida quando necessária aos imperativos da segurança nacional e a relevante interesse coletivo, conforme definidos em lei.","answer":false,"explanation":"Errada. O art. 173, caput, só permite a exploração direta de atividade econômica pelo Estado quando necessária aos imperativos da segurança nacional ou a relevante interesse coletivo, conforme definidos em lei. O enunciado troca \"ou\" por \"e\", exigindo os dois fundamentos cumulativamente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0008","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso I","number":"Art. 173, § 1º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nI - sua função social e formas de fiscalização pelo Estado e pela sociedade;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nI - sua função social e formas de fiscalização pelo Estado e pela sociedade;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 173, § 1º, caput e inciso I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0009","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso II","number":"Art. 173, § 1º, caput e inciso II","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nII - a sujeição ao regime jurídico próprio das empresas privadas, inclusive quanto aos direitos e obrigações civis, comerciais, trabalhistas e tributários;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nII - a sujeição ao regime jurídico próprio das entidades de direito público, inclusive quanto aos direitos e obrigações civis, comerciais, trabalhistas e tributários;","answer":false,"explanation":"Errada. O art. 173, § 1º, II, sujeita essas entidades ao regime jurídico próprio das empresas privadas, inclusive quanto aos direitos e obrigações civis, comerciais, trabalhistas e tributários. O enunciado fala em \"entidades de direito público\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0010","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso III","number":"Art. 173, § 1º, caput e inciso III","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIII - licitação e contratação de obras, serviços, compras e alienações, observados os princípios da administração pública;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIII - licitação e contratação de obras, serviços, compras e alienações, observados os princípios da administração pública;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 173, § 1º, caput e inciso III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0011","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso IV","number":"Art. 173, § 1º, caput e inciso IV","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIV - a constituição e o funcionamento dos conselhos de administração e fiscal, com a participação de acionistas minoritários;"],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nIV - a constituição e o funcionamento dos conselhos de administração e fiscal, com a participação de acionistas majoritários;","answer":false,"explanation":"Errada. O art. 173, § 1º, IV, prevê a constituição e o funcionamento dos conselhos de administração e fiscal, com a participação de acionistas minoritários. O enunciado fala em acionistas majoritários.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0012","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 1º, caput e inciso V","number":"Art. 173, § 1º, caput e inciso V","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nV - os mandatos, a avaliação de desempenho e a responsabilidade dos administradores."],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá o estatuto jurídico da empresa pública, da sociedade de economia mista e de suas subsidiárias que explorem atividade econômica de produção ou comercialização de bens ou de prestação de serviços, dispondo sobre:\nV - os mandatos, a avaliação de desempenho e a responsabilidade dos administradores.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 173, § 1º, caput e inciso V, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0013","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 2º","number":"Art. 173, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º As empresas públicas e as sociedades de economia mista não poderão gozar de privilégios fiscais não extensivos às do setor privado."],"origin":"authorial","question":{"statement":"§ 2º As empresas públicas e as sociedades de economia mista não poderão gozar de privilégios fiscais não extensivos às do setor privado.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 173, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0014","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 3º","number":"Art. 173, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º A lei regulamentará as relações da empresa pública com o Estado e a sociedade."],"origin":"authorial","question":{"statement":"§ 3º O decreto regulamentará as relações da empresa pública com o Estado e a sociedade.","answer":false,"explanation":"Errada. O art. 173, § 3º, dispõe que a lei regulamentará as relações da empresa pública com o Estado e a sociedade. O enunciado atribui a regulamentação a decreto.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0015","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 4º","number":"Art. 173, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A lei reprimirá o abuso do poder econômico que vise à dominação dos mercados, à eliminação da concorrência e ao aumento arbitrário dos lucros."],"origin":"authorial","question":{"statement":"§ 4º A lei reprimirá o abuso do poder econômico que vise à dominação dos mercados, à eliminação da concorrência e ao aumento arbitrário dos lucros.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 173, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0016","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 173, § 5º","number":"Art. 173, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º A lei, sem prejuízo da responsabilidade individual dos dirigentes da pessoa jurídica, estabelecerá a responsabilidade desta, sujeitando-a às punições compatíveis com sua natureza, nos atos praticados contra a ordem econômica e financeira e contra a economia popular."],"origin":"authorial","question":{"statement":"§ 5º A lei, em substituição à responsabilidade individual dos dirigentes da pessoa jurídica, estabelecerá a responsabilidade desta, sujeitando-a às punições compatíveis com sua natureza, nos atos praticados contra a ordem econômica e financeira e contra a economia popular.","answer":false,"explanation":"Errada. O art. 173, § 5º, prevê que a lei estabelecerá a responsabilidade da pessoa jurídica sem prejuízo da responsabilidade individual de seus dirigentes. O enunciado diz \"em substituição à\" responsabilidade individual, o que a afastaria.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0017","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, caput","number":"Art. 174, caput","title":"Constituição Federal de 1988","parts":["Art. 174. Como agente normativo e regulador da atividade econômica, o Estado exercerá, na forma da lei, as funções de fiscalização, incentivo e planejamento, sendo este determinante para o setor público e indicativo para o setor privado."],"origin":"authorial","question":{"statement":"Art. 174. Como agente normativo e regulador da atividade econômica, o Estado exercerá, na forma da lei, as funções de fiscalização, incentivo e planejamento, sendo este indicativo para o setor público e determinante para o setor privado.","answer":false,"explanation":"Errada. O art. 174, caput, atribui ao Estado, como agente normativo e regulador da atividade econômica, as funções de fiscalização, incentivo e planejamento, sendo este determinante para o setor público e indicativo para o setor privado. O enunciado inverte os adjetivos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0018","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, § 1º","number":"Art. 174, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A lei estabelecerá as diretrizes e bases do planejamento do desenvolvimento nacional equilibrado, o qual incorporará e compatibilizará os planos nacionais e regionais de desenvolvimento."],"origin":"authorial","question":{"statement":"§ 1º A lei estabelecerá as diretrizes e bases do planejamento do desenvolvimento nacional equilibrado, o qual incorporará e compatibilizará os planos nacionais e regionais de desenvolvimento.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 174, § 1º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0019","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, § 2º","number":"Art. 174, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º A lei apoiará e estimulará o cooperativismo e outras formas de associativismo."],"origin":"authorial","question":{"statement":"§ 2º A lei poderá apoiar e estimular o cooperativismo e outras formas de associativismo.","answer":false,"explanation":"Errada. O art. 174, § 2º, dispõe que a lei apoiará e estimulará o cooperativismo e outras formas de associativismo, em comando imperativo. O enunciado o transforma em faculdade (\"poderá apoiar e estimular\").","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0020","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, § 3º","number":"Art. 174, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros."],"origin":"authorial","question":{"statement":"§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 174, § 3º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0021","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 174, §§ 3º e 4º","number":"Art. 174, §§ 3º e 4º","title":"Constituição Federal de 1988","parts":["§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros.\n§ 4º As cooperativas a que se refere o parágrafo anterior terão prioridade na autorização ou concessão para pesquisa e lavra dos recursos e jazidas de minerais garimpáveis, nas áreas onde estejam atuando, e naquelas fixadas de acordo com o art. 21, XXV, na forma da lei."],"origin":"authorial","question":{"statement":"§ 3º O Estado favorecerá a organização da atividade garimpeira em cooperativas, levando em conta a proteção do meio ambiente e a promoção econômico-social dos garimpeiros.\n§ 4º As cooperativas a que se refere o parágrafo anterior terão exclusividade na autorização ou concessão para pesquisa e lavra dos recursos e jazidas de minerais garimpáveis, nas áreas onde estejam atuando, e naquelas fixadas de acordo com o art. 21, XXV, na forma da lei.","answer":false,"explanation":"Errada. O art. 174, § 4º, dá às cooperativas a que se refere o § 3º prioridade (e não exclusividade) na autorização ou concessão para pesquisa e lavra dos recursos e jazidas de minerais garimpáveis. O enunciado fala em exclusividade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0022","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, caput","number":"Art. 175, caput","title":"Constituição Federal de 1988","parts":["Art. 175. Incumbe ao Poder Público, na forma da lei, diretamente ou sob regime de concessão ou permissão, sempre através de licitação, a prestação de serviços públicos."],"origin":"authorial","question":{"statement":"Art. 175. Incumbe ao Poder Público, na forma da lei, diretamente ou sob regime de concessão ou autorização, sempre através de licitação, a prestação de serviços públicos.","answer":false,"explanation":"Errada. O art. 175, caput, incumbe ao Poder Público a prestação de serviços públicos, diretamente ou sob regime de concessão ou permissão, sempre através de licitação. O enunciado cita \"autorização\" no lugar de \"permissão\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0023","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, parágrafo único, inciso I","number":"Art. 175, parágrafo único, inciso I","title":"Constituição Federal de 1988","parts":["Parágrafo único. A lei disporá sobre:\nI - o regime das empresas concessionárias e permissionárias de serviços públicos, o caráter especial de seu contrato e de sua prorrogação, bem como as condições de caducidade, fiscalização e rescisão da concessão ou permissão;"],"origin":"authorial","question":{"statement":"Parágrafo único. A lei disporá sobre:\nI - o regime das empresas concessionárias e permissionárias de serviços públicos, o caráter especial de seu contrato e de sua prorrogação, bem como as condições de caducidade, fiscalização e rescisão da concessão ou permissão;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 175, parágrafo único, inciso I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0024","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, parágrafo único, incisos II e III","number":"Art. 175, parágrafo único, incisos II e III","title":"Constituição Federal de 1988","parts":["Parágrafo único. A lei disporá sobre:\nII - os direitos dos usuários;\nIII - política tarifária;"],"origin":"authorial","question":{"statement":"Parágrafo único. A lei disporá sobre:\nII - os direitos dos usuários;\nIII - política tarifária;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 175, parágrafo único, incisos II e III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0025","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 175, parágrafo único, inciso IV","number":"Art. 175, parágrafo único, inciso IV","title":"Constituição Federal de 1988","parts":["Parágrafo único. A lei disporá sobre:\nIV - a obrigação de manter serviço adequado."],"origin":"authorial","question":{"statement":"Parágrafo único. A lei disporá sobre:\nIV - a obrigação de manter serviço contínuo.","answer":false,"explanation":"Errada. O art. 175, parágrafo único, IV, determina que a lei disponha sobre a obrigação de manter serviço adequado. O enunciado substitui \"adequado\" por \"contínuo\", expressão que não consta do inciso.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0026","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, caput","number":"Art. 176, caput","title":"Constituição Federal de 1988","parts":["Art. 176. As jazidas, em lavra ou não, e demais recursos minerais e os potenciais de energia hidráulica constituem propriedade distinta da do solo, para efeito de exploração ou aproveitamento, e pertencem à União, garantida ao concessionário a propriedade do produto da lavra."],"origin":"authorial","question":{"statement":"Art. 176. As jazidas, em lavra ou não, e demais recursos minerais e os potenciais de energia hidráulica constituem propriedade distinta da do solo, para efeito de exploração ou aproveitamento, e pertencem à União, garantida ao concessionário a propriedade do produto da lavra.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 176, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0027","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 1º","number":"Art. 176, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A pesquisa e a lavra de recursos minerais e o aproveitamento dos potenciais a que se refere o \"caput\" deste artigo somente poderão ser efetuados mediante autorização ou concessão da União, no interesse nacional, por brasileiros ou empresa constituída sob as leis brasileiras e que tenha sua sede e administração no País, na forma da lei, que estabelecerá as condições específicas quando essas atividades se desenvolverem em faixa de fronteira ou terras indígenas."],"origin":"authorial","question":{"statement":"§ 1º A pesquisa e a lavra de recursos minerais e o aproveitamento dos potenciais a que se refere o \"caput\" deste artigo somente poderão ser efetuados mediante autorização ou concessão da União, no interesse nacional, por brasileiros ou empresa constituída sob as leis brasileiras e que tenha sua sede ou administração no País, na forma da lei, que estabelecerá as condições específicas quando essas atividades se desenvolverem em faixa de fronteira ou terras indígenas.","answer":false,"explanation":"Errada. O art. 176, § 1º, exige empresa constituída sob as leis brasileiras e que tenha sua sede e administração no País (requisitos cumulativos). O enunciado troca \"e\" por \"ou\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0028","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 2º","number":"Art. 176, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º É assegurada participação ao proprietário do solo nos resultados da lavra, na forma e no valor que dispuser a lei."],"origin":"authorial","question":{"statement":"§ 2º É assegurada participação ao Município onde se situa a jazida nos resultados da lavra, na forma e no valor que dispuser a lei.","answer":false,"explanation":"Errada. O art. 176, § 2º, assegura participação ao proprietário do solo nos resultados da lavra, na forma e no valor que dispuser a lei. O enunciado a atribui ao Município onde se situa a jazida.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0029","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 3º","number":"Art. 176, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º A autorização de pesquisa será sempre por prazo determinado, e as autorizações e concessões previstas neste artigo não poderão ser cedidas ou transferidas, total ou parcialmente, sem prévia anuência do poder concedente."],"origin":"authorial","question":{"statement":"§ 3º A autorização de pesquisa será sempre por prazo determinado, e as autorizações e concessões previstas neste artigo não poderão ser cedidas ou transferidas, total ou parcialmente, sem prévia anuência do poder concedente.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 176, § 3º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0030","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 176, § 4º","number":"Art. 176, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Não dependerá de autorização ou concessão o aproveitamento do potencial de energia renovável de capacidade reduzida."],"origin":"authorial","question":{"statement":"§ 4º Não dependerá de autorização ou concessão o aproveitamento do potencial de energia renovável de capacidade reduzida.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 176, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0031","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, caput e incisos I e II","number":"Art. 177, caput e incisos I e II","title":"Constituição Federal de 1988","parts":["Art. 177. Constituem monopólio da União:\nI - a pesquisa e a lavra das jazidas de petróleo e gás natural e outros hidrocarbonetos fluidos;\nII - a refinação do petróleo nacional ou estrangeiro;"],"origin":"authorial","question":{"statement":"Art. 177. Constituem monopólio da União:\nI - a pesquisa e a lavra das jazidas de petróleo e gás natural e outros hidrocarbonetos fluidos;\nII - a refinação do petróleo nacional ou estrangeiro;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 177, caput e incisos I e II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0032","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, caput e incisos III e IV","number":"Art. 177, caput e incisos III e IV","title":"Constituição Federal de 1988","parts":["Art. 177. Constituem monopólio da União:\nIII - a importação e exportação dos produtos e derivados básicos resultantes das atividades previstas nos incisos anteriores;\nIV - o transporte marítimo do petróleo bruto de origem nacional ou de derivados básicos de petróleo produzidos no País, bem assim o transporte, por meio de conduto, de petróleo bruto, seus derivados e gás natural de qualquer origem;"],"origin":"authorial","question":{"statement":"Art. 177. Constituem monopólio da União:\nIII - a importação e exportação dos produtos e derivados básicos resultantes das atividades previstas nos incisos anteriores;\nIV - o transporte marítimo do petróleo bruto de qualquer origem ou de derivados básicos de petróleo produzidos no País, bem assim o transporte, por meio de conduto, de petróleo bruto, seus derivados e gás natural de qualquer origem;","answer":false,"explanation":"Errada. O art. 177, IV, inclui no monopólio da União o transporte marítimo do petróleo bruto de origem nacional (e não de qualquer origem) ou de derivados básicos de petróleo produzidos no País; a expressão \"de qualquer origem\" qualifica apenas o transporte por conduto. O enunciado estende essa expressão ao transporte marítimo do petróleo bruto.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0033","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, caput e inciso V","number":"Art. 177, caput e inciso V","title":"Constituição Federal de 1988","parts":["Art. 177. Constituem monopólio da União:\nV - a pesquisa, a lavra, o enriquecimento, o reprocessamento, a industrialização e o comércio de minérios e minerais nucleares e seus derivados, com exceção dos radioisótopos cuja produção, comercialização e utilização poderão ser autorizadas sob regime de permissão, conforme as alíneas b e c do inciso XXIII do caput do art. 21 desta Constituição Federal."],"origin":"authorial","question":{"statement":"Art. 177. Constituem monopólio da União:\nV - a pesquisa, a lavra, o enriquecimento, o reprocessamento, a industrialização e o comércio de minérios e minerais nucleares e seus derivados, com exceção dos radioisótopos cuja produção, comercialização e utilização poderão ser autorizadas sob regime de permissão, conforme as alíneas b e c do inciso XXIII do caput do art. 21 desta Constituição Federal.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 177, caput e inciso V, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0034","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 1º","number":"Art. 177, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A União poderá contratar com empresas estatais ou privadas a realização das atividades previstas nos incisos I a IV deste artigo observadas as condições estabelecidas em lei."],"origin":"authorial","question":{"statement":"§ 1º A União poderá contratar somente com empresas estatais a realização das atividades previstas nos incisos I a IV deste artigo observadas as condições estabelecidas em lei.","answer":false,"explanation":"Errada. O art. 177, § 1º, permite que a União contrate com empresas estatais ou privadas a realização das atividades dos incisos I a IV, observadas as condições legais. O enunciado limita a contratação \"somente\" a empresas estatais.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0035","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 2º, caput e inciso I","number":"Art. 177, § 2º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 2º A lei a que se refere o § 1º disporá sobre:\nI - a garantia do fornecimento dos derivados de petróleo em todo o território nacional;"],"origin":"authorial","question":{"statement":"§ 2º A lei a que se refere o § 1º disporá sobre:\nI - a garantia do fornecimento dos derivados de petróleo em todo o território nacional;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 177, § 2º, caput e inciso I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0036","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 2º, caput e incisos II e III","number":"Art. 177, § 2º, caput e incisos II e III","title":"Constituição Federal de 1988","parts":["§ 2º A lei a que se refere o § 1º disporá sobre:\nII - as condições de contratação;\nIII - a estrutura e atribuições do órgão regulador do monopólio da União;"],"origin":"authorial","question":{"statement":"§ 2º A lei a que se refere o § 1º disporá sobre:\nII - as condições de contratação;\nIII - a estrutura e atribuições do órgão executor do monopólio da União;","answer":false,"explanation":"Errada. O art. 177, § 2º, III, manda a lei dispor sobre a estrutura e as atribuições do órgão regulador do monopólio da União. O enunciado fala em órgão \"executor\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0037","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 3º","number":"Art. 177, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º A lei disporá sobre o transporte e a utilização de materiais radioativos no território nacional."],"origin":"authorial","question":{"statement":"§ 3º A lei disporá sobre o transporte e a utilização de materiais radioativos no território nacional.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 177, § 3º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0038","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso I, alínea a","number":"Art. 177, § 4º, caput, inciso I, alínea a","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\na) diferenciada por produto ou uso;"],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\na) diferenciada por produto ou uso;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 177, § 4º, caput, inciso I, alínea a, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0039","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso I, alínea b","number":"Art. 177, § 4º, caput, inciso I, alínea b","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\nb) reduzida e restabelecida por ato do Poder Executivo, não se lhe aplicando o disposto no art. 150,III, b;"],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nI - a alíquota da contribuição poderá ser:\nb) reduzida e restabelecida por lei específica, não se lhe aplicando o disposto no art. 150,III, b;","answer":false,"explanation":"Errada. O art. 177, § 4º, I, b, admite que a alíquota da contribuição seja reduzida e restabelecida por ato do Poder Executivo, não se lhe aplicando o disposto no art. 150, III, b. O enunciado exige \"lei específica\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0040","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso II, alínea a","number":"Art. 177, § 4º, caput, inciso II, alínea a","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\na) ao pagamento de subsídios a preços ou transporte de álcool combustível, gás natural e seus derivados e derivados de petróleo;"],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\na) ao pagamento de subsídios apenas ao transporte de álcool combustível, gás natural e seus derivados e derivados de petróleo;","answer":false,"explanation":"Errada. O art. 177, § 4º, II, a, destina os recursos ao pagamento de subsídios a preços ou transporte de álcool combustível, gás natural e seus derivados e derivados de petróleo. O enunciado restringe a destinação \"apenas ao transporte\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0041","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso II, alíneas b e c","number":"Art. 177, § 4º, caput, inciso II, alíneas b e c","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nb) ao financiamento de projetos ambientais relacionados com a indústria do petróleo e do gás;\nc) ao financiamento de programas de infra-estrutura de transportes."],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nb) ao financiamento de projetos ambientais relacionados com a indústria do petróleo e do gás;\nc) ao financiamento de programas de infra-estrutura de transportes.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 177, § 4º, caput, inciso II, alíneas b e c, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0042","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 177, § 4º, caput, inciso II, alínea d","number":"Art. 177, § 4º, caput, inciso II, alínea d","title":"Constituição Federal de 1988","parts":["§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nd) ao pagamento de subsídios a tarifas de transporte público coletivo de passageiros."],"origin":"authorial","question":{"statement":"§ 4º A lei que instituir contribuição de intervenção no domínio econômico relativa às atividades de importação ou comercialização de petróleo e seus derivados, gás natural e seus derivados e álcool combustível deverá atender aos seguintes requisitos:\nII - os recursos arrecadados serão destinados:\nd) ao pagamento de subsídios a tarifas de transporte privado de passageiros.","answer":false,"explanation":"Errada. O art. 177, § 4º, II, d, destina recursos ao pagamento de subsídios a tarifas de transporte público coletivo de passageiros. O enunciado fala em transporte \"privado\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0043","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 178, caput","number":"Art. 178, caput","title":"Constituição Federal de 1988","parts":["Art. 178. A lei disporá sobre a ordenação dos transportes aéreo, aquático e terrestre, devendo, quanto à ordenação do transporte internacional, observar os acordos firmados pela União, atendido o princípio da reciprocidade."],"origin":"authorial","question":{"statement":"Art. 178. A lei disporá sobre a ordenação dos transportes aéreo, aquático e terrestre, devendo, quanto à ordenação do transporte internacional, observar os acordos firmados pelos Estados, atendido o princípio da reciprocidade.","answer":false,"explanation":"Errada. O art. 178, caput, manda observar, quanto à ordenação do transporte internacional, os acordos firmados pela União, atendido o princípio da reciprocidade. O enunciado atribui os acordos aos Estados.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0044","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 178, parágrafo único","number":"Art. 178, parágrafo único","title":"Constituição Federal de 1988","parts":["Parágrafo único. Na ordenação do transporte aquático, a lei estabelecerá as condições em que o transporte de mercadorias na cabotagem e a navegação interior poderão ser feitos por embarcações estrangeiras."],"origin":"authorial","question":{"statement":"Parágrafo único. Na ordenação do transporte aquático, a lei estabelecerá as condições em que o transporte de mercadorias na cabotagem e a navegação interior poderão ser feitos por embarcações estrangeiras.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 178, parágrafo único, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0045","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 179, caput","number":"Art. 179, caput","title":"Constituição Federal de 1988","parts":["Art. 179. A União, os Estados, o Distrito Federal e os Municípios dispensarão às microempresas e às empresas de pequeno porte, assim definidas em lei, tratamento jurídico diferenciado, visando a incentivá-las pela simplificação de suas obrigações administrativas, tributárias, previdenciárias e creditícias, ou pela eliminação ou redução destas por meio de lei."],"origin":"authorial","question":{"statement":"Art. 179. A União, os Estados, o Distrito Federal e os Municípios dispensarão às microempresas e às empresas de pequeno porte, assim definidas em lei, tratamento jurídico diferenciado, visando a incentivá-las pela simplificação de suas obrigações administrativas, tributárias, previdenciárias e creditícias, ou pela eliminação ou redução destas por meio de decreto.","answer":false,"explanation":"Errada. O art. 179, caput, prevê a simplificação das obrigações das microempresas e empresas de pequeno porte, ou sua eliminação ou redução, por meio de lei. O enunciado diz \"decreto\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0046","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 180, caput","number":"Art. 180, caput","title":"Constituição Federal de 1988","parts":["Art. 180. A União, os Estados, o Distrito Federal e os Municípios promoverão e incentivarão o turismo como fator de desenvolvimento social e econômico."],"origin":"authorial","question":{"statement":"Art. 180. A União, os Estados, o Distrito Federal e os Municípios promoverão e incentivarão o turismo como fator de desenvolvimento social e econômico.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 180, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0047","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 181, caput","number":"Art. 181, caput","title":"Constituição Federal de 1988","parts":["Art. 181. O atendimento de requisição de documento ou informação de natureza comercial, feita por autoridade administrativa ou judiciária estrangeira, a pessoa física ou jurídica residente ou domiciliada no País dependerá de autorização do Poder competente."],"origin":"authorial","question":{"statement":"Art. 181. O atendimento de requisição de documento ou informação de natureza comercial, feita por autoridade administrativa ou judiciária estrangeira, a pessoa física ou jurídica residente ou domiciliada no exterior dependerá de autorização do Poder competente.","answer":false,"explanation":"Errada. O art. 181, caput, subordina à autorização do Poder competente o atendimento de requisição de documento ou informação de natureza comercial, feita por autoridade administrativa ou judiciária estrangeira, a pessoa física ou jurídica residente ou domiciliada no País. O enunciado fala em residente ou domiciliada no \"exterior\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0048","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 193, caput","number":"Art. 193, caput","title":"Constituição Federal de 1988","parts":["Art. 193. A ordem social tem como base o primado do trabalho, e como objetivo o bem-estar e a justiça sociais."],"origin":"authorial","question":{"statement":"Art. 193. A ordem social tem como base o primado do trabalho, e como objetivo o bem-estar e a justiça sociais.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 193, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0049","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 193, parágrafo único","number":"Art. 193, parágrafo único","title":"Constituição Federal de 1988","parts":["Parágrafo único. O Estado exercerá a função de planejamento das políticas sociais, assegurada, na forma da lei, a participação da sociedade nos processos de formulação, de monitoramento, de controle e de avaliação dessas políticas."],"origin":"authorial","question":{"statement":"Parágrafo único. O Estado exercerá a função de planejamento das políticas sociais, assegurada, independentemente de lei, a participação da sociedade nos processos de formulação, de monitoramento, de controle e de avaliação dessas políticas.","answer":false,"explanation":"Errada. O art. 193, parágrafo único, assegura a participação da sociedade nos processos de formulação, monitoramento, controle e avaliação das políticas sociais na forma da lei. O enunciado diz \"independentemente de lei\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0050","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, caput","number":"Art. 194, caput","title":"Constituição Federal de 1988","parts":["Art. 194. A seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social."],"origin":"authorial","question":{"statement":"Art. 194. A seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 194, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0051","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso I","number":"Art. 194, parágrafo único, inciso I","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nI - universalidade da cobertura e do atendimento;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nI - universalidade da cobertura e seletividade do atendimento;","answer":false,"explanation":"Errada. O art. 194, parágrafo único, I, prevê universalidade da cobertura e do atendimento; a seletividade é objetivo do inciso III (seletividade e distributividade). O enunciado insere \"seletividade\" no inciso I.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0052","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso II","number":"Art. 194, parágrafo único, inciso II","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nII - uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nII - uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 194, parágrafo único, inciso II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0053","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso III","number":"Art. 194, parágrafo único, inciso III","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIII - seletividade e distributividade na prestação dos benefícios e serviços;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIII - uniformidade e distributividade na prestação dos benefícios e serviços;","answer":false,"explanation":"Errada. O art. 194, parágrafo único, III, prevê seletividade e distributividade na prestação dos benefícios e serviços; a uniformidade integra o inciso II (uniformidade e equivalência dos benefícios e serviços às populações urbanas e rurais). O enunciado troca \"seletividade\" por \"uniformidade\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0054","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso IV","number":"Art. 194, parágrafo único, inciso IV","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIV - irredutibilidade do valor dos benefícios;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nIV - irredutibilidade do valor dos benefícios;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 194, parágrafo único, inciso IV, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0055","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso V","number":"Art. 194, parágrafo único, inciso V","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nV - eqüidade na forma de participação no custeio;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nV - igualdade na forma de participação no custeio;","answer":false,"explanation":"Errada. O art. 194, parágrafo único, V, prevê eqüidade na forma de participação no custeio. O enunciado troca o termo por \"igualdade\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0056","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso VI","number":"Art. 194, parágrafo único, inciso VI","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVI - diversidade da base de financiamento, identificando-se, em rubricas contábeis específicas para cada área, as receitas e as despesas vinculadas a ações de saúde, previdência e assistência social, preservado o caráter contributivo da previdência social;"],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVI - diversidade da base de financiamento, identificando-se, em rubricas contábeis específicas para cada área, as receitas e as despesas vinculadas a ações de saúde, previdência e assistência social, preservado o caráter contributivo da previdência social;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 194, parágrafo único, inciso VI, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0057","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 194, parágrafo único, inciso VII","number":"Art. 194, parágrafo único, inciso VII","title":"Constituição Federal de 1988","parts":["Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVII - caráter democrático e descentralizado da administração, mediante gestão quadripartite, com participação dos trabalhadores, dos empregadores, dos aposentados e do Governo nos órgãos colegiados."],"origin":"authorial","question":{"statement":"Parágrafo único. Compete ao Poder Público, nos termos da lei, organizar a seguridade social, com base nos seguintes objetivos:\nVII - caráter democrático e descentralizado da administração, mediante gestão tripartite, com participação dos trabalhadores, dos empregadores, dos aposentados e do Governo nos órgãos colegiados.","answer":false,"explanation":"Errada. O art. 194, parágrafo único, VII, prevê gestão quadripartite, com participação dos trabalhadores, dos empregadores, dos aposentados e do Governo nos órgãos colegiados. O enunciado diz \"tripartite\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0058","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 196, caput","number":"Art. 196, caput","title":"Constituição Federal de 1988","parts":["Art. 196. A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação."],"origin":"authorial","question":{"statement":"Art. 196. A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e seletivo às ações e serviços para sua promoção, proteção e recuperação.","answer":false,"explanation":"Errada. O art. 196, caput, assegura acesso universal e igualitário às ações e serviços para promoção, proteção e recuperação da saúde. O enunciado troca \"igualitário\" por \"seletivo\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0059","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 197, caput","number":"Art. 197, caput","title":"Constituição Federal de 1988","parts":["Art. 197. São de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor, nos termos da lei, sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado."],"origin":"authorial","question":{"statement":"Art. 197. São de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor, nos termos da lei, sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 197, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0060","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, caput e inciso I","number":"Art. 198, caput e inciso I","title":"Constituição Federal de 1988","parts":["Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nI - descentralização, com direção única em cada esfera de governo;"],"origin":"authorial","question":{"statement":"Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nI - descentralização, com direção centralizada na União;","answer":false,"explanation":"Errada. O art. 198, I, prevê descentralização, com direção única em cada esfera de governo. O enunciado fala em direção centralizada na União.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0061","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, caput e inciso II","number":"Art. 198, caput e inciso II","title":"Constituição Federal de 1988","parts":["Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nII - atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais;"],"origin":"authorial","question":{"statement":"Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nII - atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, caput e inciso II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0062","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, caput e inciso III","number":"Art. 198, caput e inciso III","title":"Constituição Federal de 1988","parts":["Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nIII - participação da comunidade."],"origin":"authorial","question":{"statement":"Art. 198. As ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes:\nIII - participação dos prestadores privados.","answer":false,"explanation":"Errada. O art. 198, III, prevê a participação da comunidade como diretriz do sistema único de saúde. O enunciado fala em participação dos prestadores privados.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0063","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 1º","number":"Art. 198, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º O sistema único de saúde será financiado, nos termos do art. 195, com recursos do orçamento da seguridade social, da União, dos Estados, do Distrito Federal e dos Municípios, além de outras fontes."],"origin":"authorial","question":{"statement":"§ 1º O sistema único de saúde será financiado, nos termos do art. 195, com recursos do orçamento da seguridade social, da União, dos Estados, do Distrito Federal e dos Municípios, vedadas outras fontes.","answer":false,"explanation":"Errada. O art. 198, § 1º, dispõe que o sistema único de saúde será financiado, além de outras fontes, com recursos do orçamento da seguridade social, da União, dos Estados, do Distrito Federal e dos Municípios. O enunciado diz que outras fontes são vedadas.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0064","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 2º, caput e inciso I","number":"Art. 198, § 2º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nI - no caso da União, a receita corrente líquida do respectivo exercício financeiro, não podendo ser inferior a 15% (quinze por cento);"],"origin":"authorial","question":{"statement":"§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nI - no caso da União, a receita corrente líquida do respectivo exercício financeiro, não podendo ser inferior a 15% (quinze por cento);","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 2º, caput e inciso I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0065","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 2º, caput e inciso II","number":"Art. 198, § 2º, caput e inciso II","title":"Constituição Federal de 1988","parts":["§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nII - no caso dos Estados e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 155 e 156-A e dos recursos de que tratam os arts. 157 e 159, I, \"a\", e II, deduzidas as parcelas que forem transferidas aos respectivos Municípios;"],"origin":"authorial","question":{"statement":"§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nII - no caso dos Estados e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 155 e 156-A e dos recursos de que tratam os arts. 157 e 159, I, \"a\", e II, incluídas as parcelas que forem transferidas aos respectivos Municípios;","answer":false,"explanation":"Errada. O art. 198, § 2º, II, calcula o mínimo dos Estados e do Distrito Federal sobre o produto da arrecadação dos impostos a que se refere o art. 155 e dos recursos de que tratam os arts. 157 e 159, I, a, e II, deduzidas as parcelas transferidas aos respectivos Municípios. O enunciado diz \"incluídas\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0066","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 2º, caput e inciso III","number":"Art. 198, § 2º, caput e inciso III","title":"Constituição Federal de 1988","parts":["§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nIII - no caso dos Municípios e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 156 e 156-A e dos recursos de que tratam os arts. 158 e 159, I, \"b\", e § 3º."],"origin":"authorial","question":{"statement":"§ 2º A União, os Estados, o Distrito Federal e os Municípios aplicarão, anualmente, em ações e serviços públicos de saúde recursos mínimos derivados da aplicação de percentuais calculados sobre:\nIII - no caso dos Municípios e do Distrito Federal, o produto da arrecadação dos impostos a que se referem os arts. 156 e 156-A e dos recursos de que tratam os arts. 158 e 159, I, \"b\", e § 3º.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 2º, caput e inciso III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0067","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 3º, caput e inciso I","number":"Art. 198, § 3º, caput e inciso I","title":"Constituição Federal de 1988","parts":["§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nI - os percentuais de que tratam os incisos II e III do § 2º;"],"origin":"authorial","question":{"statement":"§ 3º Lei complementar, que será reavaliada pelo menos a cada dez anos, estabelecerá:\nI - os percentuais de que tratam os incisos II e III do § 2º;","answer":false,"explanation":"Errada. O art. 198, § 3º, prevê lei complementar que será reavaliada pelo menos a cada cinco anos. O enunciado diz dez anos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0068","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 3º, caput e inciso II","number":"Art. 198, § 3º, caput e inciso II","title":"Constituição Federal de 1988","parts":["§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nII – os critérios de rateio dos recursos da União vinculados à saúde destinados aos Estados, ao Distrito Federal e aos Municípios, e dos Estados destinados a seus respectivos Municípios, objetivando a progressiva redução das disparidades regionais;"],"origin":"authorial","question":{"statement":"§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nII – os critérios de rateio dos recursos da União vinculados à saúde destinados aos Estados, ao Distrito Federal e aos Municípios, e dos Estados destinados a seus respectivos Municípios, objetivando a progressiva redução das disparidades regionais;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 3º, caput e inciso II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0069","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 3º, caput e inciso III","number":"Art. 198, § 3º, caput e inciso III","title":"Constituição Federal de 1988","parts":["§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nIII – as normas de fiscalização, avaliação e controle das despesas com saúde nas esferas federal, estadual, distrital e municipal;"],"origin":"authorial","question":{"statement":"§ 3º Lei complementar, que será reavaliada pelo menos a cada cinco anos, estabelecerá:\nIII – as normas de fiscalização, avaliação e controle das despesas com saúde nas esferas federal, estadual, distrital e municipal;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 3º, caput e inciso III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0070","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 4º","number":"Art. 198, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Os gestores locais do sistema único de saúde poderão admitir agentes comunitários de saúde e agentes de combate às endemias por meio de processo seletivo público, de acordo com a natureza e complexidade de suas atribuições e requisitos específicos para sua atuação."],"origin":"authorial","question":{"statement":"§ 4º Os gestores locais do sistema único de saúde poderão admitir agentes comunitários de saúde e agentes de combate às endemias por meio de concurso público de provas e títulos, de acordo com a natureza e complexidade de suas atribuições e requisitos específicos para sua atuação.","answer":false,"explanation":"Errada. O art. 198, § 4º, autoriza os gestores locais do SUS a admitir agentes comunitários de saúde e agentes de combate às endemias por meio de processo seletivo público. O enunciado exige concurso público de provas e títulos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0071","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 5º","number":"Art. 198, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º Lei federal disporá sobre o regime jurídico, o piso salarial profissional nacional, as diretrizes para os Planos de Carreira e a regulamentação das atividades de agente comunitário de saúde e agente de combate às endemias, competindo à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios, para o cumprimento do referido piso salarial."],"origin":"authorial","question":{"statement":"§ 5º Lei federal disporá sobre o regime jurídico, o piso salarial profissional nacional, as diretrizes para os Planos de Carreira e a regulamentação das atividades de agente comunitário de saúde e agente de combate às endemias, competindo à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios, para o cumprimento do referido piso salarial.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 5º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0072","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 6º","number":"Art. 198, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º Além das hipóteses previstas no § 1º do art. 41 e no § 4º do art. 169 da Constituição Federal, o servidor que exerça funções equivalentes às de agente comunitário de saúde ou de agente de combate às endemias poderá perder o cargo em caso de descumprimento dos requisitos específicos, fixados em lei, para o seu exercício."],"origin":"authorial","question":{"statement":"§ 6º Além das hipóteses previstas no § 1º do art. 41 e no § 4º do art. 169 da Constituição Federal, o servidor que exerça funções equivalentes às de agente comunitário de saúde ou de agente de combate às endemias poderá perder o cargo em caso de descumprimento dos requisitos específicos, fixados em regulamento, para o seu exercício.","answer":false,"explanation":"Errada. O art. 198, § 6º, admite a perda do cargo em caso de descumprimento dos requisitos específicos, fixados em lei, para o exercício da função. O enunciado diz \"regulamento\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0073","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 7º","number":"Art. 198, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias fica sob responsabilidade da União, e cabe aos Estados, ao Distrito Federal e aos Municípios estabelecer, além de outros consectários e vantagens, incentivos, auxílios, gratificações e indenizações, a fim de valorizar o trabalho desses profissionais."],"origin":"authorial","question":{"statement":"§ 7º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias fica sob responsabilidade da União, e cabe aos Estados, ao Distrito Federal e aos Municípios estabelecer, além de outros consectários e vantagens, incentivos, auxílios, gratificações e indenizações, a fim de valorizar o trabalho desses profissionais.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 7º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0074","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 8º","number":"Art. 198, § 8º","title":"Constituição Federal de 1988","parts":["§ 8º Os recursos destinados ao pagamento do vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias serão consignados no orçamento geral da União com dotação própria e exclusiva."],"origin":"authorial","question":{"statement":"§ 8º Os recursos destinados ao pagamento do vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias serão consignados no orçamento geral dos Municípios com dotação própria e exclusiva.","answer":false,"explanation":"Errada. O art. 198, § 8º, determina que os recursos destinados ao pagamento do vencimento dos agentes sejam consignados no orçamento geral da União, com dotação própria e exclusiva. O enunciado diz \"dos Municípios\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0075","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 9º","number":"Art. 198, § 9º","title":"Constituição Federal de 1988","parts":["§ 9º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias não será inferior a 2 (dois) salários mínimos, repassados pela União aos Municípios, aos Estados e ao Distrito Federal."],"origin":"authorial","question":{"statement":"§ 9º O vencimento dos agentes comunitários de saúde e dos agentes de combate às endemias não será inferior a 2 (dois) salários mínimos, repassados pela União aos Municípios, aos Estados e ao Distrito Federal.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 9º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0076","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 10","number":"Art. 198, § 10","title":"Constituição Federal de 1988","parts":["§ 10. Os agentes comunitários de saúde e os agentes de combate às endemias terão também, em razão dos riscos inerentes às funções desempenhadas, aposentadoria especial e, somado aos seus vencimentos, adicional de insalubridade."],"origin":"authorial","question":{"statement":"§ 10. Os agentes comunitários de saúde e os agentes de combate às endemias terão também, em razão dos riscos inerentes às funções desempenhadas, aposentadoria especial e, somado aos seus vencimentos, adicional de periculosidade.","answer":false,"explanation":"Errada. O art. 198, § 10, prevê aposentadoria especial e, somado aos vencimentos, adicional de insalubridade em razão dos riscos inerentes às funções. O enunciado troca o adicional por \"periculosidade\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0077","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 11","number":"Art. 198, § 11","title":"Constituição Federal de 1988","parts":["§ 11. Os recursos financeiros repassados pela União aos Estados, ao Distrito Federal e aos Municípios para pagamento do vencimento ou de qualquer outra vantagem dos agentes comunitários de saúde e dos agentes de combate às endemias não serão objeto de inclusão no cálculo para fins do limite de despesa com pessoal."],"origin":"authorial","question":{"statement":"§ 11. Os recursos financeiros repassados pela União aos Estados, ao Distrito Federal e aos Municípios para pagamento do vencimento ou de qualquer outra vantagem dos agentes comunitários de saúde e dos agentes de combate às endemias não serão objeto de inclusão no cálculo para fins do limite de despesa com pessoal.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 11, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0078","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 12","number":"Art. 198, § 12","title":"Constituição Federal de 1988","parts":["§ 12. Lei federal instituirá pisos salariais profissionais nacionais para o enfermeiro, o técnico de enfermagem, o auxiliar de enfermagem e a parteira, a serem observados por pessoas jurídicas de direito público e de direito privado."],"origin":"authorial","question":{"statement":"§ 12. Lei federal instituirá pisos salariais profissionais nacionais para o enfermeiro, o técnico de enfermagem, o auxiliar de enfermagem e a parteira, a serem observados apenas por pessoas jurídicas de direito público.","answer":false,"explanation":"Errada. O art. 198, § 12, determina que os pisos salariais das categorias de enfermeiro, técnico de enfermagem, auxiliar de enfermagem e parteira sejam observados por pessoas jurídicas de direito público e de direito privado. O enunciado limita a observância \"apenas\" às de direito público.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0079","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 13","number":"Art. 198, § 13","title":"Constituição Federal de 1988","parts":["§ 13. A União, os Estados, o Distrito Federal e os Municípios, até o final do exercício financeiro em que for publicada a lei de que trata o § 12 deste artigo, adequarão a remuneração dos cargos ou dos respectivos planos de carreiras, quando houver, de modo a atender aos pisos estabelecidos para cada categoria profissional."],"origin":"authorial","question":{"statement":"§ 13. A União, os Estados, o Distrito Federal e os Municípios, até o final do exercício financeiro em que for publicada a lei de que trata o § 12 deste artigo, adequarão a remuneração dos cargos ou dos respectivos planos de carreiras, quando houver, de modo a atender aos pisos estabelecidos para cada categoria profissional.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 13, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0080","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 14","number":"Art. 198, § 14","title":"Constituição Federal de 1988","parts":["§ 14. Compete à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo."],"origin":"authorial","question":{"statement":"§ 14. Compete à União, nos termos da lei, prestar assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 70% (setenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo.","answer":false,"explanation":"Errada. O art. 198, § 14, refere-se aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde. O enunciado fala em 70% (setenta por cento).","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0081","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 198, § 15","number":"Art. 198, § 15","title":"Constituição Federal de 1988","parts":["§ 15. Os recursos federais destinados aos pagamentos da assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo serão consignados no orçamento geral da União com dotação própria e exclusiva."],"origin":"authorial","question":{"statement":"§ 15. Os recursos federais destinados aos pagamentos da assistência financeira complementar aos Estados, ao Distrito Federal e aos Municípios e às entidades filantrópicas, bem como aos prestadores de serviços contratualizados que atendam, no mínimo, 60% (sessenta por cento) de seus pacientes pelo sistema único de saúde, para o cumprimento dos pisos salariais de que trata o § 12 deste artigo serão consignados no orçamento geral da União com dotação própria e exclusiva.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 198, § 15, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0082","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, caput","number":"Art. 199, caput","title":"Constituição Federal de 1988","parts":["Art. 199. A assistência à saúde é livre à iniciativa privada."],"origin":"authorial","question":{"statement":"Art. 199. A assistência à saúde é livre à iniciativa privada.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 199, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0083","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 1º","number":"Art. 199, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º As instituições privadas poderão participar de forma complementar do sistema único de saúde, segundo diretrizes deste, mediante contrato de direito público ou convênio, tendo preferência as entidades filantrópicas e as sem fins lucrativos."],"origin":"authorial","question":{"statement":"§ 1º As instituições privadas poderão participar de forma substitutiva do sistema único de saúde, segundo diretrizes deste, mediante contrato de direito público ou convênio, tendo preferência as entidades filantrópicas e as sem fins lucrativos.","answer":false,"explanation":"Errada. O art. 199, § 1º, prevê que as instituições privadas poderão participar de forma complementar do sistema único de saúde, segundo diretrizes deste, mediante contrato de direito público ou convênio. O enunciado diz participação \"substitutiva\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0084","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 2º","number":"Art. 199, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º É vedada a destinação de recursos públicos para auxílios ou subvenções às instituições privadas com fins lucrativos."],"origin":"authorial","question":{"statement":"§ 2º É vedada a destinação de recursos públicos para auxílios ou subvenções às instituições privadas com fins lucrativos.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 199, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0085","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 3º","number":"Art. 199, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º - É vedada a participação direta ou indireta de empresas ou capitais estrangeiros na assistência à saúde no País, salvo nos casos previstos em lei."],"origin":"authorial","question":{"statement":"§ 3º - É vedada a participação direta ou indireta de empresas ou capitais estrangeiros na assistência à saúde no País, salvo nos casos previstos em decreto.","answer":false,"explanation":"Errada. O art. 199, § 3º, veda a participação direta ou indireta de empresas ou capitais estrangeiros na assistência à saúde no País, salvo nos casos previstos em lei. O enunciado diz \"decreto\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0086","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 199, § 4º","number":"Art. 199, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A lei disporá sobre as condições e os requisitos que facilitem a remoção de órgãos, tecidos e substâncias humanas para fins de transplante, pesquisa e tratamento, bem como a coleta, processamento e transfusão de sangue e seus derivados, sendo vedado todo tipo de comercialização."],"origin":"authorial","question":{"statement":"§ 4º A lei disporá sobre as condições e os requisitos que facilitem a remoção de órgãos, tecidos e substâncias humanas para fins de transplante, pesquisa e tratamento, bem como a coleta, processamento e transfusão de sangue e seus derivados, sendo vedado todo tipo de comercialização.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 199, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0087","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso I","number":"Art. 200, caput e inciso I","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nI - controlar e fiscalizar procedimentos, produtos e substâncias de interesse para a saúde e participar da produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nI - controlar e fiscalizar procedimentos, produtos e substâncias de interesse para a saúde e exercer com exclusividade a produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos;","answer":false,"explanation":"Errada. O art. 200, I, atribui ao SUS controlar e fiscalizar procedimentos, produtos e substâncias de interesse para a saúde e participar da produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos. O enunciado fala em exercer essa produção \"com exclusividade\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0088","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso II","number":"Art. 200, caput e inciso II","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nII - executar as ações de vigilância sanitária e epidemiológica, bem como as de saúde do trabalhador;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nII - executar as ações de vigilância sanitária e epidemiológica, bem como as de saúde do trabalhador;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 200, caput e inciso II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0089","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso III","number":"Art. 200, caput e inciso III","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIII - ordenar a formação de recursos humanos na área de saúde;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIII - ordenar a formação de recursos humanos na área de saúde;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 200, caput e inciso III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0090","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso IV","number":"Art. 200, caput e inciso IV","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIV - participar da formulação da política e da execução das ações de saneamento básico;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nIV - participar apenas da execução das ações de saneamento básico;","answer":false,"explanation":"Errada. O art. 200, IV, atribui ao SUS participar da formulação da política e da execução das ações de saneamento básico. O enunciado restringe a participação \"apenas\" à execução.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0091","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso V","number":"Art. 200, caput e inciso V","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nV - incrementar, em sua área de atuação, o desenvolvimento científico e tecnológico e a inovação;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nV - incrementar, em sua área de atuação, o desenvolvimento científico e tecnológico e a inovação;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 200, caput e inciso V, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0092","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso VI","number":"Art. 200, caput e inciso VI","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVI - fiscalizar e inspecionar alimentos, compreendido o controle de seu teor nutricional, bem como bebidas e águas para consumo humano;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVI - fiscalizar e inspecionar alimentos, excluído o controle de seu teor nutricional, bem como bebidas e águas para consumo humano;","answer":false,"explanation":"Errada. O art. 200, VI, atribui ao SUS fiscalizar e inspecionar alimentos, compreendido o controle de seu teor nutricional, bem como bebidas e águas para consumo humano. O enunciado diz \"excluído\" o controle do teor nutricional.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0093","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso VII","number":"Art. 200, caput e inciso VII","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVII - participar do controle e fiscalização da produção, transporte, guarda e utilização de substâncias e produtos psicoativos, tóxicos e radioativos;"],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVII - participar do controle e fiscalização da produção, transporte, guarda e utilização de substâncias e produtos psicoativos, tóxicos e radioativos;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 200, caput e inciso VII, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0094","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 200, caput e inciso VIII","number":"Art. 200, caput e inciso VIII","title":"Constituição Federal de 1988","parts":["Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVIII - colaborar na proteção do meio ambiente, nele compreendido o do trabalho."],"origin":"authorial","question":{"statement":"Art. 200. Ao sistema único de saúde compete, além de outras atribuições, nos termos da lei:\nVIII - colaborar na proteção do meio ambiente, excluído o do trabalho.","answer":false,"explanation":"Errada. O art. 200, VIII, atribui ao SUS colaborar na proteção do meio ambiente, nele compreendido o do trabalho. O enunciado diz \"excluído\" o meio ambiente do trabalho.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0095","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, caput","number":"Art. 202, caput","title":"Constituição Federal de 1988","parts":["Art. 202. O regime de previdência privada, de caráter complementar e organizado de forma autônoma em relação ao regime geral de previdência social, será facultativo, baseado na constituição de reservas que garantam o benefício contratado, e regulado por lei complementar."],"origin":"authorial","question":{"statement":"Art. 202. O regime de previdência privada, de caráter complementar e organizado de forma autônoma em relação ao regime geral de previdência social, será facultativo, baseado na constituição de reservas que garantam o benefício contratado, e regulado por lei complementar.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 202, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0096","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 1º","number":"Art. 202, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º A lei complementar de que trata este artigo assegurará ao participante de planos de benefícios de entidades de previdência privada o pleno acesso às informações relativas à gestão de seus respectivos planos."],"origin":"authorial","question":{"statement":"§ 1º A lei complementar de que trata este artigo assegurará ao patrocinador de planos de benefícios de entidades de previdência privada o pleno acesso às informações relativas à gestão de seus respectivos planos.","answer":false,"explanation":"Errada. O art. 202, § 1º, assegura ao participante de planos de benefícios de entidades de previdência privada o pleno acesso às informações relativas à gestão de seus respectivos planos. O enunciado atribui o direito ao \"patrocinador\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0097","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 2º","number":"Art. 202, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º As contribuições do empregador, os benefícios e as condições contratuais previstas nos estatutos, regulamentos e planos de benefícios das entidades de previdência privada não integram o contrato de trabalho dos participantes, assim como, à exceção dos benefícios concedidos, não integram a remuneração dos participantes, nos termos da lei."],"origin":"authorial","question":{"statement":"§ 2º As contribuições do empregador, os benefícios e as condições contratuais previstas nos estatutos, regulamentos e planos de benefícios das entidades de previdência privada não integram o contrato de trabalho dos participantes, assim como, à exceção dos benefícios concedidos, não integram a remuneração dos participantes, nos termos da lei.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 202, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0098","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 3º","number":"Art. 202, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º É vedado o aporte de recursos a entidade de previdência privada pela União, Estados, Distrito Federal e Municípios, suas autarquias, fundações, empresas públicas, sociedades de economia mista e outras entidades públicas, salvo na qualidade de patrocinador, situação na qual, em hipótese alguma, sua contribuição normal poderá exceder a do segurado."],"origin":"authorial","question":{"statement":"§ 3º É vedado o aporte de recursos a entidade de previdência privada pela União, Estados, Distrito Federal e Municípios, suas autarquias, fundações, empresas públicas, sociedades de economia mista e outras entidades públicas, salvo na qualidade de patrocinador, situação na qual, sua contribuição normal poderá exceder a do segurado.","answer":false,"explanation":"Errada. O art. 202, § 3º, ressalva o aporte de recursos pelos entes públicos apenas na qualidade de patrocinador, situação na qual, em hipótese alguma, sua contribuição normal poderá exceder a do segurado. O enunciado suprime \"em hipótese alguma\" e passa a afirmar que a contribuição \"poderá exceder\" a do segurado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0099","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 4º","number":"Art. 202, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Lei complementar disciplinará a relação entre a União, Estados, Distrito Federal ou Municípios, inclusive suas autarquias, fundações, sociedades de economia mista e empresas controladas direta ou indiretamente, enquanto patrocinadores de planos de benefícios previdenciários, e as entidades de previdência complementar."],"origin":"authorial","question":{"statement":"§ 4º Lei complementar disciplinará a relação entre a União, Estados, Distrito Federal ou Municípios, inclusive suas autarquias, fundações, sociedades de economia mista e empresas controladas direta ou indiretamente, enquanto patrocinadores de planos de benefícios previdenciários, e as entidades de previdência complementar.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 202, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0100","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 5º","number":"Art. 202, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º A lei complementar de que trata o § 4º aplicar-se-á, no que couber, às empresas privadas permissionárias ou concessionárias de prestação de serviços públicos, quando patrocinadoras de planos de benefícios em entidades de previdência complementar."],"origin":"authorial","question":{"statement":"§ 5º A lei complementar de que trata o § 4º aplicar-se-á integralmente, às empresas privadas permissionárias ou concessionárias de prestação de serviços públicos, quando patrocinadoras de planos de benefícios em entidades de previdência complementar.","answer":false,"explanation":"Errada. O art. 202, § 5º, determina que a lei complementar de que trata o § 4º aplicar-se-á, no que couber, às empresas privadas permissionárias ou concessionárias de prestação de serviços públicos quando patrocinadoras de entidades fechadas de previdência privada. O enunciado diz \"integralmente\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0101","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 202, § 6º","number":"Art. 202, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º Lei complementar estabelecerá os requisitos para a designação dos membros das diretorias das entidades fechadas de previdência complementar instituídas pelos patrocinadores de que trata o § 4º e disciplinará a inserção dos participantes nos colegiados e instâncias de decisão em que seus interesses sejam objeto de discussão e deliberação."],"origin":"authorial","question":{"statement":"§ 6º Lei complementar estabelecerá os requisitos para a designação dos membros das diretorias das entidades fechadas de previdência complementar instituídas pelos patrocinadores de que trata o § 4º e disciplinará a inserção dos participantes nos colegiados e instâncias de decisão em que seus interesses sejam objeto de discussão e deliberação.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 202, § 6º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0102","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput","number":"Art. 203, caput","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, mediante contribuição à seguridade social, e tem por objetivos:","answer":false,"explanation":"Errada. O art. 203, caput, prevê que a assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social. O enunciado a condiciona à contribuição (\"mediante contribuição\").","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0103","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e incisos I e II","number":"Art. 203, caput e incisos I e II","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nI - a proteção à família, à maternidade, à infância, à adolescência e à velhice;\nII - o amparo às crianças e adolescentes carentes;"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nI - a proteção à família, à maternidade, à infância, à adolescência e à velhice;\nII - o amparo às crianças e adolescentes carentes;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 203, caput e incisos I e II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0104","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso III","number":"Art. 203, caput e inciso III","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIII - a promoção da integração ao mercado de trabalho;"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIII - a promoção da integração ao mercado de trabalho;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 203, caput e inciso III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0105","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso IV","number":"Art. 203, caput e inciso IV","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIV - a habilitação e reabilitação das pessoas portadoras de deficiência e a promoção de sua integração à vida comunitária;"],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nIV - a habilitação e reabilitação das pessoas portadoras de deficiência e a promoção de sua integração exclusiva ao mercado de trabalho;","answer":false,"explanation":"Errada. O art. 203, IV, prevê a habilitação e reabilitação das pessoas portadoras de deficiência e a promoção de sua integração à vida comunitária. O enunciado a restringe à integração \"exclusiva ao mercado de trabalho\", que é objeto do inciso III.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0106","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso V","number":"Art. 203, caput e inciso V","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nV - a garantia de um salário mínimo de benefício mensal à pessoa portadora de deficiência e ao idoso que comprovem não possuir meios de prover à própria manutenção ou de tê-la provida por sua família, conforme dispuser a lei."],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nV - a garantia de um salário mínimo de benefício mensal à pessoa portadora de deficiência e ao idoso que comprovem não possuir meios de prover à própria manutenção ou de tê-la provida por sua família, conforme dispuser a lei.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 203, caput e inciso V, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0107","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 203, caput e inciso VI","number":"Art. 203, caput e inciso VI","title":"Constituição Federal de 1988","parts":["Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nVI - a redução da vulnerabilidade socioeconômica de famílias em situação de pobreza ou de extrema pobreza."],"origin":"authorial","question":{"statement":"Art. 203. A assistência social será prestada a quem dela necessitar, independentemente de contribuição à seguridade social, e tem por objetivos:\nVI - a redução da vulnerabilidade socioeconômica de famílias em situação de pobreza e de extrema pobreza.","answer":false,"explanation":"Errada. O art. 203, VI, prevê a redução da vulnerabilidade socioeconômica de famílias em situação de pobreza ou de extrema pobreza (situações alternativas). O enunciado troca \"ou\" por \"e\", exigindo as duas situações cumulativamente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0108","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, caput e inciso I","number":"Art. 204, caput e inciso I","title":"Constituição Federal de 1988","parts":["Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nI - descentralização político-administrativa, cabendo a coordenação e as normas gerais à esfera federal e a coordenação e a execução dos respectivos programas às esferas estadual e municipal, bem como a entidades beneficentes e de assistência social;"],"origin":"authorial","question":{"statement":"Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nI - descentralização político-administrativa, cabendo a coordenação e as normas gerais à esfera federal e a coordenação e a execução dos respectivos programas à esfera federal, bem como a entidades beneficentes e de assistência social;","answer":false,"explanation":"Errada. O art. 204, I, atribui a coordenação e as normas gerais à esfera federal e a coordenação e a execução dos respectivos programas às esferas estadual e municipal, bem como a entidades beneficentes e de assistência social. O enunciado atribui a coordenação e a execução à esfera federal.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0109","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, caput e inciso II","number":"Art. 204, caput e inciso II","title":"Constituição Federal de 1988","parts":["Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nII - participação da população, por meio de organizações representativas, na formulação das políticas e no controle das ações em todos os níveis."],"origin":"authorial","question":{"statement":"Art. 204. As ações governamentais na área da assistência social serão realizadas com recursos do orçamento da seguridade social, previstos no art. 195, além de outras fontes, e organizadas com base nas seguintes diretrizes:\nII - participação da população, por meio de organizações representativas, na formulação das políticas e no controle das ações em todos os níveis.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 204, caput e inciso II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0110","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, parágrafo único, inciso I","number":"Art. 204, parágrafo único, inciso I","title":"Constituição Federal de 1988","parts":["Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nI - despesas com pessoal e encargos sociais;"],"origin":"authorial","question":{"statement":"Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até um por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nI - despesas com pessoal e encargos sociais;","answer":false,"explanation":"Errada. O art. 204, parágrafo único, faculta aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida. O enunciado fala em \"um por cento\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0111","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 204, parágrafo único, incisos II e III","number":"Art. 204, parágrafo único, incisos II e III","title":"Constituição Federal de 1988","parts":["Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nII - serviço da dívida;\nIII - qualquer outra despesa corrente não vinculada diretamente aos investimentos ou ações apoiados."],"origin":"authorial","question":{"statement":"Parágrafo único. É facultado aos Estados e ao Distrito Federal vincular a programa de apoio à inclusão e promoção social até cinco décimos por cento de sua receita tributária líquida, vedada a aplicação desses recursos no pagamento de:\nII - serviço da dívida;\nIII - qualquer outra despesa corrente não vinculada diretamente aos investimentos ou ações apoiados.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 204, parágrafo único, incisos II e III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0112","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, caput","number":"Art. 225, caput","title":"Constituição Federal de 1988","parts":["Art. 225. Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se ao Poder Público e à coletividade o dever de defendê-lo e preservá-lo para as presentes e futuras gerações."],"origin":"authorial","question":{"statement":"Art. 225. Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se exclusivamente ao Poder Público o dever de defendê-lo e preservá-lo para as presentes e futuras gerações.","answer":false,"explanation":"Errada. O art. 225, caput, impõe ao Poder Público e à coletividade o dever de defender e preservar o meio ambiente ecologicamente equilibrado para as presentes e futuras gerações. O enunciado o atribui \"exclusivamente\" ao Poder Público.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0113","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, I","number":"Art. 225, § 1º, I","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nI - preservar e restaurar os processos ecológicos essenciais e prover o manejo ecológico das espécies e ecossistemas;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nI - preservar e restaurar os processos ecológicos essenciais e prover o manejo ecológico das espécies e ecossistemas;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 1º, I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0114","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, II","number":"Art. 225, § 1º, II","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nII - preservar a diversidade e a integridade do patrimônio genético do País e fiscalizar as entidades dedicadas à pesquisa e manipulação de material genético;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nII - preservar a diversidade e a integridade do patrimônio genético do País e autorizar exclusivamente as entidades dedicadas à pesquisa e manipulação de material genético;","answer":false,"explanation":"Errada. O art. 225, § 1º, II, incumbe ao Poder Público preservar a diversidade e a integridade do patrimônio genético do País e fiscalizar as entidades dedicadas à pesquisa e manipulação de material genético. O enunciado diz \"autorizar exclusivamente\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0115","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, III","number":"Art. 225, § 1º, III","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIII - definir, em todas as unidades da Federação, espaços territoriais e seus componentes a serem especialmente protegidos, sendo a alteração e a supressão permitidas somente através de lei, vedada qualquer utilização que comprometa a integridade dos atributos que justifiquem sua proteção;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIII - definir, em todas as unidades da Federação, espaços territoriais e seus componentes a serem especialmente protegidos, sendo a alteração e a supressão permitidas somente através de lei, vedada qualquer utilização que comprometa a integridade dos atributos que justifiquem sua proteção;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 1º, III, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0116","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, IV","number":"Art. 225, § 1º, IV","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIV - exigir, na forma da lei, para instalação de obra ou atividade potencialmente causadora de significativa degradação do meio ambiente, estudo prévio de impacto ambiental, a que se dará publicidade;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nIV - exigir, na forma da lei, para instalação de obra ou atividade potencialmente causadora de significativa degradação do meio ambiente, estudo posterior de impacto ambiental, a que se dará publicidade;","answer":false,"explanation":"Errada. O art. 225, § 1º, IV, exige estudo prévio de impacto ambiental, a que se dará publicidade, para obra ou atividade potencialmente causadora de significativa degradação do meio ambiente. O enunciado diz estudo \"posterior\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0117","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, V","number":"Art. 225, § 1º, V","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nV - controlar a produção, a comercialização e o emprego de técnicas, métodos e substâncias que comportem risco para a vida, a qualidade de vida e o meio ambiente;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nV - controlar a produção, a comercialização e o emprego de técnicas, métodos e substâncias que comportem risco para a vida, a qualidade de vida e o meio ambiente;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 1º, V, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0118","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, VI","number":"Art. 225, § 1º, VI","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVI - promover a educação ambiental em todos os níveis de ensino e a conscientização pública para a preservação do meio ambiente;"],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVI - promover a educação ambiental apenas no ensino básico e a conscientização pública para a preservação do meio ambiente;","answer":false,"explanation":"Errada. O art. 225, § 1º, VI, manda promover a educação ambiental em todos os níveis de ensino e a conscientização pública para a preservação do meio ambiente. O enunciado a restringe \"apenas\" ao ensino básico.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0119","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, VII","number":"Art. 225, § 1º, VII","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVII - proteger a fauna e a flora, vedadas, na forma da lei, as práticas que coloquem em risco sua função ecológica, provoquem a extinção de espécies ou submetam os animais a crueldade."],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVII - proteger a fauna e a flora, vedadas, na forma da lei, as práticas que coloquem em risco sua função ecológica, provoquem a extinção de espécies ou submetam os animais a crueldade.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 1º, VII, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0120","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 1º, VIII","number":"Art. 225, § 1º, VIII","title":"Constituição Federal de 1988","parts":["§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVIII - manter regime fiscal favorecido para os biocombustíveis e para o hidrogênio de baixa emissão de carbono, na forma de lei complementar, a fim de assegurar-lhes tributação inferior à incidente sobre os combustíveis fósseis, capaz de garantir diferencial competitivo em relação a estes, especialmente em relação às contribuições de que tratam o art. 195, I, \"b\", IV e V, e o art. 239 e aos impostos a que se referem os arts. 155, II, e 156-A."],"origin":"authorial","question":{"statement":"§ 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público:\nVIII - manter regime fiscal favorecido exclusivamente para os biocombustíveis, na forma de lei complementar, a fim de assegurar-lhes tributação inferior à incidente sobre os combustíveis fósseis, capaz de garantir diferencial competitivo em relação a estes, especialmente em relação às contribuições de que tratam o art. 195, I, \"b\", IV e V, e o art. 239 e aos impostos a que se referem os arts. 155, II, e 156-A.","answer":false,"explanation":"Errada. O art. 225, § 1º, VIII, manda manter regime fiscal favorecido para os biocombustíveis e para o hidrogênio de baixa emissão de carbono, na forma de lei complementar. O enunciado restringe o regime \"exclusivamente\" aos biocombustíveis.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0121","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 2º","number":"Art. 225, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º Aquele que explorar recursos minerais fica obrigado a recuperar o meio ambiente degradado, de acordo com solução técnica exigida pelo órgão público competente, na forma da lei."],"origin":"authorial","question":{"statement":"§ 2º Aquele que explorar recursos minerais fica obrigado a recuperar o meio ambiente degradado, de acordo com solução técnica exigida pelo órgão público competente, na forma da lei.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0122","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 3º","number":"Art. 225, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º As condutas e atividades consideradas lesivas ao meio ambiente sujeitarão os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas, independentemente da obrigação de reparar os danos causados."],"origin":"authorial","question":{"statement":"§ 3º As condutas e atividades consideradas lesivas ao meio ambiente sujeitarão os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas, em substituição à obrigação de reparar os danos causados.","answer":false,"explanation":"Errada. O art. 225, § 3º, sujeita os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas, independentemente da obrigação de reparar os danos causados. O enunciado diz \"em substituição à\" obrigação de reparar.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0123","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 4º","number":"Art. 225, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A Floresta Amazônica brasileira, a Mata Atlântica, a Serra do Mar, o Pantanal Mato-Grossense e a Zona Costeira são patrimônio nacional, e sua utilização far-se-á, na forma da lei, dentro de condições que assegurem a preservação do meio ambiente, inclusive quanto ao uso dos recursos naturais."],"origin":"authorial","question":{"statement":"§ 4º A Floresta Amazônica brasileira, a Mata Atlântica, a Serra do Mar, o Pantanal Mato-Grossense e a Zona Costeira são patrimônio nacional, e sua utilização far-se-á, na forma da lei, dentro de condições que assegurem a preservação do meio ambiente, inclusive quanto ao uso dos recursos naturais.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0124","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 5º","number":"Art. 225, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º São indisponíveis as terras devolutas ou arrecadadas pelos Estados, por ações discriminatórias, necessárias à proteção dos ecossistemas naturais."],"origin":"authorial","question":{"statement":"§ 5º São indisponíveis as terras devolutas ou arrecadadas pela União, por ações discriminatórias, necessárias à proteção dos ecossistemas naturais.","answer":false,"explanation":"Errada. O art. 225, § 5º, declara indisponíveis as terras devolutas ou arrecadadas pelos Estados, por ações discriminatórias, necessárias à proteção dos ecossistemas naturais. O enunciado atribui a arrecadação à União.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0125","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 6º","number":"Art. 225, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º As usinas que operem com reator nuclear deverão ter sua localização definida em lei federal, sem o que não poderão ser instaladas."],"origin":"authorial","question":{"statement":"§ 6º As usinas que operem com reator nuclear deverão ter sua localização definida em lei federal, sem o que não poderão ser instaladas.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 225, § 6º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0126","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 225, § 7º","number":"Art. 225, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º Para fins do disposto na parte final do inciso VII do § 1º deste artigo, não se consideram cruéis as práticas desportivas que utilizem animais, desde que sejam manifestações culturais, conforme o § 1º do art. 215 desta Constituição Federal, registradas como bem de natureza imaterial integrante do patrimônio cultural brasileiro, devendo ser regulamentadas por lei específica que assegure o bem-estar dos animais envolvidos."],"origin":"authorial","question":{"statement":"§ 7º Para fins do disposto na parte final do inciso VII do § 1º deste artigo, não se consideram cruéis as práticas desportivas que utilizem animais, desde que sejam manifestações culturais, conforme o § 1º do art. 215 desta Constituição Federal, reconhecidas como bem de natureza imaterial integrante do patrimônio cultural brasileiro, devendo ser regulamentadas por lei específica que assegure o bem-estar dos animais envolvidos.","answer":false,"explanation":"Errada. O art. 225, § 7º, exige que as manifestações culturais sejam registradas como bem de natureza imaterial integrante do patrimônio cultural brasileiro. O enunciado troca \"registradas\" por \"reconhecidas\", termo que não consta do texto; a alteração é terminológica, por isso a certificação é parcial (gabarito mantido pela literalidade).","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado-parcial","basis":"texto legal conferido (Constituição Federal, Planalto); dispositivo ou precedente complementar ainda não conferido em fonte oficial","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0127","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, caput","number":"Art. 226, caput","title":"Constituição Federal de 1988","parts":["Art. 226. A família, base da sociedade, tem especial proteção do Estado."],"origin":"authorial","question":{"statement":"Art. 226. A família, base da sociedade, tem especial proteção do Estado.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 226, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0128","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 1º","number":"Art. 226, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º O casamento é civil e gratuita a celebração."],"origin":"authorial","question":{"statement":"§ 1º O casamento é civil e gratuito o registro civil.","answer":false,"explanation":"Errada. O art. 226, § 1º, prevê que o casamento é civil e gratuita a celebração. O enunciado fala em gratuidade do \"registro civil\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0129","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 2º","number":"Art. 226, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º O casamento religioso tem efeito civil, nos termos da lei."],"origin":"authorial","question":{"statement":"§ 2º O casamento religioso tem efeito civil, nos termos da lei.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 226, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0130","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 3º","number":"Art. 226, § 3º","title":"Constituição Federal de 1988","parts":["§ 3º Para efeito da proteção do Estado, é reconhecida a união estável entre o homem e a mulher como entidade familiar, devendo a lei facilitar sua conversão em casamento."],"origin":"authorial","question":{"statement":"§ 3º Para efeito da proteção do Estado, é reconhecida a união estável entre o homem e a mulher como entidade familiar, devendo a lei impedir sua conversão em casamento.","answer":false,"explanation":"Errada. O art. 226, § 3º, manda a lei facilitar a conversão da união estável em casamento. O enunciado diz \"impedir\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0131","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 4º","number":"Art. 226, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º Entende-se, também, como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes."],"origin":"authorial","question":{"statement":"§ 4º Entende-se, também, como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 226, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0132","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 5º","number":"Art. 226, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º Os direitos e deveres referentes à sociedade conjugal são exercidos igualmente pelo homem e pela mulher."],"origin":"authorial","question":{"statement":"§ 5º Os direitos e deveres referentes à sociedade conjugal são exercidos preferencialmente pelo homem.","answer":false,"explanation":"Errada. O art. 226, § 5º, prevê que os direitos e deveres referentes à sociedade conjugal são exercidos igualmente pelo homem e pela mulher. O enunciado diz que são exercidos \"preferencialmente pelo homem\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0133","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 6º","number":"Art. 226, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º O casamento civil pode ser dissolvido pelo divórcio."],"origin":"authorial","question":{"statement":"§ 6º O casamento civil pode ser dissolvido pelo divórcio.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 226, § 6º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0134","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 7º","number":"Art. 226, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º Fundado nos princípios da dignidade da pessoa humana e da paternidade responsável, o planejamento familiar é livre decisão do casal, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito, vedada qualquer forma coercitiva por parte de instituições oficiais ou privadas."],"origin":"authorial","question":{"statement":"§ 7º Fundado nos princípios da dignidade da pessoa humana e da paternidade responsável, o planejamento familiar é decisão exclusiva do Estado, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito, vedada qualquer forma coercitiva por parte de instituições oficiais ou privadas.","answer":false,"explanation":"Errada. O art. 226, § 7º, dispõe que o planejamento familiar é livre decisão do casal, competindo ao Estado propiciar recursos educacionais e científicos para o exercício desse direito. O enunciado atribui a decisão \"exclusiva\" ao Estado.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0135","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 226, § 8º","number":"Art. 226, § 8º","title":"Constituição Federal de 1988","parts":["§ 8º O Estado assegurará a assistência à família na pessoa de cada um dos que a integram, criando mecanismos para coibir a violência no âmbito de suas relações."],"origin":"authorial","question":{"statement":"§ 8º O Estado assegurará a assistência à família na pessoa de cada um dos que a integram, criando mecanismos para coibir a violência no âmbito de suas relações.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 226, § 8º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0136","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, caput","number":"Art. 227, caput","title":"Constituição Federal de 1988","parts":["Art. 227. É dever da família, da sociedade e do Estado assegurar à criança, ao adolescente e ao jovem, com absoluta prioridade, o direito à vida, à saúde, à alimentação, à educação, ao lazer, à profissionalização, à cultura, à dignidade, ao respeito, à liberdade e à convivência familiar e comunitária, além de colocá-los a salvo de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão."],"origin":"authorial","question":{"statement":"Art. 227. É dever da família, da sociedade e do Estado assegurar à criança e ao adolescente, com absoluta prioridade, o direito à vida, à saúde, à alimentação, à educação, ao lazer, à profissionalização, à cultura, à dignidade, ao respeito, à liberdade e à convivência familiar e comunitária, além de colocá-los a salvo de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão.","answer":false,"explanation":"Errada. O art. 227, caput, impõe à família, à sociedade e ao Estado o dever de assegurar, com absoluta prioridade, os direitos ali listados à criança, ao adolescente e ao jovem. O enunciado omite o jovem; a omissão não contradiz o dispositivo, por isso a certificação é parcial (gabarito mantido pela falta de correspondência literal).","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado-parcial","basis":"texto legal conferido (Constituição Federal, Planalto); dispositivo ou precedente complementar ainda não conferido em fonte oficial","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0137","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 1º, I","number":"Art. 227, § 1º, I","title":"Constituição Federal de 1988","parts":["§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nI - aplicação de percentual dos recursos públicos destinados à saúde na assistência materno-infantil;"],"origin":"authorial","question":{"statement":"§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nI - aplicação de percentual dos recursos públicos destinados à saúde na assistência materno-infantil;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 1º, I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0138","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 1º, II","number":"Art. 227, § 1º, II","title":"Constituição Federal de 1988","parts":["§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nII - criação de programas de prevenção e atendimento especializado para as pessoas portadoras de deficiência física, sensorial ou mental, bem como de integração social do adolescente e do jovem portador de deficiência, mediante o treinamento para o trabalho e a convivência, e a facilitação do acesso aos bens e serviços coletivos, com a eliminação de obstáculos arquitetônicos e de todas as formas de discriminação."],"origin":"authorial","question":{"statement":"§ 1º O Estado promoverá programas de assistência integral à saúde da criança, do adolescente e do jovem, admitida a participação de entidades não governamentais, mediante políticas específicas e obedecendo aos seguintes preceitos:\nII - criação de programas de prevenção e atendimento especializado para as pessoas portadoras de deficiência física, sensorial ou mental, bem como de integração social do adolescente e do jovem portador de deficiência, mediante o treinamento para o trabalho e a convivência, e a facilitação do acesso aos bens e serviços coletivos, com a eliminação apenas de obstáculos arquitetônicos.","answer":false,"explanation":"Errada. O art. 227, § 1º, II, prevê a facilitação do acesso aos bens e serviços coletivos, com a eliminação de obstáculos arquitetônicos e de todas as formas de discriminação. O enunciado restringe a eliminação \"apenas\" aos obstáculos arquitetônicos.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0139","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 2º","number":"Art. 227, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º A lei disporá sobre normas de construção dos logradouros e dos edifícios de uso público e de fabricação de veículos de transporte coletivo, a fim de garantir acesso adequado às pessoas portadoras de deficiência."],"origin":"authorial","question":{"statement":"§ 2º A lei disporá sobre normas de construção dos logradouros e dos edifícios de uso público e de fabricação de veículos de transporte coletivo, a fim de garantir acesso adequado às pessoas portadoras de deficiência.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0140","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, I","number":"Art. 227, § 3º, I","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nI - idade mínima de quatorze anos para admissão ao trabalho, observado o disposto no art. 7º, XXXIII;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nI - idade mínima de quatorze anos para admissão ao trabalho, independentemente do disposto no art. 7º, XXXIII;","answer":false,"explanation":"Errada. O art. 227, § 3º, I, fixa idade mínima de quatorze anos para admissão ao trabalho, observado o disposto no art. 7º, XXXIII. O enunciado diz \"independentemente do\" disposto nesse inciso.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0141","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, II","number":"Art. 227, § 3º, II","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nII - garantia de direitos previdenciários e trabalhistas;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nII - garantia de direitos previdenciários e trabalhistas;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 3º, II, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0142","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, III","number":"Art. 227, § 3º, III","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIII - garantia de acesso do trabalhador adolescente e jovem à escola;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIII - garantia de acesso apenas do trabalhador adolescente à escola;","answer":false,"explanation":"Errada. O art. 227, § 3º, III, garante o acesso do trabalhador adolescente e jovem à escola. O enunciado restringe a garantia \"apenas\" ao trabalhador adolescente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0143","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, IV","number":"Art. 227, § 3º, IV","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIV - garantia de pleno e formal conhecimento da atribuição de ato infracional, igualdade na relação processual e defesa técnica por profissional habilitado, segundo dispuser a legislação tutelar específica;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nIV - garantia de pleno e formal conhecimento da atribuição de ato infracional, igualdade na relação processual e defesa técnica por profissional habilitado, segundo dispuser a legislação tutelar específica;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 3º, IV, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0144","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, V","number":"Art. 227, § 3º, V","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nV - obediência aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento, quando da aplicação de qualquer medida privativa da liberdade;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nV - obediência aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento, quando da aplicação de medidas meramente educativas sem privação da liberdade;","answer":false,"explanation":"Errada. O art. 227, § 3º, V, exige obediência aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento quando da aplicação de qualquer medida privativa da liberdade. O enunciado fala em \"medidas meramente educativas sem privação\" da liberdade.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0145","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, VI","number":"Art. 227, § 3º, VI","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVI - estímulo do Poder Público, através de assistência jurídica, incentivos fiscais e subsídios, nos termos da lei, ao acolhimento, sob a forma de guarda, de criança ou adolescente órfão ou abandonado;"],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVI - estímulo do Poder Público, através de assistência jurídica, incentivos fiscais e subsídios, nos termos da lei, ao acolhimento, sob a forma de guarda, de criança ou adolescente órfão ou abandonado;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 3º, VI, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0146","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 3º, VII","number":"Art. 227, § 3º, VII","title":"Constituição Federal de 1988","parts":["§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVII - programas de prevenção e atendimento especializado à criança, ao adolescente e ao jovem dependente de entorpecentes e drogas afins."],"origin":"authorial","question":{"statement":"§ 3º O direito a proteção especial abrangerá os seguintes aspectos:\nVII - programas de prevenção e atendimento especializado somente ao adolescente dependente de entorpecentes e drogas afins.","answer":false,"explanation":"Errada. O art. 227, § 3º, VII, prevê programas de prevenção e atendimento especializado à criança, ao adolescente e ao jovem dependente de entorpecentes e drogas afins. O enunciado os restringe \"somente\" ao adolescente.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0147","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 4º","number":"Art. 227, § 4º","title":"Constituição Federal de 1988","parts":["§ 4º A lei punirá severamente o abuso, a violência e a exploração sexual da criança e do adolescente."],"origin":"authorial","question":{"statement":"§ 4º A lei punirá severamente o abuso, a violência e a exploração sexual da criança e do adolescente.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 4º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0148","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 5º","number":"Art. 227, § 5º","title":"Constituição Federal de 1988","parts":["§ 5º A adoção será assistida pelo Poder Público, na forma da lei, que estabelecerá casos e condições de sua efetivação por parte de estrangeiros."],"origin":"authorial","question":{"statement":"§ 5º A adoção será assistida pelo Poder Público, na forma da lei, que estabelecerá casos e condições de sua efetivação exclusivamente por parte de brasileiros.","answer":false,"explanation":"Errada. O art. 227, § 5º, prevê que a adoção será assistida pelo Poder Público, na forma da lei, que estabelecerá casos e condições de sua efetivação por parte de estrangeiros. O enunciado fala em efetivação \"exclusivamente por parte de brasileiros\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0149","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 6º","number":"Art. 227, § 6º","title":"Constituição Federal de 1988","parts":["§ 6º Os filhos, havidos ou não da relação do casamento, ou por adoção, terão os mesmos direitos e qualificações, proibidas quaisquer designações discriminatórias relativas à filiação."],"origin":"authorial","question":{"statement":"§ 6º Os filhos, havidos ou não da relação do casamento, ou por adoção, terão os mesmos direitos e qualificações, proibidas quaisquer designações discriminatórias relativas à filiação.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 6º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0150","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 7º","number":"Art. 227, § 7º","title":"Constituição Federal de 1988","parts":["§ 7º No atendimento dos direitos da criança e do adolescente levar-se- á em consideração o disposto no art. 204."],"origin":"authorial","question":{"statement":"§ 7º No atendimento dos direitos da criança e do adolescente levar-se- á em consideração o disposto no art. 198.","answer":false,"explanation":"Errada. O art. 227, § 7º, manda levar em consideração, no atendimento dos direitos da criança e do adolescente, o disposto no art. 204. O enunciado cita o art. 198.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0151","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 8º, I","number":"Art. 227, § 8º, I","title":"Constituição Federal de 1988","parts":["§ 8º A lei estabelecerá:\nI - o estatuto da juventude, destinado a regular os direitos dos jovens;"],"origin":"authorial","question":{"statement":"§ 8º A lei estabelecerá:\nI - o estatuto da juventude, destinado a regular os direitos dos jovens;","answer":true,"explanation":"Correta. O enunciado reproduz o art. 227, § 8º, I, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0152","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 227, § 8º, II","number":"Art. 227, § 8º, II","title":"Constituição Federal de 1988","parts":["§ 8º A lei estabelecerá:\nII - o plano nacional de juventude, de duração decenal, visando à articulação das várias esferas do poder público para a execução de políticas públicas."],"origin":"authorial","question":{"statement":"§ 8º A lei estabelecerá:\nII - o plano nacional de juventude, de duração quadrienal, visando à articulação das várias esferas do poder público para a execução de políticas públicas.","answer":false,"explanation":"Errada. O art. 227, § 8º, II, prevê o plano nacional de juventude, de duração decenal. O enunciado diz \"quadrienal\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0153","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 228, caput","number":"Art. 228, caput","title":"Constituição Federal de 1988","parts":["Art. 228. São penalmente inimputáveis os menores de dezoito anos, sujeitos às normas da legislação especial."],"origin":"authorial","question":{"statement":"Art. 228. São penalmente inimputáveis os menores de dezoito anos, sujeitos às normas da legislação especial.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 228, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0154","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 229, caput","number":"Art. 229, caput","title":"Constituição Federal de 1988","parts":["Art. 229. Os pais têm o dever de assistir, criar e educar os filhos menores, e os filhos maiores têm o dever de ajudar e amparar os pais na velhice, carência ou enfermidade."],"origin":"authorial","question":{"statement":"Art. 229. Os pais têm o dever de assistir, criar e educar os filhos menores, e os filhos menores têm o dever de ajudar e amparar os pais na velhice, carência ou enfermidade.","answer":false,"explanation":"Errada. O art. 229, caput, impõe aos pais o dever de assistir, criar e educar os filhos menores, e aos filhos maiores o dever de ajudar e amparar os pais na velhice, carência ou enfermidade. O enunciado troca \"maiores\" por \"menores\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0155","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 230, caput","number":"Art. 230, caput","title":"Constituição Federal de 1988","parts":["Art. 230. A família, a sociedade e o Estado têm o dever de amparar as pessoas idosas, assegurando sua participação na comunidade, defendendo sua dignidade e bem-estar e garantindo-lhes o direito à vida."],"origin":"authorial","question":{"statement":"Art. 230. A família, a sociedade e o Estado têm o dever de amparar as pessoas idosas, assegurando sua participação na comunidade, defendendo sua dignidade e bem-estar e garantindo-lhes o direito à vida.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 230, caput, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0156","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 230, § 1º","number":"Art. 230, § 1º","title":"Constituição Federal de 1988","parts":["§ 1º Os programas de amparo aos idosos serão executados preferencialmente em seus lares."],"origin":"authorial","question":{"statement":"§ 1º Os programas de amparo aos idosos serão executados exclusivamente em instituições especializadas.","answer":false,"explanation":"Errada. O art. 230, § 1º, prevê que os programas de amparo aos idosos serão executados preferencialmente em seus lares. O enunciado diz \"exclusivamente em instituições especializadas\".","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · alta","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0157","discipline":"cf","topicId":"led-cf-cf88","subtopic":"Art. 230, § 2º","number":"Art. 230, § 2º","title":"Constituição Federal de 1988","parts":["§ 2º Aos maiores de sessenta e cinco anos é garantida a gratuidade dos transportes coletivos urbanos."],"origin":"authorial","question":{"statement":"§ 2º Aos maiores de sessenta e cinco anos é garantida a gratuidade dos transportes coletivos urbanos.","answer":true,"explanation":"Correta. O enunciado reproduz o art. 230, § 2º, da Constituição Federal de 1988.","source":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","meta":"LEI EM DIA · média","origin":"authorial","legalAudit":{"status":"certificado","basis":"texto legal conferido (Constituição Federal, Planalto)","date":"2026-10-28","source":"CF/88, texto compilado do Planalto"}}},{"id":"LED-20261009-0158","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 73, caput","number":"Art. 73, caput","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 73. Na hipótese de contratação direta indevida ocorrida com dolo, fraude ou erro grosseiro, o contratado e o agente público responsável responderão solidariamente pelo dano causado ao erário, sem prejuízo de outras sanções legais cabíveis."],"origin":"authorial","question":{"statement":"Art. 73. Na hipótese de contratação direta indevida ocorrida com dolo, fraude ou erro leve, o contratado e o agente público responsável responderão solidariamente pelo dano causado ao erário, sem prejuízo de outras sanções legais cabíveis.","answer":false,"explanation":"A solidariedade do contratado e do agente responsável depende de dolo, fraude ou erro grosseiro na contratação direta indevida.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0161","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso III, alínea a","number":"Art. 75, caput, inciso III, alínea a","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIII - para contratação que mantenha todas as condições definidas em edital de licitação realizada há menos de 1 (um) ano, quando se verificar que naquela licitação:\na) não surgiram licitantes interessados ou não foram apresentadas propostas válidas;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIII - para contratação que mantenha todas as condições definidas em edital de licitação realizada há menos de 1 (um) ano, quando se verificar que naquela licitação:\na) não surgiram licitantes interessados ou não foram apresentadas propostas válidas;","answer":true,"explanation":"A licitação anterior deve ter ocorrido há menos de um ano, sem interessados ou sem propostas válidas, e a contratação deve manter as condições do edital.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0162","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso III, alínea b","number":"Art. 75, caput, inciso III, alínea b","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIII - para contratação que mantenha todas as condições definidas em edital de licitação realizada há menos de 1 (um) ano, quando se verificar que naquela licitação:\nb) as propostas apresentadas consignaram preços manifestamente superiores aos praticados no mercado ou incompatíveis com os fixados pelos órgãos oficiais competentes;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIII - para contratação que mantenha todas as condições definidas em edital de licitação realizada há menos de 2 (dois) anos, quando se verificar que naquela licitação:\nb) as propostas apresentadas consignaram preços manifestamente superiores aos praticados no mercado ou incompatíveis com os fixados pelos órgãos oficiais competentes;","answer":false,"explanation":"O prazo é inferior a um ano e se mantém a exigência de condições do edital diante de preços superiores ao mercado ou incompatíveis com os oficiais.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0163","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea a","number":"Art. 75, caput, inciso IV, alínea a","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\na) bens, componentes ou peças de origem nacional ou estrangeira necessários à manutenção de equipamentos, a serem adquiridos do fornecedor original desses equipamentos durante o período de garantia técnica, quando essa condição de exclusividade for indispensável para a vigência da garantia;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\na) bens, componentes ou peças de origem nacional ou estrangeira necessários à manutenção de equipamentos, a serem adquiridos do fornecedor original desses equipamentos durante o período de garantia técnica, quando essa condição de exclusividade for indispensável para a vigência da garantia;","answer":true,"explanation":"A aquisição do fornecedor original, no período de garantia, depende de exclusividade indispensável à sua vigência.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0164","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea b","number":"Art. 75, caput, inciso IV, alínea b","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nb) bens, serviços, alienações ou obras, nos termos de acordo internacional específico aprovado pelo Congresso Nacional, quando as condições ofertadas forem manifestamente vantajosas para a Administração;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nb) bens, serviços, alienações ou obras, nos termos de acordo internacional específico aprovado pelo Poder Executivo, quando as condições ofertadas forem manifestamente vantajosas para a Administração;","answer":false,"explanation":"O acordo internacional específico deve ser aprovado pelo Congresso Nacional, e as condições ofertadas, manifestamente vantajosas.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0166","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea d","number":"Art. 75, caput, inciso IV, alínea d","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nd) transferência de tecnologia ou licenciamento de direito de uso ou de exploração de criação protegida, nas contratações realizadas por instituição científica, tecnológica e de inovação (ICT) pública ou por agência de fomento, desde que demonstrada vantagem para a Administração;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nd) transferência de tecnologia ou licenciamento de direito de uso ou de exploração de criação protegida, nas contratações realizadas por instituição científica, tecnológica e de inovação (ICT) privada ou por agência de fomento, desde que demonstrada vantagem para a Administração;","answer":false,"explanation":"A ICT é pública; a alternativa é agência de fomento, e a vantagem para a Administração deve ser demonstrada.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0167","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea e","number":"Art. 75, caput, inciso IV, alínea e","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\ne) hortifrutigranjeiros, pães e outros gêneros perecíveis, no período necessário para a realização dos processos licitatórios correspondentes, hipótese em que a contratação será realizada diretamente com base no preço do dia;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\ne) hortifrutigranjeiros, pães e outros gêneros perecíveis, no período necessário para a realização dos processos licitatórios correspondentes, hipótese em que a contratação será realizada diretamente com base no preço do dia;","answer":true,"explanation":"Os perecíveis podem ser adquiridos diretamente apenas pelo período necessário à licitação correspondente e pelo preço do dia.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0168","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea f","number":"Art. 75, caput, inciso IV, alínea f","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nf) bens ou serviços produzidos ou prestados no País que envolvam, cumulativamente, alta complexidade tecnológica e defesa nacional;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nf) bens ou serviços produzidos ou prestados no País que envolvam, alternativamente, alta complexidade tecnológica ou defesa nacional;","answer":false,"explanation":"Alta complexidade tecnológica e defesa nacional são requisitos cumulativos.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0169","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea g","number":"Art. 75, caput, inciso IV, alínea g","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\ng) materiais de uso das Forças Armadas, com exceção de materiais de uso pessoal e administrativo, quando houver necessidade de manter a padronização requerida pela estrutura de apoio logístico dos meios navais, aéreos e terrestres, mediante autorização por ato do comandante da força militar;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\ng) materiais de uso das Forças Armadas, com exceção de materiais de uso pessoal e administrativo, quando houver necessidade de manter a padronização requerida pela estrutura de apoio logístico dos meios navais, aéreos e terrestres, mediante autorização por ato do comandante da força militar;","answer":true,"explanation":"Há exceção para materiais de uso pessoal e administrativo e autorização por ato do comandante da força.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0170","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea h","number":"Art. 75, caput, inciso IV, alínea h","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nh) bens e serviços para atendimento dos contingentes militares das forças singulares brasileiras empregadas em operações de paz no exterior, hipótese em que a contratação deverá ser justificada quanto ao preço e à escolha do fornecedor ou executante e ratificada pelo comandante da força militar;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nh) bens e serviços para atendimento dos contingentes militares das forças singulares brasileiras empregadas em operações de paz no exterior, hipótese em que a contratação deverá ser justificada quanto ao preço e à escolha do fornecedor ou executante e ratificada pelo Ministro da Defesa;","answer":false,"explanation":"Além das justificativas de preço e escolha, a ratificação cabe ao comandante da força militar.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0171","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea i","number":"Art. 75, caput, inciso IV, alínea i","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\ni) abastecimento ou suprimento de efetivos militares em estada eventual de curta duração em portos, aeroportos ou localidades diferentes de suas sedes, por motivo de movimentação operacional ou de adestramento;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\ni) abastecimento ou suprimento de efetivos militares em estada eventual de curta duração em portos, aeroportos ou localidades diferentes de suas sedes, por motivo de movimentação operacional ou de adestramento;","answer":true,"explanation":"A hipótese abrange suprimento de efetivos militares em estada eventual e curta fora de suas sedes por operação ou adestramento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0172","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea j","number":"Art. 75, caput, inciso IV, alínea j","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nj) coleta, processamento e comercialização de resíduos sólidos urbanos recicláveis ou reutilizáveis, em áreas com sistema de coleta seletiva de lixo, realizados por associações ou cooperativas formadas exclusivamente de pessoas físicas de baixa renda reconhecidas pelo poder público como catadores de materiais recicláveis, com o uso de equipamentos compatíveis com as normas técnicas, ambientais e de saúde pública;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nj) coleta, processamento e comercialização de resíduos sólidos urbanos recicláveis ou reutilizáveis, em áreas com sistema de coleta seletiva de lixo, realizados por associações ou cooperativas formadas predominantemente de pessoas físicas de baixa renda reconhecidas pelo poder público como catadores de materiais recicláveis, com o uso de equipamentos compatíveis com as normas técnicas, ambientais e de saúde pública;","answer":false,"explanation":"A associação ou cooperativa deve ser formada exclusivamente por pessoas físicas de baixa renda reconhecidas como catadores.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0173","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea k","number":"Art. 75, caput, inciso IV, alínea k","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nk) aquisição ou restauração de obras de arte e objetos históricos, de autenticidade certificada, desde que inerente às finalidades do órgão ou com elas compatível;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nk) aquisição ou restauração de obras de arte e objetos históricos, de autenticidade certificada, desde que inerente às finalidades do órgão ou com elas compatível;","answer":true,"explanation":"A autenticidade deve ser certificada e a obra de arte ou objeto histórico deve se relacionar com as finalidades do órgão.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0174","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea l","number":"Art. 75, caput, inciso IV, alínea l","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nl) serviços especializados ou aquisição ou locação de equipamentos destinados ao rastreamento e à obtenção de provas previstas nos incisos II e V do caput do art. 3º da Lei nº 12.850, de 2 de agosto de 2013, quando houver necessidade justificada de manutenção de sigilo sobre a investigação;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nl) serviços especializados ou aquisição ou locação de equipamentos destinados ao rastreamento e à obtenção de provas previstas nos incisos II e V do caput do art. 3º da Lei nº 12.850, de 2 de agosto de 2013, quando houver mera conveniência de manutenção de sigilo sobre a investigação;","answer":false,"explanation":"A necessidade de sigilo sobre a investigação deve ser justificada.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0175","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput, inciso IV, alínea m","number":"Art. 75, caput, inciso IV, alínea m","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nm) aquisição de medicamentos destinados exclusivamente ao tratamento de doenças raras definidas pelo Ministério da Saúde;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIV - para contratação que tenha por objeto:\nm) aquisição de medicamentos destinados exclusivamente ao tratamento de doenças raras definidas pelo Ministério da Saúde;","answer":true,"explanation":"Os medicamentos devem destinar-se exclusivamente a doenças raras definidas pelo Ministério da Saúde.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0176","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso V","number":"Art. 75, caput e inciso V","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nV - para contratação com vistas ao cumprimento do disposto nos arts. 3º, 3º-A, 4º, 5º e 20 da Lei nº 10.973, de 2 de dezembro de 2004, observados os princípios gerais de contratação constantes da referida Lei;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nV - para contratação com vistas ao cumprimento do disposto nos arts. 3º, 3º-A, 4º, 5º e 20 da Lei nº 10.973, de 2 de dezembro de 2004, observados os princípios gerais de contratação constantes da referida Lei;","answer":true,"explanation":"A contratação para cumprir os dispositivos da Lei de Inovação observa os princípios gerais de contratação da própria lei referida.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0177","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso VI","number":"Art. 75, caput e inciso VI","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nVI - para contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministro de Estado da Defesa, mediante demanda dos comandos das Forças Armadas ou dos demais ministérios;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nVI - para contratação que possa acarretar comprometimento da segurança nacional, nos casos estabelecidos pelo Ministro de Estado da Justiça, mediante demanda dos comandos das Forças Armadas ou dos demais ministérios;","answer":false,"explanation":"A definição dos casos cabe ao Ministro da Defesa, mediante demanda dos comandos ou dos demais ministérios.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0178","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso VII","number":"Art. 75, caput e inciso VII","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nVII - nos casos de guerra, estado de defesa, estado de sítio, intervenção federal ou de grave perturbação da ordem;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nVII - nos casos de guerra, estado de defesa, estado de sítio, intervenção federal ou de grave perturbação da ordem;","answer":true,"explanation":"Guerra, estados de defesa ou de sítio, intervenção federal e grave perturbação da ordem figuram como hipóteses de dispensa.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0179","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso VIII","number":"Art. 75, caput e inciso VIII","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nVIII - nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens, públicos ou particulares, e somente para aquisição dos bens necessários ao atendimento da situação emergencial ou calamitosa e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 (um) ano, contado da data de ocorrência da emergência ou da calamidade, vedadas a prorrogação dos respectivos contratos e a recontratação de empresa já contratada com base no disposto neste inciso;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nVIII - nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens, públicos ou particulares, e somente para aquisição dos bens necessários ao atendimento da situação emergencial ou calamitosa e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 (um) ano, contado da assinatura do contrato, vedadas a prorrogação dos respectivos contratos e a recontratação de empresa já contratada com base no disposto neste inciso;","answer":false,"explanation":"O prazo máximo de um ano se conta da ocorrência da emergência ou calamidade; a prorrogação e a recontratação indicadas são vedadas.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0180","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso VIII","number":"Art. 75, caput e inciso VIII","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nVIII - nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens, públicos ou particulares, e somente para aquisição dos bens necessários ao atendimento da situação emergencial ou calamitosa e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 (um) ano, contado da data de ocorrência da emergência ou da calamidade, vedadas a prorrogação dos respectivos contratos e a recontratação de empresa já contratada com base no disposto neste inciso;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nVIII - nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens, públicos ou particulares, e somente para aquisição dos bens necessários ao atendimento da situação emergencial ou calamitosa e para as parcelas de obras e serviços que possam ser concluídas no prazo máximo de 1 (um) ano, contado da data de ocorrência da emergência ou da calamidade, permitidas a prorrogação dos respectivos contratos e a recontratação de empresa já contratada com base no disposto neste inciso;","answer":false,"explanation":"O dispositivo veda prorrogação dos respectivos contratos e recontratação da mesma empresa com base no inciso VIII.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0181","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso IX","number":"Art. 75, caput e inciso IX","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nIX - para a aquisição, por pessoa jurídica de direito público interno, de bens produzidos ou serviços prestados por órgão ou entidade que integrem a Administração Pública e que tenham sido criados para esse fim específico, desde que o preço contratado seja compatível com o praticado no mercado;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nIX - para a aquisição, por pessoa jurídica de direito público interno, de bens produzidos ou serviços prestados por órgão ou entidade que integrem a Administração Pública e que tenham sido criados para esse fim específico, desde que o preço contratado seja compatível com o praticado no mercado;","answer":true,"explanation":"A adquirente é pessoa jurídica de direito público interno; o fornecedor público foi criado para esse fim, com preço compatível.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0182","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso X","number":"Art. 75, caput e inciso X","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nX - quando a União tiver que intervir no domínio econômico para regular preços ou normalizar o abastecimento;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nX - quando o Município tiver que intervir no domínio econômico para regular preços ou normalizar o abastecimento;","answer":false,"explanation":"A intervenção no domínio econômico da hipótese cabe à União, para regular preços ou abastecimento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0183","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XI","number":"Art. 75, caput e inciso XI","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXI - para celebração de contrato de programa com ente federativo ou com entidade de sua Administração Pública indireta que envolva prestação de serviços públicos de forma associada nos termos autorizados em contrato de consórcio público ou em convênio de cooperação;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXI - para celebração de contrato de programa com ente federativo ou com entidade de sua Administração Pública indireta que envolva prestação de serviços públicos de forma associada nos termos autorizados em contrato de consórcio público ou em convênio de cooperação;","answer":true,"explanation":"O contrato de programa envolve prestação associada de serviços públicos autorizada em consórcio ou convênio de cooperação.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0184","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XII","number":"Art. 75, caput e inciso XII","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXII - para contratação em que houver transferência de tecnologia de produtos estratégicos para o Sistema Único de Saúde (SUS), conforme elencados em ato da direção nacional do SUS, inclusive por ocasião da aquisição desses produtos durante as etapas de absorção tecnológica, e em valores compatíveis com aqueles definidos no instrumento firmado para a transferência de tecnologia;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXII - para contratação em que houver transferência de tecnologia de produtos estratégicos para o Sistema Único de Saúde (SUS), conforme elencados em ato da direção estadual do SUS, inclusive por ocasião da aquisição desses produtos durante as etapas de absorção tecnológica, e em valores compatíveis com aqueles definidos no instrumento firmado para a transferência de tecnologia;","answer":false,"explanation":"Os produtos estratégicos para o SUS são elencados em ato da direção nacional.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0185","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XIII","number":"Art. 75, caput e inciso XIII","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXIII - para contratação de profissionais para compor a comissão de avaliação de critérios de técnica, quando se tratar de profissional técnico de notória especialização;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXIII - para contratação de profissionais para compor a comissão de avaliação de critérios de técnica, quando se tratar de profissional técnico de notória especialização;","answer":true,"explanation":"A comissão avalia critérios de técnica, e o profissional técnico deve ter notória especialização.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0186","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XIV","number":"Art. 75, caput e inciso XIV","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXIV - para contratação de associação de pessoas com deficiência, sem fins lucrativos e de comprovada idoneidade, por órgão ou entidade da Administração Pública, para a prestação de serviços, desde que o preço contratado seja compatível com o praticado no mercado e os serviços contratados sejam prestados exclusivamente por pessoas com deficiência;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXIV - para contratação de associação de pessoas com deficiência, sem fins lucrativos e de comprovada idoneidade, por órgão ou entidade da Administração Pública, para a prestação de serviços, desde que o preço contratado seja compatível com o praticado no mercado e os serviços contratados sejam prestados preferencialmente por pessoas com deficiência;","answer":false,"explanation":"O serviço contratado da associação deve ser prestado exclusivamente por pessoas com deficiência.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0187","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XV","number":"Art. 75, caput e inciso XV","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXV - para contratação de instituição brasileira que tenha por finalidade estatutária apoiar, captar e executar atividades de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e estímulo à inovação, inclusive para gerir administrativa e financeiramente essas atividades, ou para contratação de instituição dedicada à recuperação social da pessoa presa, desde que o contratado tenha inquestionável reputação ética e profissional e não tenha fins lucrativos;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXV - para contratação de instituição brasileira que tenha por finalidade estatutária apoiar, captar e executar atividades de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e estímulo à inovação, inclusive para gerir administrativa e financeiramente essas atividades, ou para contratação de instituição dedicada à recuperação social da pessoa presa, desde que o contratado tenha inquestionável reputação ética e profissional e não tenha fins lucrativos;","answer":true,"explanation":"As instituições descritas dependem de reputação ética e profissional inquestionável e ausência de fins lucrativos.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0188","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XVI","number":"Art. 75, caput e inciso XVI","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXVI - para aquisição, por pessoa jurídica de direito público interno, de produtos estratégicos para a saúde fornecidos por produtores públicos por intermédio de fundação que, regimental ou estatutariamente, tenha por finalidade apoiar órgão da Administração Pública direta, sua autarquia ou fundação em projetos de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e de estímulo à inovação, inclusive na gestão administrativa e financeira necessária à execução desses projetos, ou em parcerias que envolvam transferência de tecnologia de produtos estratégicos para o SUS, nos termos do inciso XII deste caput, e que tenha sido criada para esse fim específico em data anterior à entrada em vigor desta Lei, desde que o preço contratado seja compatível com o praticado no mercado;"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXVI - para aquisição, por pessoa jurídica de direito público interno, de produtos estratégicos para a saúde fornecidos por produtores privados por intermédio de fundação que, regimental ou estatutariamente, tenha por finalidade apoiar órgão da Administração Pública direta, sua autarquia ou fundação em projetos de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e de estímulo à inovação, inclusive na gestão administrativa e financeira necessária à execução desses projetos, ou em parcerias que envolvam transferência de tecnologia de produtos estratégicos para o SUS, nos termos do inciso XII deste caput, e que tenha sido criada para esse fim específico em data anterior à entrada em vigor desta Lei, desde que o preço contratado seja compatível com o praticado no mercado;","answer":false,"explanation":"A redação de 2026 contempla produtores públicos por intermédio da fundação, entre os requisitos restantes.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0189","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, caput e inciso XVII","number":"Art. 75, caput e inciso XVII","title":"Lei nº 14.133/2021 · Licitações","parts":["Art. 75. É dispensável a licitação:\nXVII - para contratação de entidades privadas sem fins lucrativos para a implementação de cisternas ou outras tecnologias sociais de acesso à água para consumo humano e produção de alimentos, a fim de beneficiar as famílias rurais de baixa renda atingidas pela seca ou pela falta regular de água; e"],"origin":"authorial","question":{"statement":"Art. 75. É dispensável a licitação:\nXVII - para contratação de entidades privadas sem fins lucrativos para a implementação de cisternas ou outras tecnologias sociais de acesso à água para consumo humano e produção de alimentos, a fim de beneficiar as famílias rurais de baixa renda atingidas pela seca ou pela falta regular de água; e","answer":true,"explanation":"A implementação de cisternas e outras tecnologias sociais por entidade privada sem fins lucrativos beneficia famílias rurais de baixa renda.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0191","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 1º, I","number":"Art. 75, § 1º, I","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 1º Para fins de aferição dos valores que atendam aos limites referidos nos incisos I e II do caput deste artigo, deverão ser observados:\nI - o somatório do que for despendido no exercício financeiro pela respectiva unidade gestora;"],"origin":"authorial","question":{"statement":"§ 1º Para fins de aferição dos valores que atendam aos limites referidos nos incisos I e II do caput deste artigo, deverão ser observados:\nI - o somatório do que for despendido no exercício financeiro pela respectiva unidade gestora;","answer":true,"explanation":"O somatório da despesa da unidade gestora no exercício financeiro compõe a aferição do limite dos incisos I e II.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0192","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 1º, II","number":"Art. 75, § 1º, II","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 1º Para fins de aferição dos valores que atendam aos limites referidos nos incisos I e II do caput deste artigo, deverão ser observados:\nII - o somatório da despesa realizada com objetos de mesma natureza, entendidos como tais aqueles relativos a contratações no mesmo ramo de atividade."],"origin":"authorial","question":{"statement":"§ 1º Para fins de aferição dos valores que atendam aos limites referidos nos incisos I e II do caput deste artigo, deverão ser observados:\nII - o somatório da despesa realizada com objetos de mesma natureza, entendidos como tais aqueles relativos a contratações em qualquer ramo de atividade.","answer":false,"explanation":"A soma por objetos de mesma natureza utiliza o mesmo ramo de atividade.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0193","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 2º","number":"Art. 75, § 2º","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 2º Os valores referidos nos incisos I e II do caput deste artigo serão duplicados para compras, obras e serviços contratados por consórcio público ou por autarquia ou fundação qualificadas como agências executivas na forma da lei."],"origin":"authorial","question":{"statement":"§ 2º Os valores referidos nos incisos I e II do caput deste artigo serão duplicados para compras, obras e serviços contratados por consórcio público ou por autarquia ou fundação qualificadas como agências executivas na forma da lei.","answer":true,"explanation":"A duplicação dos valores beneficia consórcio público ou autarquia ou fundação qualificada como agência executiva.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0194","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 3º","number":"Art. 75, § 3º","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 3º As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente precedidas de divulgação de aviso em sítio eletrônico oficial, pelo prazo mínimo de 3 (três) dias úteis, com a especificação do objeto pretendido e com a manifestação de interesse da Administração em obter propostas adicionais de eventuais interessados, devendo ser selecionada a proposta mais vantajosa."],"origin":"authorial","question":{"statement":"§ 3º As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente precedidas de divulgação de aviso em sítio eletrônico oficial, pelo prazo máximo de 3 (três) dias úteis, com a especificação do objeto pretendido e com a manifestação de interesse da Administração em obter propostas adicionais de eventuais interessados, devendo ser selecionada a proposta mais vantajosa.","answer":false,"explanation":"A publicação é preferencial, por no mínimo três dias úteis, para colher propostas adicionais e selecionar a mais vantajosa.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0195","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 4º","number":"Art. 75, § 4º","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 4º As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente pagas por meio de cartão de pagamento, cujo extrato deverá ser divulgado e mantido à disposição do público no Portal Nacional de Contratações Públicas (PNCP)."],"origin":"authorial","question":{"statement":"§ 4º As contratações de que tratam os incisos I e II do caput deste artigo serão preferencialmente pagas por meio de cartão de pagamento, cujo extrato deverá ser divulgado e mantido à disposição do público no Portal Nacional de Contratações Públicas (PNCP).","answer":true,"explanation":"O pagamento por cartão é preferencial; o extrato deve ser divulgado no PNCP.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0196","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 5º","number":"Art. 75, § 5º","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 5º A dispensa prevista na alínea “c” do inciso IV do caput deste artigo, quando aplicada a obras e serviços de engenharia, seguirá procedimentos especiais instituídos em regulamentação específica."],"origin":"authorial","question":{"statement":"§ 5º A dispensa prevista na alínea “c” do inciso IV do caput deste artigo, quando aplicada a quaisquer compras, seguirá procedimentos especiais instituídos em regulamentação específica.","answer":false,"explanation":"A regulamentação especial se aplica à dispensa da alínea c quando ligada a obras e serviços de engenharia.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0197","discipline":"adm","topicId":"led-adm-licitacoes-14133","subtopic":"Art. 75, § 6º","number":"Art. 75, § 6º","title":"Lei nº 14.133/2021 · Licitações","parts":["§ 6º Para os fins do inciso VIII do caput deste artigo, considera-se emergencial a contratação por dispensa com objetivo de manter a continuidade do serviço público, e deverão ser observados os valores praticados pelo mercado na forma do art. 23 desta Lei e adotadas as providências necessárias para a conclusão do processo licitatório, sem prejuízo de apuração de responsabilidade dos agentes públicos que deram causa à situação emergencial."],"origin":"authorial","question":{"statement":"§ 6º Para os fins do inciso VIII do caput deste artigo, considera-se emergencial a contratação por dispensa com objetivo de manter a continuidade do serviço público, e deverão ser observados os valores praticados pelo mercado na forma do art. 23 desta Lei e adotadas as providências necessárias para a conclusão do processo licitatório, sem prejuízo de apuração de responsabilidade dos agentes públicos que deram causa à situação emergencial.","answer":true,"explanation":"Na emergência para continuidade de serviço público, há preço de mercado, providências licitatórias e eventual responsabilização dos agentes.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0199","discipline":"adm","topicId":"led-adm-decreto-12807","subtopic":"Art. 1º, caput","number":"Art. 1º, caput","title":"Decreto nº 12.807/2025","parts":["Art. 1º Ficam atualizados os valores estabelecidos na Lei nº 14.133, de 1º de abril de 2021, na forma do Anexo."],"origin":"authorial","question":{"statement":"Art. 1º Ficam atualizados os valores estabelecidos na Lei nº 14.133, de 1º de abril de 2021, na forma do Anexo.","answer":true,"explanation":"O Decreto atualiza os valores da Lei nº 14.133 conforme seu anexo.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0200","discipline":"adm","topicId":"led-adm-decreto-12807","subtopic":"Art. 2º, caput","number":"Art. 2º, caput","title":"Decreto nº 12.807/2025","parts":["Art. 2º A atualização dos valores de que trata o art. 1º será divulgada no Portal Nacional de Contratações Públicas – PNCP, conforme o disposto no art. 182 da Lei nº 14.133, de 1º de abril de 2021."],"origin":"authorial","question":{"statement":"Art. 2º A atualização dos valores de que trata o art. 1º será divulgada no Diário Oficial do Município, conforme o disposto no art. 182 da Lei nº 14.133, de 1º de abril de 2021.","answer":false,"explanation":"A divulgação dos valores atualizados ocorre no PNCP.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0201","discipline":"adm","topicId":"led-adm-decreto-12807","subtopic":"Art. 3º, caput","number":"Art. 3º, caput","title":"Decreto nº 12.807/2025","parts":["Art. 3º Fica delegada à autoridade máxima do Ministério da Gestão e da Inovação em Serviços Públicos a competência para atualizar, nos exercícios subsequentes, os valores de que trata o art. 1º."],"origin":"authorial","question":{"statement":"Art. 3º Fica delegada à autoridade máxima do Ministério da Gestão e da Inovação em Serviços Públicos a competência para atualizar, nos exercícios subsequentes, os valores de que trata o art. 1º.","answer":true,"explanation":"A competência para exercícios subsequentes foi delegada à autoridade máxima do Ministério da Gestão e da Inovação.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0202","discipline":"adm","topicId":"led-adm-decreto-12807","subtopic":"Art. 5º, caput","number":"Art. 5º, caput","title":"Decreto nº 12.807/2025","parts":["Art. 5º Este Decreto entra em vigor em 1º de janeiro de 2026."],"origin":"authorial","question":{"statement":"Art. 5º Este Decreto entra em vigor em 1º de janeiro de 2027.","answer":false,"explanation":"O Decreto nº 12.807 passou a vigorar em 1º de janeiro de 2026.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12807.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0212","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 10","number":"Art. 10","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 10. O legítimo interesse do controlador somente poderá fundamentar tratamento de dados pessoais para finalidades legítimas, consideradas a partir de situações concretas, que incluem, mas não se limitam a:"],"origin":"authorial","question":{"statement":"Art. 10. O legítimo interesse do controlador somente poderá fundamentar tratamento de dados pessoais para finalidades definidas exclusivamente pelo controlador, consideradas a partir de situações concretas, que incluem, mas não se limitam a:","answer":false,"explanation":"As finalidades devem ser legítimas e consideradas a partir de situações concretas; a definição exclusiva pelo controlador não basta.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0213","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 10, inc. I","number":"Art. 10, inc. I","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 10. O legítimo interesse do controlador somente poderá fundamentar tratamento de dados pessoais para finalidades legítimas, consideradas a partir de situações concretas, que incluem, mas não se limitam a:\nI - apoio e promoção de atividades do controlador; e"],"origin":"authorial","question":{"statement":"Art. 10. O legítimo interesse do controlador somente poderá fundamentar tratamento de dados pessoais para finalidades legítimas, consideradas a partir de situações concretas, que incluem, mas não se limitam a:\nI - apoio e promoção de atividades do controlador; e","answer":true,"explanation":"O apoio e a promoção de atividades do controlador são finalidades concretas possíveis do legítimo interesse.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0215","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 10, § 1º","number":"Art. 10, § 1º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 1º Quando o tratamento for baseado no legítimo interesse do controlador, somente os dados pessoais estritamente necessários para a finalidade pretendida poderão ser tratados."],"origin":"authorial","question":{"statement":"§ 1º Quando o tratamento for baseado no legítimo interesse do controlador, somente os dados pessoais estritamente necessários para a finalidade pretendida poderão ser tratados.","answer":true,"explanation":"Somente dados estritamente necessários à finalidade pretendida podem ser tratados com base no legítimo interesse.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0216","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 10, § 2º","number":"Art. 10, § 2º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 2º O controlador deverá adotar medidas para garantir a transparência do tratamento de dados baseado em seu legítimo interesse."],"origin":"authorial","question":{"statement":"§ 2º O operador deverá adotar medidas para garantir a transparência do tratamento de dados baseado em seu legítimo interesse.","answer":false,"explanation":"A transparência no tratamento fundado em legítimo interesse é dever do controlador.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0217","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 10, § 3º","number":"Art. 10, § 3º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 3º A autoridade nacional poderá solicitar ao controlador relatório de impacto à proteção de dados pessoais, quando o tratamento tiver como fundamento seu interesse legítimo, observados os segredos comercial e industrial."],"origin":"authorial","question":{"statement":"§ 3º A autoridade nacional poderá solicitar ao controlador relatório de impacto à proteção de dados pessoais, quando o tratamento tiver como fundamento seu interesse legítimo, observados os segredos comercial e industrial.","answer":true,"explanation":"A solicitação de relatório pela autoridade nacional é facultativa e resguarda segredos comercial e industrial.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0218","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 12","number":"Art. 12","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 12. Os dados anonimizados não serão considerados dados pessoais para os fins desta Lei, salvo quando o processo de anonimização ao qual foram submetidos for revertido, utilizando exclusivamente meios próprios, ou quando, com esforços razoáveis, puder ser revertido."],"origin":"authorial","question":{"statement":"Art. 12. Os dados anonimizados não serão considerados dados pessoais para os fins desta Lei, salvo quando o processo de anonimização ao qual foram submetidos for revertido, utilizando exclusivamente meios próprios, ou quando, apenas com meios próprios, puder ser revertido.","answer":false,"explanation":"A reversão com esforços razoáveis afasta a anonimização ainda que não use exclusivamente meios próprios.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0219","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 12, § 1º","number":"Art. 12, § 1º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 1º A determinação do que seja razoável deve levar em consideração fatores objetivos, tais como custo e tempo necessários para reverter o processo de anonimização, de acordo com as tecnologias disponíveis, e a utilização exclusiva de meios próprios."],"origin":"authorial","question":{"statement":"§ 1º A determinação do que seja razoável deve levar em consideração fatores objetivos, tais como custo e tempo necessários para reverter o processo de anonimização, de acordo com as tecnologias disponíveis, e a utilização exclusiva de meios próprios.","answer":true,"explanation":"A reversibilidade razoável considera custo, tempo, tecnologia disponível e uso exclusivo de meios próprios.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0220","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 12, § 2º","number":"Art. 12, § 2º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 2º Poderão ser igualmente considerados como dados pessoais, para os fins desta Lei, aqueles utilizados para formação do perfil comportamental de determinada pessoa natural, se identificada."],"origin":"authorial","question":{"statement":"§ 2º Poderão ser igualmente considerados como dados pessoais, para os fins desta Lei, aqueles utilizados para formação do perfil comportamental de determinada pessoa natural, mesmo quando não identificada.","answer":false,"explanation":"A identificação da pessoa natural é condição expressa para a equiparação desse perfil a dado pessoal.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0221","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 12, § 3º","number":"Art. 12, § 3º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 3º A autoridade nacional poderá dispor sobre padrões e técnicas utilizados em processos de anonimização e realizar verificações acerca de sua segurança, ouvido o Conselho Nacional de Proteção de Dados Pessoais."],"origin":"authorial","question":{"statement":"§ 3º A autoridade nacional poderá dispor sobre padrões e técnicas utilizados em processos de anonimização e realizar verificações acerca de sua segurança, ouvido o Conselho Nacional de Proteção de Dados Pessoais.","answer":true,"explanation":"A autoridade pode definir padrões e verificar segurança, depois de ouvir o Conselho Nacional.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0223","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 14, § 1º","number":"Art. 14, § 1º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 1º O tratamento de dados pessoais de crianças deverá ser realizado com o consentimento específico e em destaque dado por pelo menos um dos pais ou pelo responsável legal."],"origin":"authorial","question":{"statement":"§ 1º O tratamento de dados pessoais de crianças deverá ser realizado com o consentimento específico e em destaque dado por pelo menos um dos pais ou pelo responsável legal.","answer":true,"explanation":"Para dados de crianças, o consentimento deve ser específico e destacado, dado por pelo menos um pai ou responsável.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0224","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 14, § 2º","number":"Art. 14, § 2º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 2º No tratamento de dados de que trata o § 1º deste artigo, os controladores deverão manter pública a informação sobre os tipos de dados coletados, a forma de sua utilização e os procedimentos para o exercício dos direitos a que se refere o art. 18 desta Lei."],"origin":"authorial","question":{"statement":"§ 2º No tratamento de dados de que trata o § 1º deste artigo, os controladores deverão manter reservada a informação sobre os tipos de dados coletados, a forma de sua utilização e os procedimentos para o exercício dos direitos a que se refere o art. 18 desta Lei.","answer":false,"explanation":"Os controladores devem tornar públicas as informações listadas sobre os dados das crianças.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0225","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 14, § 3º","number":"Art. 14, § 3º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 3º Poderão ser coletados dados pessoais de crianças sem o consentimento a que se refere o § 1º deste artigo quando a coleta for necessária para contatar os pais ou o responsável legal, utilizados uma única vez e sem armazenamento, ou para sua proteção, e em nenhum caso poderão ser repassados a terceiro sem o consentimento de que trata o § 1º deste artigo."],"origin":"authorial","question":{"statement":"§ 3º Poderão ser coletados dados pessoais de crianças sem o consentimento a que se refere o § 1º deste artigo quando a coleta for necessária para contatar os pais ou o responsável legal, utilizados uma única vez e com armazenamento, ou para sua proteção, e em nenhum caso poderão ser repassados a terceiro sem o consentimento de que trata o § 1º deste artigo.","answer":false,"explanation":"Na hipótese de contato com os pais ou responsável, os dados são utilizados uma única vez e sem armazenamento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0226","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 14, § 4º","number":"Art. 14, § 4º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 4º Os controladores não deverão condicionar a participação dos titulares de que trata o § 1º deste artigo em jogos, aplicações de internet ou outras atividades ao fornecimento de informações pessoais além das estritamente necessárias à atividade."],"origin":"authorial","question":{"statement":"§ 4º Os controladores não deverão condicionar a participação dos titulares de que trata o § 1º deste artigo em jogos, aplicações de internet ou outras atividades ao fornecimento de informações pessoais além das estritamente necessárias à atividade.","answer":true,"explanation":"A participação em jogos ou aplicações não pode depender de dados além dos estritamente necessários.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0227","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 14, § 5º","number":"Art. 14, § 5º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 5º O controlador deve realizar todos os esforços razoáveis para verificar que o consentimento a que se refere o § 1º deste artigo foi dado pelo responsável pela criança, consideradas as tecnologias disponíveis."],"origin":"authorial","question":{"statement":"§ 5º O controlador deve realizar todos os esforços razoáveis para verificar que o consentimento a que se refere o § 1º deste artigo foi dado pelo própria criança, consideradas as tecnologias disponíveis.","answer":false,"explanation":"O controlador verifica, por esforços razoáveis, que o consentimento foi dado pelo responsável.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0228","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 14, § 6º","number":"Art. 14, § 6º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 6º As informações sobre o tratamento de dados referidas neste artigo deverão ser fornecidas de maneira simples, clara e acessível, consideradas as características físico-motoras, perceptivas, sensoriais, intelectuais e mentais do usuário, com uso de recursos audiovisuais quando adequado, de forma a proporcionar a informação necessária aos pais ou ao responsável legal e adequada ao entendimento da criança."],"origin":"authorial","question":{"statement":"§ 6º As informações sobre o tratamento de dados referidas neste artigo deverão ser fornecidas de maneira simples, clara e acessível, consideradas as características físico-motoras, perceptivas, sensoriais, intelectuais e mentais do usuário, com uso de recursos audiovisuais quando adequado, de forma a proporcionar a informação necessária aos pais ou ao responsável legal e adequada ao entendimento da criança.","answer":true,"explanation":"A comunicação deve ser adequada às características do usuário e ao entendimento da criança, com recursos audiovisuais quando couber.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0230","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 19, inc. I","number":"Art. 19, inc. I","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 19. A confirmação de existência ou o acesso a dados pessoais serão providenciados, mediante requisição do titular:\nI - em formato simplificado, imediatamente; ou"],"origin":"authorial","question":{"statement":"Art. 19. A confirmação de existência ou o acesso a dados pessoais serão providenciados, mediante requisição do titular:\nI - em formato simplificado, imediatamente; ou","answer":true,"explanation":"A resposta simplificada ao titular é imediata; o inciso II prevê a alternativa de declaração completa.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0231","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 19, inc. II","number":"Art. 19, inc. II","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 19. A confirmação de existência ou o acesso a dados pessoais serão providenciados, mediante requisição do titular:\nII - por meio de declaração clara e completa, que indique a origem dos dados, a inexistência de registro, os critérios utilizados e a finalidade do tratamento, observados os segredos comercial e industrial, fornecida no prazo de até 15 (quinze) dias, contado da data do requerimento do titular."],"origin":"authorial","question":{"statement":"Art. 19. A confirmação de existência ou o acesso a dados pessoais serão providenciados, mediante requisição do titular:\nII - por meio de declaração clara e completa, que indique a origem dos dados, a inexistência de registro, os critérios utilizados e a finalidade do tratamento, observados os segredos comercial e industrial, fornecida no prazo de até 30 (trinta) dias, contado da data do requerimento do titular.","answer":false,"explanation":"A declaração clara e completa é fornecida em até quinze dias contados do requerimento do titular.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0232","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 19, § 1º","number":"Art. 19, § 1º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 1º Os dados pessoais serão armazenados em formato que favoreça o exercício do direito de acesso."],"origin":"authorial","question":{"statement":"§ 1º Os dados pessoais serão armazenados em formato que favoreça o exercício do direito de acesso.","answer":true,"explanation":"O formato de armazenamento deve favorecer o exercício do direito de acesso.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0235","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 19, § 2º, inc. II","number":"Art. 19, § 2º, inc. II","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 2º As informações e os dados poderão ser fornecidos, a critério do titular:\nII - sob forma impressa."],"origin":"authorial","question":{"statement":"§ 2º As informações e os dados poderão ser fornecidos, a critério do titular:\nII - sob forma impressa.","answer":true,"explanation":"A forma impressa é alternativa, a critério do titular, ao meio eletrônico.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0236","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 19, § 3º","number":"Art. 19, § 3º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 3º Quando o tratamento tiver origem no consentimento do titular ou em contrato, o titular poderá solicitar cópia eletrônica integral de seus dados pessoais, observados os segredos comercial e industrial, nos termos de regulamentação da autoridade nacional, em formato que permita a sua utilização subsequente, inclusive em outras operações de tratamento."],"origin":"authorial","question":{"statement":"§ 3º Quando o tratamento tiver origem exclusivamente no consentimento do titular, o titular poderá solicitar cópia eletrônica integral de seus dados pessoais, observados os segredos comercial e industrial, nos termos de regulamentação da autoridade nacional, em formato que permita a sua utilização subsequente, inclusive em outras operações de tratamento.","answer":false,"explanation":"A cópia eletrônica integral cabe tanto no tratamento fundado em consentimento quanto no originado em contrato.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0237","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 19, § 4º","number":"Art. 19, § 4º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 4º A autoridade nacional poderá dispor de forma diferenciada acerca dos prazos previstos nos incisos I e II do caput deste artigo para os setores específicos."],"origin":"authorial","question":{"statement":"§ 4º A autoridade nacional poderá dispor de forma diferenciada acerca dos prazos previstos nos incisos I e II do caput deste artigo para os setores específicos.","answer":true,"explanation":"A autoridade nacional pode diferenciar prazos dos incisos I e II para setores específicos.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0238","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 20","number":"Art. 20","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 20. O titular dos dados tem direito a solicitar a revisão de decisões tomadas unicamente com base em tratamento automatizado de dados pessoais que afetem seus interesses, incluídas as decisões destinadas a definir o seu perfil pessoal, profissional, de consumo e de crédito ou os aspectos de sua personalidade."],"origin":"authorial","question":{"statement":"Art. 20. O titular dos dados tem direito a solicitar a revisão de decisões tomadas predominantemente com base em tratamento automatizado de dados pessoais que afetem seus interesses, incluídas as decisões destinadas a definir o seu perfil pessoal, profissional, de consumo e de crédito ou os aspectos de sua personalidade.","answer":false,"explanation":"O direito de pedir revisão incide sobre decisão tomada unicamente com base em tratamento automatizado.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0239","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 20, § 1º","number":"Art. 20, § 1º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 1º O controlador deverá fornecer, sempre que solicitadas, informações claras e adequadas a respeito dos critérios e dos procedimentos utilizados para a decisão automatizada, observados os segredos comercial e industrial."],"origin":"authorial","question":{"statement":"§ 1º O controlador deverá fornecer, sempre que solicitadas, informações claras e adequadas a respeito dos critérios e dos procedimentos utilizados para a decisão automatizada, observados os segredos comercial e industrial.","answer":true,"explanation":"O controlador fornece informações claras sobre critérios e procedimentos, resguardados os segredos legais.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0240","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 20, § 2º","number":"Art. 20, § 2º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 2º Em caso de não oferecimento de informações de que trata o § 1º deste artigo baseado na observância de segredo comercial e industrial, a autoridade nacional poderá realizar auditoria para verificação de aspectos discriminatórios em tratamento automatizado de dados pessoais."],"origin":"authorial","question":{"statement":"§ 2º Em caso de não oferecimento de informações de que trata o § 1º deste artigo baseado na observância de segredo comercial e industrial, o controlador poderá realizar auditoria para verificação de aspectos discriminatórios em tratamento automatizado de dados pessoais.","answer":false,"explanation":"A auditoria de aspectos discriminatórios nessa hipótese cabe à autoridade nacional.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0241","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-A","number":"Art. 55-A","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-A. Fica criada a Agência Nacional de Proteção de Dados (ANPD), autarquia de natureza especial vinculada ao Ministério da Justiça e Segurança Pública, dotada de autonomia funcional, técnica, decisória, administrativa e financeira, com patrimônio próprio e com sede e foro no Distrito Federal, nos termos da Lei nº 13.848, de 25 de junho de 2019."],"origin":"authorial","question":{"statement":"Art. 55-A. Fica criada a Agência Nacional de Proteção de Dados (ANPD), autarquia de natureza especial vinculada ao Ministério da Gestão e da Inovação em Serviços Públicos, dotada de autonomia funcional, técnica, decisória, administrativa e financeira, com patrimônio próprio e com sede e foro no Distrito Federal, nos termos da Lei nº 13.848, de 25 de junho de 2019.","answer":false,"explanation":"A ANPD é autarquia especial vinculada ao Ministério da Justiça e Segurança Pública, com as autonomias enumeradas.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0243","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. I","number":"Art. 55-J, inc. I","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nI - zelar pela proteção dos dados pessoais, nos termos da legislação;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nI - zelar pela proteção dos dados pessoais, nos termos da legislação;","answer":true,"explanation":"A competência da ANPD abrange zelar pela proteção dos dados pessoais nos termos da legislação.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0245","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. III","number":"Art. 55-J, inc. III","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nIII - elaborar diretrizes para a Política Nacional de Proteção de Dados Pessoais e da Privacidade;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nIII - elaborar diretrizes para a Política Nacional de Proteção de Dados Pessoais e da Privacidade;","answer":true,"explanation":"A elaboração de diretrizes da política nacional de dados e privacidade é atribuição da ANPD.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0246","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. IV","number":"Art. 55-J, inc. IV","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nIV - fiscalizar e aplicar sanções em caso de tratamento de dados realizado em descumprimento à legislação, mediante processo administrativo que assegure o contraditório, a ampla defesa e o direito de recurso;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nIV - fiscalizar e aplicar sanções em caso de tratamento de dados realizado em descumprimento à legislação, independentemente de processo administrativo que assegure o contraditório, a ampla defesa e o direito de recurso;","answer":false,"explanation":"A sanção pressupõe processo administrativo com contraditório, ampla defesa e recurso.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0248","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. VI","number":"Art. 55-J, inc. VI","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nVI - promover na população o conhecimento das normas e das políticas públicas sobre proteção de dados pessoais e das medidas de segurança;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nVI - promover na população o conhecimento das normas e das políticas públicas sobre proteção de dados pessoais e das medidas de segurança;","answer":true,"explanation":"A ANPD deve promover conhecimento público de normas, políticas e medidas de segurança.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0249","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. VII","number":"Art. 55-J, inc. VII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nVII - promover e elaborar estudos sobre as práticas nacionais e internacionais de proteção de dados pessoais e privacidade;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nVII - promover e elaborar estudos sobre as práticas nacionais e internacionais de proteção de dados pessoais e privacidade;","answer":true,"explanation":"Estudos sobre práticas nacionais e internacionais de proteção e privacidade integram as competências.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0250","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. VIII","number":"Art. 55-J, inc. VIII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nVIII - estimular a adoção de padrões para serviços e produtos que facilitem o exercício de controle dos titulares sobre seus dados pessoais, os quais deverão levar em consideração as especificidades das atividades e o porte dos responsáveis;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nVIII - estimular a adoção de padrões para serviços e produtos que facilitem o exercício de controle dos titulares sobre seus dados pessoais, os quais deverão levar em consideração apenas o porte dos responsáveis;","answer":false,"explanation":"Os padrões devem levar em conta especificidades da atividade e porte dos responsáveis.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0251","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. IX","number":"Art. 55-J, inc. IX","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nIX - promover ações de cooperação com autoridades de proteção de dados pessoais de outros países, de natureza internacional ou transnacional;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nIX - promover ações de cooperação com autoridades de proteção de dados pessoais de outros países, de natureza internacional ou transnacional;","answer":true,"explanation":"A cooperação com autoridades estrangeiras alcança âmbitos internacional ou transnacional.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0252","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. X","number":"Art. 55-J, inc. X","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nX - dispor sobre as formas de publicidade das operações de tratamento de dados pessoais, respeitados os segredos comercial e industrial;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nX - dispor sobre as formas de publicidade das operações de tratamento de dados pessoais, respeitados os segredos comercial e industrial;","answer":true,"explanation":"A publicidade das operações é regulada com respeito aos segredos comercial e industrial.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0253","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XI","number":"Art. 55-J, inc. XI","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXI - solicitar, a qualquer momento, às entidades do poder público que realizem operações de tratamento de dados pessoais informe específico sobre o âmbito, a natureza dos dados e os demais detalhes do tratamento realizado, com a possibilidade de emitir parecer técnico complementar para garantir o cumprimento desta Lei;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXI - solicitar, somente após ordem judicial, às entidades do poder público que realizem operações de tratamento de dados pessoais informe específico sobre o âmbito, a natureza dos dados e os demais detalhes do tratamento realizado, com a possibilidade de emitir parecer técnico complementar para garantir o cumprimento desta Lei;","answer":false,"explanation":"A ANPD pode pedir informações específicas ao poder público a qualquer momento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0254","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XII","number":"Art. 55-J, inc. XII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXII - elaborar relatórios de gestão anuais acerca de suas atividades;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXII - elaborar relatórios de gestão anuais acerca de suas atividades;","answer":true,"explanation":"Os relatórios de gestão sobre as atividades da ANPD têm periodicidade anual.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0255","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XIII","number":"Art. 55-J, inc. XIII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXIII - editar regulamentos e procedimentos sobre proteção de dados pessoais e privacidade, bem como sobre relatórios de impacto à proteção de dados pessoais para os casos em que o tratamento representar alto risco à garantia dos princípios gerais de proteção de dados pessoais previstos nesta Lei;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXIII - editar regulamentos e procedimentos sobre proteção de dados pessoais e privacidade, bem como sobre relatórios de impacto à proteção de dados pessoais para os casos em que o tratamento representar baixo risco à garantia dos princípios gerais de proteção de dados pessoais previstos nesta Lei;","answer":false,"explanation":"A competência regulamentar quanto a relatórios de impacto relaciona-se a tratamento de alto risco.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0256","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XIV","number":"Art. 55-J, inc. XIV","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXIV - ouvir os agentes de tratamento e a sociedade em matérias de interesse relevante e prestar contas sobre suas atividades e planejamento;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXIV - ouvir os agentes de tratamento e a sociedade em matérias de interesse relevante e prestar contas sobre suas atividades e planejamento;","answer":true,"explanation":"A ANPD deve ouvir agentes e sociedade e prestar contas de suas atividades e planejamento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0257","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XV","number":"Art. 55-J, inc. XV","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXV - arrecadar e aplicar suas receitas e publicar, no relatório de gestão a que se refere o inciso XII do caput deste artigo, o detalhamento de suas receitas e despesas;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXV - arrecadar e aplicar suas receitas e publicar, no relatório de gestão a que se refere o inciso XII do caput deste artigo, o detalhamento de suas receitas e despesas;","answer":true,"explanation":"A ANPD arrecada e aplica receitas e detalha receitas e despesas no relatório anual.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0258","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XVI","number":"Art. 55-J, inc. XVI","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXVI - realizar auditorias, ou determinar sua realização, no âmbito da atividade de fiscalização de que trata o inciso IV e com a devida observância do disposto no inciso II do caput deste artigo, sobre o tratamento de dados pessoais efetuado pelos agentes de tratamento, incluído o poder público;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXVI - realizar auditorias, ou determinar sua realização, no âmbito da atividade de fiscalização de que trata o inciso IV e com a devida observância do disposto no inciso II do caput deste artigo, sobre o tratamento de dados pessoais efetuado pelos agentes de tratamento, excluído o poder público;","answer":false,"explanation":"O poder público também está sujeito à auditoria da ANPD, observadas as condições do inciso.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0259","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XVII","number":"Art. 55-J, inc. XVII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXVII - celebrar, a qualquer momento, compromisso com agentes de tratamento para eliminar irregularidade, incerteza jurídica ou situação contenciosa no âmbito de processos administrativos, de acordo com o previsto no Decreto-Lei nº 4.657, de 4 de setembro de 1942;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXVII - celebrar, a qualquer momento, compromisso com agentes de tratamento para eliminar irregularidade, incerteza jurídica ou situação contenciosa no âmbito de processos administrativos, de acordo com o previsto no Decreto-Lei nº 4.657, de 4 de setembro de 1942;","answer":true,"explanation":"A ANPD pode celebrar compromisso a qualquer momento no âmbito de processos administrativos.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0260","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XVIII","number":"Art. 55-J, inc. XVIII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXVIII - editar normas, orientações e procedimentos simplificados e diferenciados, inclusive quanto aos prazos, para que microempresas e empresas de pequeno porte, bem como iniciativas empresariais de caráter incremental ou disruptivo que se autodeclarem startups ou empresas de inovação, possam adequar-se a esta Lei;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXVIII - editar normas, orientações e procedimentos simplificados e diferenciados, excluídos os prazos, para que microempresas e empresas de pequeno porte, bem como iniciativas empresariais de caráter incremental ou disruptivo que se autodeclarem startups ou empresas de inovação, possam adequar-se a esta Lei;","answer":false,"explanation":"As normas simplificadas para microempresas, pequenas empresas e iniciativas inovadoras podem abranger prazos.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0261","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XIX","number":"Art. 55-J, inc. XIX","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXIX - garantir que o tratamento de dados de idosos seja efetuado de maneira simples, clara, acessível e adequada ao seu entendimento, nos termos desta Lei e da Lei nº 10.741, de 1º de outubro de 2003 (Estatuto do Idoso);"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXIX - garantir que o tratamento de dados de idosos seja efetuado de maneira simples, clara, acessível e adequada ao seu entendimento, nos termos desta Lei e da Lei nº 10.741, de 1º de outubro de 2003 (Estatuto do Idoso);","answer":true,"explanation":"O tratamento de dados de idosos deve ser simples, claro, acessível e adequado a seu entendimento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0262","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XX","number":"Art. 55-J, inc. XX","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXX - deliberar, na esfera administrativa, em caráter terminativo, sobre a interpretação desta Lei, as suas competências e os casos omissos;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXX - deliberar, na esfera administrativa, em caráter meramente consultivo, sobre a interpretação desta Lei, as suas competências e os casos omissos;","answer":false,"explanation":"A deliberação administrativa sobre interpretação, competências e omissões tem caráter terminativo.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0263","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XXI","number":"Art. 55-J, inc. XXI","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXXI - comunicar às autoridades competentes as infrações penais das quais tiver conhecimento;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXXI - comunicar às autoridades competentes as infrações penais das quais tiver conhecimento;","answer":true,"explanation":"Infrações penais conhecidas pela ANPD são comunicadas às autoridades competentes.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0264","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XXII","number":"Art. 55-J, inc. XXII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXXII - comunicar aos órgãos de controle interno o descumprimento do disposto nesta Lei por órgãos e entidades da administração pública federal;"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXXII - comunicar aos órgãos de controle externo o descumprimento do disposto nesta Lei por órgãos e entidades da administração pública federal;","answer":false,"explanation":"A comunicação de descumprimento por entidade federal é dirigida aos órgãos de controle interno.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0265","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XXIII","number":"Art. 55-J, inc. XXIII","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXXIII - articular-se com as autoridades reguladoras públicas para exercer suas competências em setores específicos de atividades econômicas e governamentais sujeitas à regulação; e"],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXXIII - articular-se com as autoridades reguladoras públicas para exercer suas competências em setores específicos de atividades econômicas e governamentais sujeitas à regulação; e","answer":true,"explanation":"A articulação com reguladores públicos alcança setores específicos regulados.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0266","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, inc. XXIV","number":"Art. 55-J, inc. XXIV","title":"Lei nº 13.709/2018 · LGPD","parts":["Art. 55-J. Compete à ANPD:\nXXIV - implementar mecanismos simplificados, inclusive por meio eletrônico, para o registro de reclamações sobre o tratamento de dados pessoais em desconformidade com esta Lei."],"origin":"authorial","question":{"statement":"Art. 55-J. Compete à ANPD:\nXXIV - implementar mecanismos simplificados, exclusivamente por meio eletrônico, para o registro de reclamações sobre o tratamento de dados pessoais em desconformidade com esta Lei.","answer":false,"explanation":"A lei inclui o meio eletrônico entre os mecanismos simplificados; não o torna exclusivo.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0267","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, § 1º","number":"Art. 55-J, § 1º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 1º Ao impor condicionantes administrativas ao tratamento de dados pessoais por agente de tratamento privado, sejam eles limites, encargos ou sujeições, a ANPD deve observar a exigência de mínima intervenção, assegurados os fundamentos, os princípios e os direitos dos titulares previstos no art. 170 da Constituição Federal e nesta Lei."],"origin":"authorial","question":{"statement":"§ 1º Ao impor condicionantes administrativas ao tratamento de dados pessoais por agente de tratamento privado, sejam eles limites, encargos ou sujeições, a ANPD deve observar a exigência de mínima intervenção, assegurados os fundamentos, os princípios e os direitos dos titulares previstos no art. 170 da Constituição Federal e nesta Lei.","answer":true,"explanation":"Ao impor condicionantes a agentes privados, a ANPD deve observar mínima intervenção e resguardar os fundamentos e direitos indicados.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0269","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, § 3º","number":"Art. 55-J, § 3º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 3º A ANPD e os órgãos e entidades públicos responsáveis pela regulação de setores específicos da atividade econômica e governamental devem coordenar suas atividades, nas correspondentes esferas de atuação, com vistas a assegurar o cumprimento de suas atribuições com a maior eficiência e promover o adequado funcionamento dos setores regulados, conforme legislação específica, e o tratamento de dados pessoais, na forma desta Lei."],"origin":"authorial","question":{"statement":"§ 3º A ANPD e os órgãos e entidades públicos responsáveis pela regulação de setores específicos da atividade econômica e governamental devem coordenar suas atividades, nas correspondentes esferas de atuação, com vistas a assegurar o cumprimento de suas atribuições com a maior eficiência e promover o adequado funcionamento dos setores regulados, conforme legislação específica, e o tratamento de dados pessoais, na forma desta Lei.","answer":true,"explanation":"ANPD e reguladores setoriais coordenam atividades em suas esferas para cumprir atribuições e proteger dados.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0270","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, § 4º","number":"Art. 55-J, § 4º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 4º A ANPD manterá fórum permanente de comunicação, inclusive por meio de cooperação técnica, com órgãos e entidades da administração pública responsáveis pela regulação de setores específicos da atividade econômica e governamental, a fim de facilitar as competências regulatória, fiscalizatória e punitiva da ANPD."],"origin":"authorial","question":{"statement":"§ 4º A ANPD manterá fórum eventual de comunicação, inclusive por meio de cooperação técnica, com órgãos e entidades da administração pública responsáveis pela regulação de setores específicos da atividade econômica e governamental, a fim de facilitar as competências regulatória, fiscalizatória e punitiva da ANPD.","answer":false,"explanation":"O fórum de comunicação da ANPD com reguladores setoriais deve ser permanente.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0271","discipline":"adm","topicId":"led-adm-lgpd-13709","subtopic":"Art. 55-J, § 5º","number":"Art. 55-J, § 5º","title":"Lei nº 13.709/2018 · LGPD","parts":["§ 5º No exercício das competências de que trata o caput deste artigo, a autoridade competente deverá zelar pela preservação do segredo empresarial e do sigilo das informações, nos termos da lei."],"origin":"authorial","question":{"statement":"§ 5º No exercício das competências de que trata o caput deste artigo, a autoridade competente deverá zelar pela preservação do segredo empresarial e do sigilo das informações, nos termos da lei.","answer":true,"explanation":"A autoridade competente deve preservar segredos empresariais e sigilo no exercício das competências.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0273","discipline":"civil","topicId":"led-civil-cc-10406","subtopic":"Art. 105","number":"Art. 105","title":"Código Civil","parts":["Art. 105. A incapacidade relativa de uma das partes não pode ser invocada pela outra em benefício próprio, nem aproveita aos co-interessados capazes, salvo se, neste caso, for indivisível o objeto do direito ou da obrigação comum."],"origin":"authorial","question":{"statement":"Art. 105. A incapacidade relativa de uma das partes não pode ser invocada pela outra em benefício próprio, nem aproveita aos co-interessados capazes, ainda que, neste caso, seja indivisível o objeto do direito ou da obrigação comum.","answer":false,"explanation":"O dispositivo ressalva a indivisibilidade do objeto comum: nessa hipótese, a incapacidade relativa pode aproveitar aos cointeressados capazes.","source":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0274","discipline":"civil","topicId":"led-civil-cc-10406","subtopic":"Art. 107","number":"Art. 107","title":"Código Civil","parts":["Art. 107. A validade da declaração de vontade não dependerá de forma especial, senão quando a lei expressamente a exigir."],"origin":"authorial","question":{"statement":"Art. 107. A validade da declaração de vontade não dependerá de forma especial, senão quando a lei expressamente a exigir.","answer":true,"explanation":"Forma especial só é requisito de validade quando expressamente exigida em lei.","source":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0275","discipline":"civil","topicId":"led-civil-cc-10406","subtopic":"Art. 109","number":"Art. 109","title":"Código Civil","parts":["Art. 109. No negócio jurídico celebrado com a cláusula de não valer sem instrumento público, este é da substância do ato."],"origin":"authorial","question":{"statement":"Art. 109. No negócio jurídico celebrado com a cláusula de não valer sem instrumento público, este é apenas meio facultativo de prova.","answer":false,"explanation":"A cláusula de não valer sem instrumento público torna esse instrumento da substância do negócio.","source":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0276","discipline":"civil","topicId":"led-civil-cc-10406","subtopic":"Art. 110","number":"Art. 110","title":"Código Civil","parts":["Art. 110. A manifestação de vontade subsiste ainda que o seu autor haja feito a reserva mental de não querer o que manifestou, salvo se dela o destinatário tinha conhecimento."],"origin":"authorial","question":{"statement":"Art. 110. A manifestação de vontade subsiste ainda que o seu autor haja feito a reserva mental de não querer o que manifestou, salvo se dela o destinatário tinha conhecimento.","answer":true,"explanation":"A reserva mental em regra não afasta a manifestação; a exceção é o conhecimento do destinatário.","source":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0277","discipline":"civil","topicId":"led-civil-cc-10406","subtopic":"Art. 114","number":"Art. 114","title":"Código Civil","parts":["Art. 114. Os negócios jurídicos benéficos e a renúncia interpretam-se estritamente."],"origin":"authorial","question":{"statement":"Art. 114. Os negócios jurídicos benéficos e a renúncia interpretam-se ampliativamente.","answer":false,"explanation":"Negócios benéficos e renúncia se interpretam estritamente.","source":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0278","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 16","number":"Art. 16","title":"Lei nº 15.040/2024 · Seguros","parts":["Art. 16. Sobrevindo o sinistro, a seguradora somente poderá recusar-se a indenizar caso prove o nexo causal entre o relevante agravamento do risco e o sinistro caracterizado."],"origin":"authorial","question":{"statement":"Art. 16. Sobrevindo o sinistro, a seguradora somente poderá recusar-se a indenizar caso prove o nexo causal entre o relevante agravamento do risco e o sinistro caracterizado.","answer":true,"explanation":"A recusa de indenização por agravamento relevante requer prova do nexo causal com o sinistro.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0279","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 21, caput","number":"Art. 21, caput","title":"Lei nº 15.040/2024 · Seguros","parts":["Art. 21. A resolução do contrato, salvo quando se tratar de mora da prestação única ou da primeira parcela do prêmio, está condicionada a notificação prévia e não poderá ocorrer em prazo inferior a 30 (trinta) dias após a suspensão da garantia."],"origin":"authorial","question":{"statement":"Art. 21. A resolução do contrato, inclusive quando se tratar de mora da prestação única ou da primeira parcela do prêmio, está condicionada a notificação prévia e não poderá ocorrer em prazo inferior a 30 (trinta) dias após a suspensão da garantia.","answer":false,"explanation":"A notificação prévia e o intervalo mínimo de trinta dias têm exceção na mora de prêmio único ou primeira parcela.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0280","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 21, § 1º","number":"Art. 21, § 1º","title":"Lei nº 15.040/2024 · Seguros","parts":["§ 1º A resolução libera integralmente a seguradora por sinistros e despesas de salvamento ocorridos a partir de então."],"origin":"authorial","question":{"statement":"§ 1º A resolução libera integralmente a seguradora por sinistros e despesas de salvamento ocorridos a partir de então.","answer":true,"explanation":"A resolução libera integralmente a seguradora por sinistros e despesas de salvamento posteriores a ela.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0281","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 21, § 2º","number":"Art. 21, § 2º","title":"Lei nº 15.040/2024 · Seguros","parts":["§ 2º Nos seguros coletivos sobre a vida e a integridade física, a resolução somente ocorrerá 90 (noventa) dias após a última notificação feita ao estipulante."],"origin":"authorial","question":{"statement":"§ 2º Nos seguros coletivos sobre a vida e a integridade física, a resolução somente ocorrerá 90 (noventa) dias após a primeira notificação feita ao estipulante.","answer":false,"explanation":"No seguro coletivo de vida e integridade, os noventa dias fluem da última notificação ao estipulante.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0282","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 21, § 3º","number":"Art. 21, § 3º","title":"Lei nº 15.040/2024 · Seguros","parts":["§ 3º Nos seguros sobre a vida e a integridade física estruturados com reserva matemática, o não pagamento de parcela do prêmio que não a primeira implicará a redução proporcional da garantia ou a devolução da reserva, conforme a escolha do segurado ou de seus beneficiários, a ser feita dentro de 30 (trinta) dias contados da notificação do inadimplemento, da qual deve constar a advertência de que, se houver abstenção nessa escolha, a decisão caberá à seguradora."],"origin":"authorial","question":{"statement":"§ 3º Nos seguros sobre a vida e a integridade física estruturados com reserva matemática, o não pagamento de parcela do prêmio que não a primeira implicará a redução proporcional da garantia ou a devolução da reserva, conforme a escolha do segurado ou de seus beneficiários, a ser feita dentro de 30 (trinta) dias contados da notificação do inadimplemento, da qual deve constar a advertência de que, se houver abstenção nessa escolha, a decisão caberá à seguradora.","answer":true,"explanation":"Na falta de parcela que não seja a primeira, segurado ou beneficiários escolhem em trinta dias entre redução da garantia e devolução da reserva; silêncio transfere a escolha à seguradora.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0284","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 21, § 5º","number":"Art. 21, § 5º","title":"Lei nº 15.040/2024 · Seguros","parts":["§ 5º Dispensa-se a notificação a que se refere o caput deste artigo quando a notificação de suspensão da garantia, de que tratam os §§ 1º, 2º e 3º do art. 20 desta Lei, advertir para a resolução do contrato caso não purgada a mora."],"origin":"authorial","question":{"statement":"§ 5º Dispensa-se a notificação a que se refere o caput deste artigo quando a notificação de suspensão da garantia, de que tratam os §§ 1º, 2º e 3º do art. 20 desta Lei, advertir para a resolução do contrato caso não purgada a mora.","answer":true,"explanation":"A notificação de resolução pode ser dispensada quando a de suspensão da garantia já advertiu sobre resolução em caso de mora não purgada.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0285","discipline":"civil","topicId":"led-civil-seguros-15040","subtopic":"Art. 88","number":"Art. 88","title":"Lei nº 15.040/2024 · Seguros","parts":["Art. 88. A mora da seguradora fará incidir multa de 2% (dois por cento) sobre o montante devido, corrigido monetariamente, sem prejuízo dos juros legais e da responsabilidade por perdas e danos desde a data em que a indenização ou o capital segurado deveriam ter sido pagos, conforme disposto nos arts. 86 e 87 desta Lei."],"origin":"authorial","question":{"statement":"Art. 88. A mora da seguradora fará incidir multa de 10% (dez por cento) sobre o montante devido, corrigido monetariamente, sem prejuízo dos juros legais e da responsabilidade por perdas e danos desde a data em que a indenização ou o capital segurado deveriam ter sido pagos, conforme disposto nos arts. 86 e 87 desta Lei.","answer":false,"explanation":"A mora da seguradora gera multa de dois por cento, além dos juros legais e perdas e danos conforme o texto.","source":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l15040.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0286","discipline":"cpc","topicId":"led-cpc-cpc","subtopic":"Art. 1.059","number":"Art. 1.059","title":"Código de Processo Civil","parts":["Art. 1.059. À tutela provisória requerida contra a Fazenda Pública aplica-se o disposto nos arts. 1º a 4º da Lei nº 8.437, de 30 de junho de 1992, e no art. 7º, § 2º, da Lei nº 12.016, de 7 de agosto de 2009."],"origin":"authorial","question":{"statement":"Art. 1.059. À tutela provisória requerida contra a Fazenda Pública aplica-se o disposto nos arts. 1º a 4º da Lei nº 8.437, de 30 de junho de 1992, e no art. 7º, § 2º, da Lei nº 12.016, de 7 de agosto de 2009.","answer":true,"explanation":"A tutela provisória contra a Fazenda Pública observa os artigos específicos das Leis nº 8.437/1992 e 12.016/2009.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105compilada.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0287","discipline":"cpc","topicId":"led-cpc-cpc","subtopic":"Art. 1.062","number":"Art. 1.062","title":"Código de Processo Civil","parts":["Art. 1.062. O incidente de desconsideração da personalidade jurídica aplica-se ao processo de competência dos juizados especiais."],"origin":"authorial","question":{"statement":"Art. 1.062. O incidente de desconsideração da personalidade jurídica não se aplica ao processo de competência dos juizados especiais.","answer":false,"explanation":"O incidente de desconsideração também se aplica aos processos dos juizados especiais.","source":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105compilada.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0288","discipline":"penal","topicId":"led-penal-cp-2848","subtopic":"Art. 337-H, caput e pena","number":"Art. 337-H, caput e pena","title":"Código Penal","parts":["Art. 337-H. Admitir, possibilitar ou dar causa a qualquer modificação ou vantagem, inclusive prorrogação contratual, em favor do contratado, durante a execução dos contratos celebrados com a Administração Pública, sem autorização em lei, no edital da licitação ou nos respectivos instrumentos contratuais, ou, ainda, pagar fatura com preterição da ordem cronológica de sua exigibilidade:\nPena - reclusão, de 4 (quatro) anos a 8 (oito) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 337-H. Admitir, possibilitar ou dar causa a qualquer modificação ou vantagem, inclusive prorrogação contratual, em favor do contratado, durante a execução dos contratos celebrados com a Administração Pública, sem autorização em lei, no edital da licitação ou nos respectivos instrumentos contratuais, ou, ainda, pagar fatura com preterição da ordem cronológica de sua exigibilidade:\nPena - reclusão, de 4 (quatro) anos a 8 (oito) anos, e multa.","answer":true,"explanation":"A alteração ou vantagem sem autorização e o pagamento com quebra de ordem cronológica integram o tipo, punido com reclusão de quatro a oito anos e multa.","source":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0289","discipline":"penal","topicId":"led-penal-cp-2848","subtopic":"Art. 337-K, caput e pena","number":"Art. 337-K, caput e pena","title":"Código Penal","parts":["Art. 337-K. Afastar ou tentar afastar licitante por meio de violência, grave ameaça, fraude ou oferecimento de vantagem de qualquer tipo:\nPena - reclusão, de 3 (três) anos a 5 (cinco) anos, e multa, além da pena correspondente à violência."],"origin":"authorial","question":{"statement":"Art. 337-K. Afastar ou tentar afastar licitante por meio de violência, grave ameaça, fraude ou oferecimento de vantagem exclusivamente pecuniária:\nPena - reclusão, de 3 (três) anos a 5 (cinco) anos, e multa, além da pena correspondente à violência.","answer":false,"explanation":"O oferecimento de vantagem de qualquer tipo integra a forma de afastar ou tentar afastar licitante.","source":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0290","discipline":"penal","topicId":"led-penal-cp-2848","subtopic":"Art. 337-K, parágrafo único","number":"Art. 337-K, parágrafo único","title":"Código Penal","parts":["Art. 337-K. Afastar ou tentar afastar licitante por meio de violência, grave ameaça, fraude ou oferecimento de vantagem de qualquer tipo:\nPena - reclusão, de 3 (três) anos a 5 (cinco) anos, e multa, além da pena correspondente à violência.\nParágrafo único. Incorre na mesma pena quem se abstém ou desiste de licitar em razão de vantagem oferecida."],"origin":"authorial","question":{"statement":"Art. 337-K. Afastar ou tentar afastar licitante por meio de violência, grave ameaça, fraude ou oferecimento de vantagem de qualquer tipo:\nPena - reclusão, de 3 (três) anos a 5 (cinco) anos, e multa, além da pena correspondente à violência.\nParágrafo único. Incorre na mesma pena quem se abstém ou desiste de licitar em razão de vantagem oferecida.","answer":true,"explanation":"A mesma pena alcança quem se abstém ou desiste de licitar em razão da vantagem oferecida.","source":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0291","discipline":"penal","topicId":"led-penal-cp-2848","subtopic":"Art. 337-O, caput e pena","number":"Art. 337-O, caput e pena","title":"Código Penal","parts":["Art. 337-O. Omitir, modificar ou entregar à Administração Pública levantamento cadastral ou condição de contorno em relevante dissonância com a realidade, em frustração ao caráter competitivo da licitação ou em detrimento da seleção da proposta mais vantajosa para a Administração Pública, em contratação para a elaboração de projeto básico, projeto executivo ou anteprojeto, em diálogo competitivo ou em procedimento de manifestação de interesse:\nPena - reclusão, de 6 (seis) meses a 3 (três) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 337-O. Omitir, modificar ou entregar à Administração Pública levantamento cadastral ou condição de contorno em qualquer dissonância com a realidade, em frustração ao caráter competitivo da licitação ou em detrimento da seleção da proposta mais vantajosa para a Administração Pública, em contratação para a elaboração de projeto básico, projeto executivo ou anteprojeto, em diálogo competitivo ou em procedimento de manifestação de interesse:\nPena - reclusão, de 6 (seis) meses a 3 (três) anos, e multa.","answer":false,"explanation":"A dissonância do levantamento cadastral ou condição de contorno deve ser relevante e vinculada aos fins descritos.","source":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0292","discipline":"penal","topicId":"led-penal-cp-2848","subtopic":"Art. 337-O, § 1º","number":"Art. 337-O, § 1º","title":"Código Penal","parts":["§ 1º Consideram-se condição de contorno as informações e os levantamentos suficientes e necessários para a definição da solução de projeto e dos respectivos preços pelo licitante, incluídos sondagens, topografia, estudos de demanda, condições ambientais e demais elementos ambientais impactantes, considerados requisitos mínimos ou obrigatórios em normas técnicas que orientam a elaboração de projetos."],"origin":"authorial","question":{"statement":"§ 1º Consideram-se condição de contorno as informações e os levantamentos suficientes e necessários para a definição da solução de projeto e dos respectivos preços pelo licitante, incluídos sondagens, topografia, estudos de demanda, condições ambientais e demais elementos ambientais impactantes, considerados requisitos mínimos ou obrigatórios em normas técnicas que orientam a elaboração de projetos.","answer":true,"explanation":"Condição de contorno inclui os levantamentos técnicos mínimos necessários à solução do projeto e aos preços do licitante.","source":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0293","discipline":"penal","topicId":"led-penal-cp-2848","subtopic":"Art. 337-O, § 2º","number":"Art. 337-O, § 2º","title":"Código Penal","parts":["Art. 337-O. Omitir, modificar ou entregar à Administração Pública levantamento cadastral ou condição de contorno em relevante dissonância com a realidade, em frustração ao caráter competitivo da licitação ou em detrimento da seleção da proposta mais vantajosa para a Administração Pública, em contratação para a elaboração de projeto básico, projeto executivo ou anteprojeto, em diálogo competitivo ou em procedimento de manifestação de interesse:\nPena - reclusão, de 6 (seis) meses a 3 (três) anos, e multa.\n§ 2º Se o crime é praticado com o fim de obter benefício, direto ou indireto, próprio ou de outrem, aplica-se em dobro a pena prevista no caput deste artigo."],"origin":"authorial","question":{"statement":"Art. 337-O. Omitir, modificar ou entregar à Administração Pública levantamento cadastral ou condição de contorno em relevante dissonância com a realidade, em frustração ao caráter competitivo da licitação ou em detrimento da seleção da proposta mais vantajosa para a Administração Pública, em contratação para a elaboração de projeto básico, projeto executivo ou anteprojeto, em diálogo competitivo ou em procedimento de manifestação de interesse:\nPena - reclusão, de 6 (seis) meses a 3 (três) anos, e multa.\n§ 2º Se o crime é praticado com o fim de obter benefício, direto ou indireto, próprio ou de outrem, aplica-se em triplo a pena prevista no caput deste artigo.","answer":false,"explanation":"O fim de obter benefício próprio ou alheio dobra a pena do caput.","source":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0294","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 9º","number":"Art. 9º","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 9º Decretar medida de privação da liberdade em qualquer desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":false,"explanation":"O tipo exige manifesta desconformidade da privação de liberdade com as hipóteses legais.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0295","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 9º, Parágrafo único, inc. I","number":"Art. 9º, Parágrafo único, inc. I","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\nI - relaxar a prisão manifestamente ilegal;"],"origin":"authorial","question":{"statement":"Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\nI - relaxar a prisão manifestamente ilegal;","answer":true,"explanation":"A prisão manifestamente ilegal deve ser relaxada pela autoridade judiciária em prazo razoável.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0296","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 9º, Parágrafo único, inc. II","number":"Art. 9º, Parágrafo único, inc. II","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\nII - substituir a prisão preventiva por medida cautelar diversa ou de conceder liberdade provisória, quando manifestamente cabível;"],"origin":"authorial","question":{"statement":"Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\nII - substituir a prisão preventiva por medida cautelar diversa ou de conceder liberdade provisória, quando apenas discutível;","answer":false,"explanation":"A omissão equiparada exige cabimento manifesto da medida ou liberdade provisória.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0297","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 9º, Parágrafo único, inc. III","number":"Art. 9º, Parágrafo único, inc. III","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\nIII - deferir liminar ou ordem de habeas corpus, quando manifestamente cabível."],"origin":"authorial","question":{"statement":"Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\nIII - deferir liminar ou ordem de habeas corpus, quando manifestamente cabível.","answer":true,"explanation":"A omissão relativa a habeas corpus requer que liminar ou ordem sejam manifestamente cabíveis.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0299","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 12, Parágrafo único, inc. I","number":"Art. 12, Parágrafo único, inc. I","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 12. Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem:\nI - deixa de comunicar, imediatamente, a execução de prisão temporária ou preventiva à autoridade judiciária que a decretou;"],"origin":"authorial","question":{"statement":"Art. 12. Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem:\nI - deixa de comunicar, imediatamente, a execução de prisão temporária ou preventiva à autoridade judiciária que a decretou;","answer":true,"explanation":"A execução de prisão temporária ou preventiva deve ser comunicada imediatamente ao juiz que a decretou.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0301","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 12, Parágrafo único, inc. III","number":"Art. 12, Parágrafo único, inc. III","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 12. Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem:\nIII - deixa de entregar ao preso, no prazo de 24 (vinte e quatro) horas, a nota de culpa, assinada pela autoridade, com o motivo da prisão e os nomes do condutor e das testemunhas;"],"origin":"authorial","question":{"statement":"Art. 12. Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem:\nIII - deixa de entregar ao preso, no prazo de 24 (vinte e quatro) horas, a nota de culpa, assinada pela autoridade, com o motivo da prisão e os nomes do condutor e das testemunhas;","answer":true,"explanation":"A nota de culpa ao preso tem prazo de vinte e quatro horas e deve trazer os elementos indicados.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0302","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 12, Parágrafo único, inc. IV","number":"Art. 12, Parágrafo único, inc. IV","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 12. Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem:\nIV - prolonga a execução de pena privativa de liberdade, de prisão temporária, de prisão preventiva, de medida de segurança ou de internação, deixando, sem motivo justo e excepcionalíssimo, de executar o alvará de soltura imediatamente após recebido ou de promover a soltura do preso quando esgotado o prazo judicial ou legal."],"origin":"authorial","question":{"statement":"Art. 12. Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem:\nIV - prolonga a execução de pena privativa de liberdade, de prisão temporária, de prisão preventiva, de medida de segurança ou de internação, deixando, sem qualquer autorização administrativa, de executar o alvará de soltura imediatamente após recebido ou de promover a soltura do preso quando esgotado o prazo judicial ou legal.","answer":false,"explanation":"A prorrogação indevida envolve a falta de motivo justo e excepcionalíssimo nos termos do inciso.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0303","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 13","number":"Art. 13","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nI - exibir-se ou ter seu corpo ou parte dele exibido à curiosidade pública;\nII - submeter-se a situação vexatória ou a constrangimento não autorizado em lei;\nIII - produzir prova contra si mesmo ou contra terceiro:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência."],"origin":"authorial","question":{"statement":"Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nI - exibir-se ou ter seu corpo ou parte dele exibido à curiosidade pública;\nII - submeter-se a situação vexatória ou a constrangimento não autorizado em lei;\nIII - produzir prova contra si mesmo ou contra terceiro:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência.","answer":true,"explanation":"O caput exige constrangimento de preso ou detento pelos meios especificados e tipifica as três finalidades enumeradas.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0304","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 13, inc. I","number":"Art. 13, inc. I","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nI - exibir-se ou ter seu corpo ou parte dele exibido à curiosidade pública;\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência."],"origin":"authorial","question":{"statement":"Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nI - exibir-se ou ter seu corpo ou parte dele exibido à autoridade judiciária;\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência.","answer":false,"explanation":"A exibição à curiosidade pública, mediante os meios constritivos do caput, integra o crime.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0305","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 13, inc. II","number":"Art. 13, inc. II","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nII - submeter-se a situação vexatória ou a constrangimento não autorizado em lei;\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência."],"origin":"authorial","question":{"statement":"Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nII - submeter-se a situação vexatória ou a constrangimento não autorizado em lei;\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência.","answer":true,"explanation":"A situação vexatória ou constrangimento não autorizado em lei é uma das finalidades do caput.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0306","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 13, inc. III","number":"Art. 13, inc. III","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nIII - produzir prova contra si mesmo ou contra terceiro:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência."],"origin":"authorial","question":{"statement":"Art. 13. Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\nIII - produzir prova apenas contra terceiro:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência.","answer":false,"explanation":"A produção constrangida de prova contra si mesmo também integra a hipótese.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0307","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15","number":"Art. 15","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 15. Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 15. Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":true,"explanation":"A ameaça de prisão a pessoa obrigada a sigilo por função, ministério, ofício ou profissão compõe o tipo.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0308","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15, Parágrafo único, inc. I","number":"Art. 15, Parágrafo único, inc. I","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 15. Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem prossegue com o interrogatório:\nI - de pessoa que tenha decidido exercer o direito ao silêncio; ou"],"origin":"authorial","question":{"statement":"Art. 15. Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem prossegue com o interrogatório:\nI - de pessoa que tenha decidido responder às perguntas; ou","answer":false,"explanation":"O prosseguimento do interrogatório após exercício do direito ao silêncio é punido.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0309","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15, Parágrafo único, inc. II","number":"Art. 15, Parágrafo único, inc. II","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 15. Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem prossegue com o interrogatório:\nII - de pessoa que tenha optado por ser assistida por advogado ou defensor público, sem a presença de seu patrono."],"origin":"authorial","question":{"statement":"Art. 15. Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem prossegue com o interrogatório:\nII - de pessoa que tenha optado por ser assistida por advogado ou defensor público, sem a presença de seu patrono.","answer":true,"explanation":"Prosseguir o interrogatório sem o patrono escolhido pelo depoente também recebe a mesma pena.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0311","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15-A, inc. I","number":"Art. 15-A, inc. I","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 15-A. Submeter a vítima de infração penal ou a testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a leve a reviver, sem estrita necessidade:\nI - a situação de violência; ou\nPena - detenção, de 3 (três) meses a 1 (um) ano, e multa."],"origin":"authorial","question":{"statement":"Art. 15-A. Submeter a vítima de infração penal ou a testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a leve a reviver, sem estrita necessidade:\nI - a situação de violência; ou\nPena - detenção, de 3 (três) meses a 1 (um) ano, e multa.","answer":true,"explanation":"A violência revivida sem estrita necessidade é uma das situações enumeradas no art. 15-A.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0312","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15-A, inc. II","number":"Art. 15-A, inc. II","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 15-A. Submeter a vítima de infração penal ou a testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a leve a reviver, sem estrita necessidade:\nII - outras situações potencialmente geradoras de sofrimento ou estigmatização:\nPena - detenção, de 3 (três) meses a 1 (um) ano, e multa."],"origin":"authorial","question":{"statement":"Art. 15-A. Submeter a vítima de infração penal ou a testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a leve a reviver, sem estrita necessidade:\nII - outras situações potencialmente geradoras de sofrimento ou estigmatização:\nPena - detenção, de 3 (três) meses a 1 (um) ano, e multa.","answer":true,"explanation":"Outras situações que provoquem sofrimento ou estigmatização completam a hipótese, respeitado o caput.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0313","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15-A, § 1º","number":"Art. 15-A, § 1º","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["§ 1º Se o agente público permitir que terceiro intimide a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena aumentada de 2/3 (dois terços)."],"origin":"authorial","question":{"statement":"§ 1º Se o agente público intimidar pessoalmente a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena aumentada de 2/3 (dois terços).","answer":false,"explanation":"Permitir intimidação por terceiro causa aumento de dois terços; intimidação própria tem pena em dobro no § 2º.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0314","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 15-A, § 2º","number":"Art. 15-A, § 2º","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["§ 2º Se o agente público intimidar a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena em dobro."],"origin":"authorial","question":{"statement":"§ 2º Se o agente público intimidar a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena em dobro.","answer":true,"explanation":"A intimidação praticada pelo próprio agente público gera pena em dobro, diversa do aumento por terceiro.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0315","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 16","number":"Art. 16","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 16. Deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 16. Deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":true,"explanation":"A identificação falsa ou ausência de identificação do preso no momento indicado recebe detenção e multa.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0317","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 18","number":"Art. 18","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 18. Submeter o preso a interrogatório policial durante o período de repouso noturno, salvo se capturado em flagrante delito ou se ele, devidamente assistido, consentir em prestar declarações:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 18. Submeter o preso a interrogatório policial durante o período de repouso noturno, salvo se capturado em flagrante delito ou se ele, sem assistência, consentir em prestar declarações:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":false,"explanation":"A exceção fundada em consentimento exige que o preso esteja devidamente assistido.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0318","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 19","number":"Art. 19","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 19. Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 19. Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":true,"explanation":"O tipo protege o envio do pleito à autoridade judiciária competente para examinar legalidade ou custódia.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0319","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 19, Parágrafo único","number":"Art. 19, Parágrafo único","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 19. Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena o magistrado que, ciente do impedimento ou da demora, deixa de tomar as providências tendentes a saná-lo ou, não sendo competente para decidir sobre a prisão, deixa de enviar o pedido à autoridade judiciária que o seja."],"origin":"authorial","question":{"statement":"Art. 19. Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena o magistrado que, independentemente de ciência do impedimento ou da demora, deixa de tomar as providências tendentes a saná-lo ou, não sendo competente para decidir sobre a prisão, deixa de enviar o pedido à autoridade judiciária que o seja.","answer":false,"explanation":"A omissão do magistrado nessa modalidade exige ciência do impedimento ou demora.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0320","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 20","number":"Art. 20","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 20. Impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 20. Impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":true,"explanation":"O impedimento sem justa causa de entrevista pessoal e reservada com advogado é punido.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0321","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 20, Parágrafo único","number":"Art. 20, Parágrafo único","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 20. Impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem impede o preso, o réu solto ou o investigado de entrevistar-se pessoal e reservadamente com seu advogado ou defensor, por prazo razoável, antes de audiência judicial, e de sentar-se ao seu lado e com ele comunicar-se durante a audiência, salvo no curso de interrogatório ou no caso de audiência realizada por videoconferência."],"origin":"authorial","question":{"statement":"Art. 20. Impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem impede o preso, o réu solto ou o investigado de entrevistar-se pessoal e reservadamente com seu advogado ou defensor, por prazo razoável, antes de audiência judicial, e de sentar-se ao seu lado e com ele comunicar-se durante a audiência, inclusive no curso de interrogatório ou no caso de audiência realizada por videoconferência.","answer":false,"explanation":"O próprio parágrafo ressalva interrogatório e audiência por videoconferência.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0322","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 21","number":"Art. 21","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 21. Manter presos de ambos os sexos na mesma cela ou espaço de confinamento:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 21. Manter presos de ambos os sexos na mesma cela ou espaço de confinamento:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":true,"explanation":"O confinamento conjunto de presos de ambos os sexos integra o tipo, com detenção e multa.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0323","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 21, Parágrafo único","number":"Art. 21, Parágrafo único","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 21. Manter presos de ambos os sexos na mesma cela ou espaço de confinamento:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem mantém, na mesma cela, criança ou adolescente na companhia de maior de idade ou em ambiente inadequado, observado o disposto na Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente)."],"origin":"authorial","question":{"statement":"Art. 21. Manter presos de ambos os sexos na mesma cela ou espaço de confinamento:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem mantém, na mesma cela, criança ou adolescente na companhia de outra criança ou em ambiente inadequado, observado o disposto na Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente).","answer":false,"explanation":"A equiparação alcança menor de idade com maior na mesma cela ou ambiente inadequado.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0324","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 22","number":"Art. 22","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 22. Invadir ou adentrar, clandestina ou astuciosamente, ou à revelia da vontade do ocupante, imóvel alheio ou suas dependências, ou nele permanecer nas mesmas condições, sem determinação judicial ou fora das condições estabelecidas em lei:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 22. Invadir ou adentrar, clandestina ou astuciosamente, ou à revelia da vontade do ocupante, imóvel alheio ou suas dependências, ou nele permanecer nas mesmas condições, sem determinação judicial ou fora das condições estabelecidas em lei:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":true,"explanation":"O ingresso ou permanência irregular em imóvel alheio tem as condições e a pena indicadas.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0326","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 22, § 1º, inc. III","number":"Art. 22, § 1º, inc. III","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 22. Invadir ou adentrar, clandestina ou astuciosamente, ou à revelia da vontade do ocupante, imóvel alheio ou suas dependências, ou nele permanecer nas mesmas condições, sem determinação judicial ou fora das condições estabelecidas em lei:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n§ 1º Incorre na mesma pena, na forma prevista no caput deste artigo, quem:\nIII - cumpre mandado de busca e apreensão domiciliar após as 21h (vinte e uma horas) ou antes das 5h (cinco horas)."],"origin":"authorial","question":{"statement":"Art. 22. Invadir ou adentrar, clandestina ou astuciosamente, ou à revelia da vontade do ocupante, imóvel alheio ou suas dependências, ou nele permanecer nas mesmas condições, sem determinação judicial ou fora das condições estabelecidas em lei:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n§ 1º Incorre na mesma pena, na forma prevista no caput deste artigo, quem:\nIII - cumpre mandado de busca e apreensão domiciliar após as 21h (vinte e uma horas) ou antes das 5h (cinco horas).","answer":true,"explanation":"O mandado domiciliar cumprido depois das 21h ou antes das 5h se equipara ao caput.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0328","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 23","number":"Art. 23","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 23. Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 23. Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":true,"explanation":"A inovação artificiosa exige finalidade de afastar ou impor responsabilidade nos termos do tipo.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0329","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 23, Parágrafo único, inc. I","number":"Art. 23, Parágrafo único, inc. I","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 23. Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem pratica a conduta com o intuito de:\nI - eximir-se de responsabilidade civil ou administrativa por excesso praticado no curso de diligência;"],"origin":"authorial","question":{"statement":"Art. 23. Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem pratica a conduta com o intuito de:\nI - eximir-se de responsabilidade exclusivamente penal por excesso praticado no curso de diligência;","answer":false,"explanation":"A finalidade equiparada no inciso I é afastar responsabilidade civil ou administrativa por excesso.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0330","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 23, Parágrafo único, inc. II","number":"Art. 23, Parágrafo único, inc. II","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 23. Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem pratica a conduta com o intuito de:\nII - omitir dados ou informações ou divulgar dados ou informações incompletos para desviar o curso da investigação, da diligência ou do processo."],"origin":"authorial","question":{"statement":"Art. 23. Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem pratica a conduta com o intuito de:\nII - omitir dados ou informações ou divulgar dados ou informações incompletos para desviar o curso da investigação, da diligência ou do processo.","answer":true,"explanation":"O inciso II inclui omitir ou divulgar informação incompleta para desviar o curso da apuração.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0331","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 24","number":"Art. 24","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 24. Constranger, sob violência ou grave ameaça, funcionário ou empregado de instituição hospitalar pública ou privada a admitir para tratamento pessoa cujo óbito já tenha ocorrido, com o fim de alterar local ou momento de crime, prejudicando sua apuração:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, além da pena correspondente à violência."],"origin":"authorial","question":{"statement":"Art. 24. Constranger, sob violência ou grave ameaça, funcionário ou empregado de instituição hospitalar pública ou privada a admitir para tratamento pessoa cujo óbito já tenha ocorrido, com o fim de alterar local ou momento de crime, prejudicando sua apuração:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, além da pena correspondente à violência.","answer":true,"explanation":"A admissão de pessoa já falecida ao hospital, com fim de alterar o local ou momento do crime, é a conduta descrita.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0333","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 25, Parágrafo único","number":"Art. 25, Parágrafo único","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 25. Proceder à obtenção de prova, em procedimento de investigação ou fiscalização, por meio manifestamente ilícito:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem faz uso de prova, em desfavor do investigado ou fiscalizado, com prévio conhecimento de sua ilicitude."],"origin":"authorial","question":{"statement":"Art. 25. Proceder à obtenção de prova, em procedimento de investigação ou fiscalização, por meio manifestamente ilícito:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\nParágrafo único. Incorre na mesma pena quem faz uso de prova, em desfavor do investigado ou fiscalizado, com prévio conhecimento de sua ilicitude.","answer":true,"explanation":"O uso da prova ilícita em desfavor do investigado exige conhecimento prévio de sua ilicitude.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0334","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 27","number":"Art. 27","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 27. Requisitar instauração ou instaurar procedimento investigatório de infração penal ou administrativa, em desfavor de alguém, à falta de qualquer indício da prática de crime, de ilícito funcional ou de infração administrativa:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 27. Requisitar instauração ou instaurar procedimento investigatório de infração penal ou administrativa, em desfavor de alguém, quando houver indício suficiente da prática de crime, de ilícito funcional ou de infração administrativa:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":false,"explanation":"O tipo exige ausência de qualquer indício de crime, ilícito funcional ou infração administrativa.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0335","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 27, Parágrafo único","number":"Art. 27, Parágrafo único","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Parágrafo único. Não há crime quando se tratar de sindicância ou investigação preliminar sumária, devidamente justificada."],"origin":"authorial","question":{"statement":"Parágrafo único. Não há crime quando se tratar de sindicância ou investigação preliminar sumária, devidamente justificada.","answer":true,"explanation":"Sindicância ou investigação preliminar sumária justificada não constitui esse crime.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0336","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 28","number":"Art. 28","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 28. Divulgar gravação ou trecho de gravação sem relação com a prova que se pretenda produzir, expondo a intimidade ou a vida privada ou ferindo a honra ou a imagem do investigado ou acusado:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 28. Divulgar gravação ou trecho de gravação com relação necessária com a prova que se pretenda produzir, expondo a intimidade ou a vida privada ou ferindo a honra ou a imagem do investigado ou acusado:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":false,"explanation":"A divulgação típica é de gravação sem relação com a prova, com exposição da intimidade ou ofensa à honra ou imagem.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0337","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 29","number":"Art. 29","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 29. Prestar informação falsa sobre procedimento judicial, policial, fiscal ou administrativo com o fim de prejudicar interesse de investigado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 29. Prestar informação falsa sobre procedimento judicial, policial, fiscal ou administrativo com o fim de prejudicar interesse de investigado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":true,"explanation":"A informação falsa exige finalidade de prejudicar interesse de investigado.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0338","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 30","number":"Art. 30","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 30. Dar início ou proceder à persecução penal, civil ou administrativa sem justa causa fundamentada ou contra quem sabe inocente:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 30. Dar início ou proceder à persecução penal, civil ou administrativa sem justa causa fundamentada e contra quem sabe inocente:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":false,"explanation":"As duas hipóteses de persecução abusiva são alternativas, não cumulativas.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0339","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 31","number":"Art. 31","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 31. Estender injustificadamente a investigação, procrastinando-a em prejuízo do investigado ou fiscalizado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 31. Estender injustificadamente a investigação, procrastinando-a em prejuízo do investigado ou fiscalizado:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":true,"explanation":"O prolongamento injustificado de investigação deve causar prejuízo ao investigado ou fiscalizado.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0341","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 32","number":"Art. 32","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 32. Negar ao interessado, seu defensor ou advogado acesso aos autos de investigação preliminar, ao termo circunstanciado, ao inquérito ou a qualquer outro procedimento investigatório de infração penal, civil ou administrativa, assim como impedir a obtenção de cópias, ressalvado o acesso a peças relativas a diligências em curso, ou que indiquem a realização de diligências futuras, cujo sigilo seja imprescindível:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 32. Negar ao interessado, seu defensor ou advogado acesso aos autos de investigação preliminar, ao termo circunstanciado, ao inquérito ou a qualquer outro procedimento investigatório de infração penal, civil ou administrativa, assim como impedir a obtenção de cópias, ressalvado o acesso a peças relativas a diligências em curso, ou que indiquem a realização de diligências futuras, cujo sigilo seja imprescindível:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":true,"explanation":"O acesso aos autos tem ressalva para diligências em curso ou futuras cujo sigilo seja imprescindível.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0343","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 33, Parágrafo único","number":"Art. 33, Parágrafo único","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 33. Exigir informação ou cumprimento de obrigação, inclusive o dever de fazer ou de não fazer, sem expresso amparo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem se utiliza de cargo ou função pública ou invoca a condição de agente público para se eximir de obrigação legal ou para obter vantagem ou privilégio indevido."],"origin":"authorial","question":{"statement":"Art. 33. Exigir informação ou cumprimento de obrigação, inclusive o dever de fazer ou de não fazer, sem expresso amparo legal:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\nParágrafo único. Incorre na mesma pena quem se utiliza de cargo ou função pública ou invoca a condição de agente público para se eximir de obrigação legal ou para obter vantagem ou privilégio indevido.","answer":true,"explanation":"O uso de cargo para afastar obrigação legal ou obter vantagem indevida incorre na mesma pena.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0344","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 36","number":"Art. 36","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 36. Decretar, em processo judicial, a indisponibilidade de ativos financeiros em quantia que extrapole exacerbadamente o valor estimado para a satisfação da dívida da parte e, ante a demonstração, pela parte, da excessividade da medida, deixar de corrigi-la:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 36. Decretar, em processo judicial, a indisponibilidade de ativos financeiros em quantia que extrapole exacerbadamente o valor estimado para a satisfação da dívida da parte e, antes da demonstração, pela parte, da excessividade da medida, deixar de corrigi-la:\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.","answer":false,"explanation":"A falta de correção pressupõe a demonstração da excessividade pela parte, além do excesso exacerbado.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0345","discipline":"penal","topicId":"led-penal-abuso-13869","subtopic":"Art. 37","number":"Art. 37","title":"Lei nº 13.869/2019 · Abuso de Autoridade","parts":["Art. 37. Demorar demasiada e injustificadamente no exame de processo de que tenha requerido vista em órgão colegiado, com o intuito de procrastinar seu andamento ou retardar o julgamento:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"authorial","question":{"statement":"Art. 37. Demorar demasiada e injustificadamente no exame de processo de que tenha requerido vista em órgão colegiado, com o intuito de procrastinar seu andamento ou retardar o julgamento:\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","answer":true,"explanation":"A demora no exame após vista em colegiado exige intuito de procrastinar ou retardar o julgamento.","source":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13869compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0347","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 4º","number":"Art. 4º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 4º O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público em 24 (vinte e quatro) horas, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias de bens, direitos ou valores do investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito dos crimes previstos nesta Lei ou das infrações penais antecedentes."],"origin":"authorial","question":{"statement":"Art. 4º O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público em 48 (quarenta e oito) horas, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias de bens, direitos ou valores do investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito dos crimes previstos nesta Lei ou das infrações penais antecedentes.","answer":false,"explanation":"Na representação do delegado, o Ministério Público é ouvido em vinte e quatro horas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0348","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 4º, § 1º","number":"Art. 4º, § 1º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 1º Proceder-se-á à alienação antecipada para preservação do valor dos bens sempre que estiverem sujeitos a qualquer grau de deterioração ou depreciação, ou quando houver dificuldade para sua manutenção."],"origin":"authorial","question":{"statement":"§ 1º Proceder-se-á à alienação antecipada para preservação do valor dos bens sempre que estiverem sujeitos a qualquer grau de deterioração ou depreciação, ou quando houver dificuldade para sua manutenção.","answer":true,"explanation":"A alienação antecipada preserva o valor quando houver deterioração, depreciação ou dificuldade de manutenção.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0349","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 4º, § 2º","number":"Art. 4º, § 2º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 2º O juiz determinará a liberação total ou parcial dos bens, direitos e valores quando comprovada a licitude de sua origem, mantendo-se a constrição dos bens, direitos e valores necessários e suficientes à reparação dos danos e ao pagamento de prestações pecuniárias, multas e custas decorrentes da infração penal."],"origin":"authorial","question":{"statement":"§ 2º O juiz determinará a liberação total ou parcial dos bens, direitos e valores quando apenas alegada a licitude de sua origem, mantendo-se a constrição dos bens, direitos e valores necessários e suficientes à reparação dos danos e ao pagamento de prestações pecuniárias, multas e custas decorrentes da infração penal.","answer":false,"explanation":"A liberação exige comprovação de origem lícita, ressalvada a constrição necessária aos pagamentos indicados.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0350","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 4º, § 3º","number":"Art. 4º, § 3º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 3º Nenhum pedido de liberação será conhecido sem o comparecimento pessoal do acusado ou de interposta pessoa a que se refere o caput deste artigo, podendo o juiz determinar a prática de atos necessários à conservação de bens, direitos ou valores, sem prejuízo do disposto no § 1º."],"origin":"authorial","question":{"statement":"§ 3º Nenhum pedido de liberação será conhecido sem o comparecimento pessoal do acusado ou de interposta pessoa a que se refere o caput deste artigo, podendo o juiz determinar a prática de atos necessários à conservação de bens, direitos ou valores, sem prejuízo do disposto no § 1º.","answer":true,"explanation":"O pedido de liberação exige comparecimento pessoal do acusado ou interposta pessoa, com atos de conservação possíveis.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0352","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 8º","number":"Art. 8º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 8º O juiz determinará, na hipótese de existência de tratado ou convenção internacional e por solicitação de autoridade estrangeira competente, medidas assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos no art. 1º praticados no estrangeiro."],"origin":"authorial","question":{"statement":"Art. 8º O juiz determinará, na hipótese de existência de tratado ou convenção internacional e por solicitação de autoridade estrangeira competente, medidas assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos no art. 1º praticados no estrangeiro.","answer":true,"explanation":"A medida por cooperação internacional exige tratado ou convenção e pedido de autoridade estrangeira competente.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0353","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 8º, § 1º","number":"Art. 8º, § 1º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 8º O juiz determinará, na hipótese de existência de tratado ou convenção internacional e por solicitação de autoridade estrangeira competente, medidas assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos no art. 1º praticados no estrangeiro.\n§ 1º Aplica-se o disposto neste artigo, independentemente de tratado ou convenção internacional, quando o governo do país da autoridade solicitante prometer reciprocidade ao Brasil."],"origin":"authorial","question":{"statement":"Art. 8º O juiz determinará, na hipótese de existência de tratado ou convenção internacional e por solicitação de autoridade estrangeira competente, medidas assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos no art. 1º praticados no estrangeiro.\n§ 1º Aplica-se o disposto neste artigo, somente mediante tratado ou convenção internacional, quando o governo do país da autoridade solicitante prometer reciprocidade ao Brasil.","answer":false,"explanation":"A reciprocidade prometida permite a aplicação sem tratado ou convenção.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0354","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 8º, § 2º","number":"Art. 8º, § 2º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 2º Na falta de tratado ou convenção, os bens, direitos ou valores privados sujeitos a medidas assecuratórias por solicitação de autoridade estrangeira competente ou os recursos provenientes da sua alienação serão repartidos entre o Estado requerente e o Brasil, na proporção de metade, ressalvado o direito do lesado ou de terceiro de boa-fé."],"origin":"authorial","question":{"statement":"§ 2º Na falta de tratado ou convenção, os bens, direitos ou valores privados sujeitos a medidas assecuratórias por solicitação de autoridade estrangeira competente ou os recursos provenientes da sua alienação serão repartidos entre o Estado requerente e o Brasil, na proporção de metade, ressalvado o direito do lesado ou de terceiro de boa-fé.","answer":true,"explanation":"Na ausência de tratado, a divisão por metade preserva o direito do lesado ou de terceiro de boa-fé.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0355","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, inc. I","number":"Art. 9º, inc. I","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nI - a captação, intermediação e aplicação de recursos financeiros de terceiros, em moeda nacional ou estrangeira;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, exclusivamente em caráter permanente, como atividade principal ou acessória, cumulativamente ou não:\nI - a captação, intermediação e aplicação de recursos financeiros de terceiros, em moeda nacional ou estrangeira;","answer":false,"explanation":"As obrigações alcançam atividade permanente ou eventual.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0356","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, inc. II","number":"Art. 9º, inc. II","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nII – a compra e venda de moeda estrangeira ou ouro como ativo financeiro ou instrumento cambial;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nII – a compra e venda de moeda estrangeira ou ouro como ativo financeiro ou instrumento cambial;","answer":true,"explanation":"A compra e venda de moeda estrangeira ou ouro como ativo financeiro ou instrumento cambial está abrangida.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0358","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. I","number":"Art. 9º, Parágrafo único, inc. I","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nI – as bolsas de valores, as bolsas de mercadorias ou futuros e os sistemas de negociação do mercado de balcão organizado;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nI – as bolsas de valores, as bolsas de mercadorias ou futuros e os sistemas de negociação do mercado de balcão organizado;","answer":true,"explanation":"Bolsas e sistemas de negociação do mercado de balcão organizado estão sujeitos às obrigações.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0359","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. II","number":"Art. 9º, Parágrafo único, inc. II","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nII - as seguradoras, as corretoras de seguros e as entidades de previdência complementar ou de capitalização;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nII - as seguradoras, as corretoras de seguros e as entidades de previdência pública ou de capitalização;","answer":false,"explanation":"A lista inclui previdência complementar, ao lado das seguradoras e corretoras.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0360","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. III","number":"Art. 9º, Parágrafo único, inc. III","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nIII - as administradoras de cartões de credenciamento ou cartões de crédito, bem como as administradoras de consórcios para aquisição de bens ou serviços;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nIII - as administradoras de cartões de credenciamento ou cartões de crédito, bem como as administradoras de consórcios para aquisição de bens ou serviços;","answer":true,"explanation":"Administradoras de cartões e de consórcios para aquisição de bens ou serviços integram a lista.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0362","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. V","number":"Art. 9º, Parágrafo único, inc. V","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nV - as empresas de arrendamento mercantil (leasing), as empresas de fomento comercial (factoring) e as Empresas Simples de Crédito (ESC);"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nV - as empresas de arrendamento mercantil (leasing), as empresas de fomento comercial (factoring) e as Empresas Simples de Crédito (ESC);","answer":true,"explanation":"Empresas de leasing, factoring e Empresas Simples de Crédito estão expressamente abrangidas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0363","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. VI","number":"Art. 9º, Parágrafo único, inc. VI","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nVI - as sociedades que, mediante sorteio, método assemelhado, exploração de loterias, inclusive de apostas de quota fixa, ou outras sistemáticas de captação de apostas com pagamento de prêmios, realizem distribuição de dinheiro, de bens móveis, de bens imóveis e de outras mercadorias ou serviços, bem como concedam descontos na sua aquisição ou contratação;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nVI - as sociedades que, mediante sorteio, método assemelhado, exploração de loterias, excluídas as apostas de quota fixa, ou outras sistemáticas de captação de apostas com pagamento de prêmios, realizem distribuição de dinheiro, de bens móveis, de bens imóveis e de outras mercadorias ou serviços, bem como concedam descontos na sua aquisição ou contratação;","answer":false,"explanation":"As apostas de quota fixa estão expressamente abrangidas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0364","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. VII","number":"Art. 9º, Parágrafo único, inc. VII","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nVII - as filiais ou representações de entes estrangeiros que exerçam no Brasil qualquer das atividades listadas neste artigo, ainda que de forma eventual;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nVII - as filiais ou representações de entes estrangeiros que exerçam no Brasil qualquer das atividades listadas neste artigo, ainda que de forma eventual;","answer":true,"explanation":"Filiais ou representações de entes estrangeiros são incluídas se exercerem as atividades no Brasil, ainda que eventualmente.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0366","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. IX","number":"Art. 9º, Parágrafo único, inc. IX","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nIX - as pessoas físicas ou jurídicas, nacionais ou estrangeiras, que operem no Brasil como agentes, dirigentes, procuradoras, comissionárias ou por qualquer forma representem interesses de ente estrangeiro que exerça qualquer das atividades referidas neste artigo;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nIX - as pessoas físicas ou jurídicas, nacionais ou estrangeiras, que operem no Brasil como agentes, dirigentes, procuradoras, comissionárias ou por qualquer forma representem interesses de ente estrangeiro que exerça qualquer das atividades referidas neste artigo;","answer":true,"explanation":"A representação no Brasil de ente estrangeiro com atividade listada submete a pessoa às obrigações.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0368","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XI","number":"Art. 9º, Parágrafo único, inc. XI","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXI - as pessoas físicas ou jurídicas que comercializem jóias, pedras e metais preciosos, objetos de arte e antigüidades."],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXI - as pessoas físicas ou jurídicas que comercializem jóias, pedras e metais preciosos, objetos de arte e antigüidades.","answer":true,"explanation":"Comercialização de joias, metais preciosos, objetos de arte e antiguidades consta do inciso XI.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0369","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XII","number":"Art. 9º, Parágrafo único, inc. XII","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXII - as pessoas físicas ou jurídicas que comercializem bens de luxo ou de alto valor, intermedeiem a sua comercialização ou exerçam atividades que envolvam grande volume de recursos em espécie;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXII - as pessoas físicas ou jurídicas que comercializem exclusivamente joias e pedras preciosas, intermedeiem a sua comercialização ou exerçam atividades que envolvam grande volume de recursos em espécie;","answer":false,"explanation":"O inciso XII alcança bens de luxo ou alto valor, além da intermediação e atividades em espécie.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0370","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIII","number":"Art. 9º, Parágrafo único, inc. XIII","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIII - as juntas comerciais e os registros públicos;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIII - as juntas comerciais e os registros públicos;","answer":true,"explanation":"Juntas comerciais e registros públicos também estão sujeitos às obrigações de identificação e comunicação.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0371","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIV, al. a","number":"Art. 9º, Parágrafo único, inc. XIV, al. a","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\na) de compra e venda de imóveis, estabelecimentos comerciais ou industriais ou participações societárias de qualquer natureza;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, somente de modo habitual, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\na) de compra e venda de imóveis, estabelecimentos comerciais ou industriais ou participações societárias de qualquer natureza;","answer":false,"explanation":"A prestação eventual de assessoria ou serviços listados também é alcançada.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0372","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIV, al. b","number":"Art. 9º, Parágrafo único, inc. XIV, al. b","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\nb) de gestão de fundos, valores mobiliários ou outros ativos;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\nb) de gestão de fundos, valores mobiliários ou outros ativos;","answer":true,"explanation":"A gestão de fundos, valores mobiliários e outros ativos é operação incluída no inciso XIV.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0374","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIV, al. d","number":"Art. 9º, Parágrafo único, inc. XIV, al. d","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\nd) de criação, exploração ou gestão de sociedades de qualquer natureza, fundações, fundos fiduciários ou estruturas análogas;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\nd) de criação, exploração ou gestão de sociedades de qualquer natureza, fundações, fundos fiduciários ou estruturas análogas;","answer":true,"explanation":"Criação, exploração e gestão de sociedades, fundações e fundos fiduciários integram o alcance.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0375","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIV, al. e","number":"Art. 9º, Parágrafo único, inc. XIV, al. e","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\ne) financeiras, societárias ou imobiliárias; e"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\ne) financeiras e societárias, excluídas as imobiliárias; e","answer":false,"explanation":"As operações imobiliárias também integram o inciso XIV.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0376","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIV, al. f","number":"Art. 9º, Parágrafo único, inc. XIV, al. f","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\nf) de alienação ou aquisição de direitos sobre contratos relacionados a atividades desportivas ou artísticas profissionais;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIV - as pessoas físicas ou jurídicas que prestem, mesmo que eventualmente, serviços de assessoria, consultoria, contadoria, auditoria, aconselhamento ou assistência, de qualquer natureza, em operações:\nf) de alienação ou aquisição de direitos sobre contratos relacionados a atividades desportivas ou artísticas profissionais;","answer":true,"explanation":"Alienação ou aquisição de direitos contratuais ligados a atividades desportivas ou artísticas profissionais está incluída.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0378","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XVI","number":"Art. 9º, Parágrafo único, inc. XVI","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXVI - as empresas de transporte e guarda de valores;"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXVI - as empresas de transporte e guarda de valores;","answer":true,"explanation":"Transporte e guarda de valores estão sujeitos às obrigações dos arts. 10 e 11.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0379","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XVII","number":"Art. 9º, Parágrafo único, inc. XVII","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXVII - as pessoas físicas ou jurídicas que comercializem bens de alto valor de origem rural ou animal ou intermedeiem a sua comercialização; e"],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXVII - as pessoas físicas ou jurídicas que comercializem apenas bens urbanos de alto valor ou intermedeiem a sua comercialização; e","answer":false,"explanation":"O inciso XVII trata de bens de alto valor de origem rural ou animal.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0380","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XVIII","number":"Art. 9º, Parágrafo único, inc. XVIII","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXVIII - as dependências no exterior das entidades mencionadas neste artigo, por meio de sua matriz no Brasil, relativamente a residentes no País."],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXVIII - as dependências no exterior das entidades mencionadas neste artigo, por meio de sua matriz no Brasil, relativamente a residentes no País.","answer":true,"explanation":"Dependências no exterior são alcançadas por intermédio da matriz brasileira, relativamente a residentes no país.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0381","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 9º, Parágrafo único, inc. XIX","number":"Art. 9º, Parágrafo único, inc. XIX","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIX - as prestadoras de serviços de ativos virtuais."],"origin":"authorial","question":{"statement":"Art. 9º Sujeitam-se às obrigações referidas nos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, cumulativamente ou não:\nParágrafo único. Sujeitam-se às mesmas obrigações:\nXIX - as prestadoras de serviços exclusivamente de moeda estrangeira.","answer":false,"explanation":"Prestadoras de serviços de ativos virtuais foram incluídas entre as obrigadas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0382","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, inc. I","number":"Art. 10, inc. I","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 10. As pessoas referidas no art. 9º:\nI - identificarão seus clientes e manterão cadastro atualizado, nos termos de instruções emanadas das autoridades competentes;"],"origin":"authorial","question":{"statement":"Art. 10. As pessoas referidas no art. 9º:\nI - identificarão seus clientes e manterão cadastro atualizado, nos termos de instruções emanadas das autoridades competentes;","answer":true,"explanation":"O cadastro atualizado e a identificação dos clientes seguem instruções das autoridades competentes.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0384","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, inc. III","number":"Art. 10, inc. III","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 10. As pessoas referidas no art. 9º:\nIII - deverão adotar políticas, procedimentos e controles internos, compatíveis com seu porte e volume de operações, que lhes permitam atender ao disposto neste artigo e no art. 11, na forma disciplinada pelos órgãos competentes;"],"origin":"authorial","question":{"statement":"Art. 10. As pessoas referidas no art. 9º:\nIII - deverão adotar políticas, procedimentos e controles internos, compatíveis com seu porte e volume de operações, que lhes permitam atender ao disposto neste artigo e no art. 11, na forma disciplinada pelos órgãos competentes;","answer":true,"explanation":"Políticas e controles internos são proporcionais ao porte e volume das operações e atendem aos arts. 10 e 11.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0385","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, inc. IV","number":"Art. 10, inc. IV","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 10. As pessoas referidas no art. 9º:\nIV - deverão cadastrar-se e manter seu cadastro atualizado no órgão regulador ou fiscalizador e, na falta deste, no Conselho de Controle de Atividades Financeiras (Coaf), na forma e condições por eles estabelecidas;"],"origin":"authorial","question":{"statement":"Art. 10. As pessoas referidas no art. 9º:\nIV - deverão cadastrar-se e manter seu cadastro atualizado no órgão regulador ou fiscalizador e, na falta deste, no Banco Central do Brasil, na forma e condições por eles estabelecidas;","answer":false,"explanation":"Sem órgão regulador ou fiscalizador, o cadastro é feito no Coaf.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0386","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, inc. V","number":"Art. 10, inc. V","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 10. As pessoas referidas no art. 9º:\nV - deverão atender às requisições formuladas pelo Coaf na periodicidade, forma e condições por ele estabelecidas, cabendo-lhe preservar, nos termos da lei, o sigilo das informações prestadas."],"origin":"authorial","question":{"statement":"Art. 10. As pessoas referidas no art. 9º:\nV - deverão atender às requisições formuladas pelo Coaf na periodicidade, forma e condições por ele estabelecidas, cabendo-lhe preservar, nos termos da lei, o sigilo das informações prestadas.","answer":true,"explanation":"As requisições do Coaf devem ser atendidas, preservado o sigilo das informações prestadas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0387","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, § 1º","number":"Art. 10, § 1º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 1º Na hipótese de o cliente constituir-se em pessoa jurídica, a identificação referida no inciso I deste artigo deverá abranger as pessoas físicas autorizadas a representá-la, bem como seus proprietários."],"origin":"authorial","question":{"statement":"§ 1º Na hipótese de o cliente constituir-se em pessoa jurídica, a identificação referida no inciso I deste artigo deverá abranger as pessoas físicas autorizadas a representá-la, bem como apenas seus administradores.","answer":false,"explanation":"A identificação da pessoa jurídica também alcança seus proprietários.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0388","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, § 2º","number":"Art. 10, § 2º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 2º Os cadastros e registros referidos nos incisos I e II deste artigo deverão ser conservados durante o período mínimo de cinco anos a partir do encerramento da conta ou da conclusão da transação, prazo este que poderá ser ampliado pela autoridade competente."],"origin":"authorial","question":{"statement":"§ 2º Os cadastros e registros referidos nos incisos I e II deste artigo deverão ser conservados durante o período mínimo de cinco anos a partir do encerramento da conta ou da conclusão da transação, prazo este que poderá ser ampliado pela autoridade competente.","answer":true,"explanation":"O período mínimo de guarda é de cinco anos após encerramento da conta ou conclusão da transação, ampliável pela autoridade.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0389","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 10, § 3º","number":"Art. 10, § 3º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 3º O registro referido no inciso II deste artigo será efetuado também quando a pessoa física ou jurídica, seus entes ligados, houver realizado, em um mesmo mês-calendário, operações com uma mesma pessoa, conglomerado ou grupo que, em seu conjunto, ultrapassem o limite fixado pela autoridade competente."],"origin":"authorial","question":{"statement":"§ 3º O registro referido no inciso II deste artigo será efetuado também quando a pessoa física ou jurídica, seus entes ligados, houver realizado, em um mesmo ano-calendário, operações com uma mesma pessoa, conglomerado ou grupo que, em seu conjunto, ultrapassem o limite fixado pela autoridade competente.","answer":false,"explanation":"A soma para registro considera o mesmo mês-calendário.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0390","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 11, inc. I","number":"Art. 11, inc. I","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 11. As pessoas referidas no art. 9º:\nI - dispensarão especial atenção às operações que, nos termos de instruções emanadas das autoridades competentes, possam constituir-se em sérios indícios dos crimes previstos nesta Lei, ou com eles relacionar-se;"],"origin":"authorial","question":{"statement":"Art. 11. As pessoas referidas no art. 9º:\nI - dispensarão especial atenção às operações que, nos termos de instruções emanadas das autoridades competentes, possam constituir-se em sérios indícios dos crimes previstos nesta Lei, ou com eles relacionar-se;","answer":true,"explanation":"Atenção especial é dada a operações que constituam sérios indícios dos crimes ou se relacionem a eles.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0391","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 11, inc. II","number":"Art. 11, inc. II","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 11. As pessoas referidas no art. 9º:\nII - deverão comunicar ao Coaf, abstendo-se de dar ciência de tal ato a qualquer pessoa, inclusive àquela à qual se refira a informação, no prazo de 24 (vinte e quatro) horas, a proposta ou realização:"],"origin":"authorial","question":{"statement":"Art. 11. As pessoas referidas no art. 9º:\nII - deverão comunicar ao Coaf, abstendo-se de dar ciência de tal ato a qualquer pessoa, inclusive àquela à qual se refira a informação, no prazo de 72 (setenta e duas) horas, a proposta ou realização:","answer":false,"explanation":"A comunicação ao Coaf ocorre em vinte e quatro horas, sem dar ciência a qualquer pessoa.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0392","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 11, inc. II, al. a","number":"Art. 11, inc. II, al. a","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 11. As pessoas referidas no art. 9º:\nII - deverão comunicar ao Coaf, abstendo-se de dar ciência de tal ato a qualquer pessoa, inclusive àquela à qual se refira a informação, no prazo de 24 (vinte e quatro) horas, a proposta ou realização:\na) de todas as transações referidas no inciso II do art. 10, acompanhadas da identificação de que trata o inciso I do mencionado artigo; e"],"origin":"authorial","question":{"statement":"Art. 11. As pessoas referidas no art. 9º:\nII - deverão comunicar ao Coaf, abstendo-se de dar ciência de tal ato a qualquer pessoa, inclusive àquela à qual se refira a informação, no prazo de 24 (vinte e quatro) horas, a proposta ou realização:\na) de todas as transações referidas no inciso II do art. 10, acompanhadas da identificação de que trata o inciso I do mencionado artigo; e","answer":true,"explanation":"A comunicação acompanha a identificação do art. 10, I, para as transações enumeradas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0394","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 11, inc. III","number":"Art. 11, inc. III","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 11. As pessoas referidas no art. 9º:\nIII - deverão comunicar ao órgão regulador ou fiscalizador da sua atividade ou, na sua falta, ao Coaf, na periodicidade, forma e condições por eles estabelecidas, a não ocorrência de propostas, transações ou operações passíveis de serem comunicadas nos termos do inciso II."],"origin":"authorial","question":{"statement":"Art. 11. As pessoas referidas no art. 9º:\nIII - deverão comunicar ao órgão regulador ou fiscalizador da sua atividade ou, na sua falta, ao Coaf, na periodicidade, forma e condições por eles estabelecidas, a não ocorrência de propostas, transações ou operações passíveis de serem comunicadas nos termos do inciso II.","answer":true,"explanation":"A ausência de operação comunicável também deve ser comunicada ao regulador ou, na falta dele, ao Coaf.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0396","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 11, § 2º","number":"Art. 11, § 2º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 2º As comunicações de boa-fé, feitas na forma prevista neste artigo, não acarretarão responsabilidade civil ou administrativa."],"origin":"authorial","question":{"statement":"§ 2º As comunicações de boa-fé, feitas na forma prevista neste artigo, não acarretarão responsabilidade civil ou administrativa.","answer":true,"explanation":"Comunicações de boa-fé na forma do artigo não geram responsabilidade civil ou administrativa.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}},{"id":"LED-20261009-0398","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, inc. I","number":"Art. 12, inc. I","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nI - advertência;"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, sempre cumulativamente, pelas autoridades competentes, as seguintes sanções:\nI - advertência;","answer":false,"explanation":"As sanções administrativas podem ser aplicadas cumulativamente ou não.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0399","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, inc. II, al. a","number":"Art. 12, inc. II, al. a","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nII - multa pecuniária variável não superior:\na) ao dobro do valor da operação;"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nII - multa pecuniária variável não superior:\na) ao dobro do valor da operação;","answer":true,"explanation":"Um dos limites alternativos da multa é o dobro do valor da operação.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0400","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, inc. II, al. b","number":"Art. 12, inc. II, al. b","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nII - multa pecuniária variável não superior:\nb) ao dobro do lucro real obtido ou que presumivelmente seria obtido pela realização da operação; ou"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nII - multa pecuniária variável não superior:\nb) ao dobro do lucro real apenas efetivamente obtido pela realização da operação; ou","answer":false,"explanation":"O teto da multa considera também lucro presumivelmente obtido.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0401","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, inc. II, al. c","number":"Art. 12, inc. II, al. c","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nII - multa pecuniária variável não superior:\nc) ao valor de R$ 20.000.000,00 (vinte milhões de reais);"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nII - multa pecuniária variável não superior:\nc) ao valor de R$ 20.000.000,00 (vinte milhões de reais);","answer":true,"explanation":"O teto monetário alternativo da multa variável é vinte milhões de reais.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0402","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, inc. III","number":"Art. 12, inc. III","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nIII - inabilitação temporária, pelo prazo de até dez anos, para o exercício do cargo de administrador das pessoas jurídicas referidas no art. 9º;"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nIII - inabilitação temporária, pelo prazo mínimo de dez anos, para o exercício do cargo de administrador das pessoas jurídicas referidas no art. 9º;","answer":false,"explanation":"A inabilitação é temporária e tem limite máximo de dez anos.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0403","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, inc. IV","number":"Art. 12, inc. IV","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nIV - cassação ou suspensão da autorização para o exercício de atividade, operação ou funcionamento."],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\nIV - cassação ou suspensão da autorização para o exercício de atividade, operação ou funcionamento.","answer":true,"explanation":"Cassação ou suspensão da autorização são modalidades de sanção administrativa.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0404","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 1º","number":"Art. 12, § 1º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 1º A pena de advertência será aplicada por irregularidade no cumprimento das instruções referidas nos incisos I e II do art. 10."],"origin":"authorial","question":{"statement":"§ 1º A pena de advertência será aplicada por irregularidade no cumprimento das instruções referidas nos incisos III e IV do art. 10.","answer":false,"explanation":"A advertência atende a irregularidade no cumprimento das instruções dos incisos I e II.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0405","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 2º, inc. I","number":"Art. 12, § 2º, inc. I","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nI – deixarem de sanar as irregularidades objeto de advertência, no prazo assinalado pela autoridade competente;"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, exclusivamente por dolo:\nI – deixarem de sanar as irregularidades objeto de advertência, no prazo assinalado pela autoridade competente;","answer":false,"explanation":"A multa pode incidir por culpa ou dolo, nas hipóteses enumeradas.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0406","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 2º, inc. II","number":"Art. 12, § 2º, inc. II","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nII - não cumprirem o disposto nos incisos I a IV do art. 10;"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nII - não cumprirem o disposto nos incisos I a IV do art. 10;","answer":true,"explanation":"O descumprimento dos incisos I a IV do art. 10 integra as causas da multa.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0407","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 2º, inc. III","number":"Art. 12, § 2º, inc. III","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nIII - deixarem de atender, no prazo estabelecido, a requisição formulada nos termos do inciso V do art. 10;"],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nIII - deixarem de atender, independentemente do prazo estabelecido, a requisição formulada nos termos do inciso V do art. 10;","answer":false,"explanation":"A falta de atendimento à requisição deve ser considerada no prazo estabelecido.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0408","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 2º, inc. IV","number":"Art. 12, § 2º, inc. IV","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nIV - descumprirem a vedação ou deixarem de fazer a comunicação a que se refere o art. 11."],"origin":"authorial","question":{"statement":"Art. 12. Às pessoas referidas no art. 9º, bem como aos administradores das pessoas jurídicas, que deixem de cumprir as obrigações previstas nos arts. 10 e 11 serão aplicadas, cumulativamente ou não, pelas autoridades competentes, as seguintes sanções:\n§ 2º A multa será aplicada sempre que as pessoas referidas no art. 9º, por culpa ou dolo:\nIV - descumprirem a vedação ou deixarem de fazer a comunicação a que se refere o art. 11.","answer":true,"explanation":"Violar a vedação ou deixar de comunicar conforme o art. 11 também sujeita à multa.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0409","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 3º","number":"Art. 12, § 3º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 3º A inabilitação temporária será aplicada quando forem verificadas infrações graves quanto ao cumprimento das obrigações constantes desta Lei ou quando ocorrer reincidência específica, devidamente caracterizada em transgressões anteriormente punidas com multa."],"origin":"authorial","question":{"statement":"§ 3º A inabilitação temporária será aplicada quando forem verificadas infrações leves quanto ao cumprimento das obrigações constantes desta Lei ou quando ocorrer reincidência específica, devidamente caracterizada em transgressões anteriormente punidas com multa.","answer":false,"explanation":"A inabilitação requer infrações graves ou reincidência específica descrita no parágrafo.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · alta","origin":"authorial"}},{"id":"LED-20261009-0410","discipline":"penal","topicId":"led-penal-lavagem-9613","subtopic":"Art. 12, § 4º","number":"Art. 12, § 4º","title":"Lei nº 9.613/1998 · Lavagem de Dinheiro","parts":["§ 4º A cassação da autorização será aplicada nos casos de reincidência específica de infrações anteriormente punidas com a pena prevista no inciso III do caput deste artigo."],"origin":"authorial","question":{"statement":"§ 4º A cassação da autorização será aplicada nos casos de reincidência específica de infrações anteriormente punidas com a pena prevista no inciso III do caput deste artigo.","answer":true,"explanation":"A cassação exige reincidência específica após infração anteriormente punida com inabilitação do inciso III.","source":"https://www.planalto.gov.br/ccivil_03/leis/l9613compilado.htm","meta":"LEI EM DIA · média","origin":"authorial"}}];
